  ui_story_5038_50380001_17_dialog_content = "H-Como é que de repente há tantos?",
  ui_story_5038_50380001_18_dialog_content = "Ainda tenho algumas coisas comigo que ainda não contei...",
  ui_story_5038_50380001_19_dialog_content = "Há horários de pico para entrega de cartas, e agora é um período particularmente movimentado.",
