  ui_story_5038_50380001_26_dialog_content = "Uau! Que tipo de lugar é Twin Paviwions Bay? Cadê? Eu nunca estive lá antes!",
  ui_story_5038_50380001_27_dialog_content = "Nesse caso, sinta-se à vontade para aproveitar esta oportunidade para explorar.",
  ui_story_5038_50380001_28_dialog_content = "É uma boa época do ano para visitar Twin Pavilions Bay.",
  ui_story_5038_50380001_29_dialog_content = "Tudo bem! Então eu deveria me preparar para... Ir... Indo!",
  ui_story_5038_50380001_30_dialog_content = "<color=#e8d9bb>5 dias depois</color>",
  ui_story_5038_50380001_31_dialog_content = "<size=50>Wahhhhhhh—</size>",
  ui_story_5038_50380001_32_dialog_content = "<size=50>PlayerName! H-Ajude-me!</size>",
  ui_story_5038_50380001_33_dialog_content = "Huh? Tweety? O que está errado?!",
  ui_story_5038_50380001_34_dialog_content = "O que aconteceu?",
