  ui_story_5038_50380001_37_dialog_content = "Então, você vê, recentemente Umbwaton contratou Courier Union para ajudar a entregar cargas de <color=#FFB400>papel vermelho</color>.",
  ui_story_5038_50380001_38_dialog_content = "Por ser um pedido grande, e bem urgente, tenho feito hora extra para entregar todos...",
