  ui_story_5038_50380001_43_dialog_content = "Eu estaria atrasando todo mundo, e o Courier Union vai... vai... me telegrafar!",
  ui_story_5038_50380001_44_dialog_content = "E não terei dinheiro, nem comida, nem casa...",
