  ui_story_5038_50380001_46_dialog_content = "Tão drástico?!",
  ui_story_5038_50380001_47_dialog_content = "Então... Piu-Piu quer pedir sua ajuda, senhor!",
  ui_story_5038_50380001_48_dialog_content = "Eu poderia contratar Sowoz para me ajudar?",
  ui_story_5038_50380001_49_dialog_content = "Eu vou pagar! Quando eu receber o salawy deste mês, darei tudo a você!",
  ui_story_5038_50380001_50_dialog_content = "Você não precisa se preocupar em pagar. Ficarei feliz em ajudá-lo.",
  ui_story_5038_50380001_51_dialog_content = "Como o tempo parece ser essencial, podemos ir agora!",
  ui_story_5038_50380001_52_dialog_content = "Onde você está indo?",
  ui_story_5038_50380001_53_dialog_content = "Uma cidade hawbour chamada Twin Pavilions Bay.",
  ui_story_5038_50380001_54_dialog_content = "Acontece que Soroz está bem acima da bacia do rio Gold agora.",
  ui_story_5038_50380001_55_dialog_content = "Se seguirmos o rio rio abaixo até avistarmos o oceano, é lá que estará a Twin Pavilions Bay.",
  ui_story_5038_50380001_56_dialog_content = "Você esteve lá?!",
  ui_story_5038_50380001_57_dialog_content = "Não, não pessoalmente. Acabei de ler sobre isso na biblioteca de Lumopolis.",
  ui_story_5038_50380001_58_dialog_content = "Situa-se ao longo do estuário do rio Gold e tem uma cultura única. É freqüentemente citado em muitos livros diferentes.",
  ui_story_5038_50380001_59_dialog_content = "Além disso, você pode estar familiarizado com suas origens.",
  ui_story_5038_50380001_60_dialog_content = "Como assim?",
  ui_story_5038_50380001_61_dialog_content = "<color=#FFB400>A Guilda Lin</color> fundou a cidade.",
  ui_story_5038_50380001_62_dialog_content = "A Guilda Lin?! Eles não estão em Umbraton?",
  ui_story_5038_50380001_63_dialog_content = "Umbraton é onde eles realizam negócios, mas Twin Pavilions Bay é onde eles chamam de lar.",
  ui_story_5038_50380001_64_dialog_content = "Não se esqueça, a Lin Guild vem de outro continente distante ao leste.",
  ui_story_5038_50380001_65_dialog_content = "Antes de aparecerem, o estuário do rio Gold abrigava apenas algumas pequenas e empobrecidas vilas de pescadores.",
  ui_story_5038_50380001_66_dialog_content = "Um dia, um enorme navio chegou às suas costas e trouxe alguns membros da Lin Guild para Astra.",
  ui_story_5038_50380001_67_dialog_content = "Eles descarregaram um monte de mercadorias do Extremo Oriente, que então passaram a transportar ao longo do rio Gold para Umbraton.",
  ui_story_5038_50380001_68_dialog_content = "Eles tiveram que contratar trabalhadores e precisavam de lugares para se hospedar e comer. Com o tempo, os aldeões locais gradualmente encontraram novos empregos.",
  ui_story_5038_50380001_69_dialog_content = "O porto prosperou com o dinheiro que a Lin Guild ganhou.",
  ui_story_5038_50380001_70_dialog_content = "Os habitantes locais receberam bem a influência das culturas orientais e construíram uma cidade no estilo de Longzhou.",
  ui_story_5038_50380001_71_dialog_content = "A partir de então, a Lin Guild se estabeleceu e viveu ao lado dos habitantes locais em harmonia até hoje.",
  ui_story_5038_50380001_72_dialog_content = "Então esse é o Twin Pavilions Bay, nosso destino.",
  ui_story_5038_50380001_73_dialog_content = "Uau, uma cidade construída por mercadores! Eu nunca vi um lugar assim antes.",
  ui_story_5038_50380001_74_dialog_content = "Vai ser muito caro lá? Não temos muitas economias.",
  ui_story_5038_50380001_75_dialog_content = "Ouvi dizer que em lugares ricos, você tem que pagar pelo estacionamento de veículos e outras coisas. Você pode imaginar quanto custaria estacionar algo como Soroz?",
  ui_story_5038_50380001_76_dialog_content = "Bem, eu não me preocuparia com taxas de estacionamento, mas para evitar problemas desnecessários...",
  ui_story_5038_50380001_77_dialog_content = "Eu recomendaria pousar Soroz em algum lugar fora da cidade, PlayerName.",
  ui_story_5038_50380001_78_dialog_content = "Bom ponto.",
  ui_story_5038_50380001_79_dialog_content = "Veja! Acho que estamos quase lá!",
  ui_story_5038_50380001_80_dialog_content = "Nossa... Até as ruas são lindas!",
  ui_story_5038_50380001_81_dialog_content = "Sim! Há vermelho em todos os lugares, tão pwetty!",
  ui_story_5038_50380001_82_dialog_content = "Parece um lugar muito feliz e animado.",
  ui_story_5038_50380001_83_dialog_content = "Sim. Segundo os livros, toda a cidade tem o estilo de um continente completamente diferente.",
  ui_story_5038_50380001_84_dialog_content = "Em algum lugar do outro lado do oceano, é assim que suas casas e ruas são.",
  ui_story_5038_50380001_85_dialog_content = "É como se o continente do outro lado fosse um mundo completamente diferente.",
  ui_story_5038_50380001_86_dialog_content = "E, e, aposto que eles também têm feriados totalmente diferentes!",
  ui_story_5038_50380001_87_dialog_content = "Todo esse papel vermelho que estou entregando esses dias deve ser para o festival tradicional.",
  ui_story_5038_50380001_88_dialog_content = "Como foi chamado mesmo...?",
  ui_story_5038_50380001_89_dialog_content = "Feliz Ano Novo! Você está aqui para o Festival da Primavera?",
  ui_story_5038_50380001_90_dialog_content = "Oh sim! Chama-se Festival Spwing!",
  ui_story_5038_50380001_91_dialog_content = "Atualmente, não encontramos muitos rostos desconhecidos em Twin Pavilions Bay. Você é de fora da cidade?",
  ui_story_5038_50380001_92_dialog_content = "Eu posso dizer só de olhar para suas roupas.",
  ui_story_5038_50380001_93_dialog_content = "Momento perfeito, senhor! Aqui está o papel vermelho que sua loja encomendou. Por favor, assine aqui!",
  ui_story_5038_50380001_94_dialog_content = "Obrigado. E lá estava eu, preocupada que não chegasse a tempo!",
  ui_story_5038_50380001_95_dialog_content = "Desculpe-me por perguntar, mas eu queria saber por que você pediu tanto papel vermelho de Umbraton?",
  ui_story_5038_50380001_96_dialog_content = "Eles são importantes para dar as boas-vindas ao ano novo.",
  ui_story_5038_50380001_97_dialog_content = "É uma tradição em Longzhou pendurar dois pedaços de papel vermelho com a palavra \"Bênção\" em suas portas para o Festival da Primavera.",
  ui_story_5038_50380001_98_dialog_content = "Eles nos ajudam a orar por boa sorte e prosperidade no próximo ano.",
  ui_story_5038_50380001_99_dialog_content = "Longzhou - esse é o nome do continente oriental?",
  ui_story_5038_50380001_100_dialog_content = "No local. Parece que vocês não estão muito familiarizados com muitos de nós.",
  ui_story_5038_50380001_101_dialog_content = "Aqueles de nós que moram aqui em Twin Pavilions Bay são bastante autossuficientes e não costumam interagir com lugares mais distantes do interior.",
  ui_story_5038_50380001_102_dialog_content = "Poderíamos, e teríamos, facilmente comprado este papel vermelho em nossas próprias lojas locais.",
  ui_story_5038_50380001_103_dialog_content = "Mas este ano ... houve um pouco de situação.",
  ui_story_5038_50380001_104_dialog_content = "Que tipo de situação?",
  ui_story_5038_50380001_105_dialog_content = "Nossas lojas estão todas sem estoque. Não só do papel, mas de tudo, inclusive do necessário.",
  ui_story_5038_50380001_106_dialog_content = "Como assim... Você está mesmo sem reservas?",
  ui_story_5038_50380001_107_dialog_content = "Normalmente, os membros da Lin Guild <color=#FFB400>navio de abastecimento</color> vem uma vez a cada poucos meses de Longzhou.",
  ui_story_5038_50380001_108_dialog_content = "Mas não vimos nenhum vestígio disso no último meio ano. Não temos ideia do que aconteceu.",
  ui_story_5038_50380001_109_dialog_content = "As lojas que dependem do navio de suprimentos para comprar estoque não podem durar para sempre.",
  ui_story_5038_50380001_110_dialog_content = "O papel vermelho faz parte do que falta. Portanto, não tivemos escolha a não ser pedir alguns de Umbraton.",
  ui_story_5038_50380001_111_dialog_content = "(Ah, então foi isso que aconteceu. Parece preocupante...)",
  ui_story_5038_50380001_112_dialog_content = "(A Lin Guild até me ajudou antes, mas não tenho ideia de como eles estão.)",
  ui_story_5038_50380001_113_dialog_content = "Ah... eu conheço a sensação. Deve sentir falta do sabor de casa, senhor.",
  ui_story_5038_50380001_114_dialog_content = "<color=#e8d9bb>BOM... BOM...</color>",
  ui_story_5038_50380001_115_dialog_content = "O que foi?",
  ui_story_5038_50380001_116_dialog_content = "Parece uma buzina vindo do porto...",
  ui_story_5038_50380001_117_dialog_content = "Isso é... a sirene de um navio!",
  ui_story_5038_50380001_118_dialog_content = "Claro que é! Eu reconheceria uma sirene em qualquer lugar!",
  ui_story_5038_50380001_119_dialog_content = "Há um navio no porto! Poderia ser a Lin Guild?",
  ui_story_5038_50380001_120_dialog_content = "É o navio de abastecimento da Lin Guild?",
  ui_story_5038_50380001_121_dialog_content = "Parece que chegamos na hora certa.",
  ui_story_5038_50380001_122_dialog_content = "É o navio de abastecimento, é mesmo!",
  ui_story_5038_50380001_123_dialog_content = "Oh, graças a Deus! Eu estava preocupado em não conseguir nada para o Festival da Primavera!",
  ui_story_5038_50380001_124_dialog_content = "Alguém está vindo!",
  ui_story_5038_50380001_125_dialog_content = "...",
  ui_story_5038_50380001_126_dialog_content = "(Há um homem estranho ali, que não parece nem um pouco animado.)",
  ui_story_5038_50380001_127_dialog_content = "Fora do caminho! Deixe-o passar! Abra espaço para o cara velho, fraco, doente e deficiente!",
  ui_story_5038_50380001_128_dialog_content = "Você, jovem! Você está bloqueando as rodas!",
  ui_story_5038_50380001_129_dialog_content = "A-Aquilo em que ele está sentado é... uma cadeira de rodas?!",
  ui_story_5038_50380001_130_dialog_content = "Me desculpe! Onde estão minhas maneiras?",
  ui_story_5038_50380001_131_dialog_content = "Sem problema. Eu já disse muitas vezes, Liqing, rapaz, para não rotular comigo tudo isso...",
  ui_story_5038_50380001_132_dialog_content = "Ainda não estou morto, meu cérebro está funcionando muito bem.",
  ui_story_5038_50380001_133_dialog_content = "Hahahaha! Eu só queria nos passar pela multidão mais rápido!",
  ui_story_5038_50380001_134_dialog_content = "Eu estive esperando para sempre para comprar as incríveis ervas medicinais de Longzhou!",
  ui_story_5038_50380001_135_dialog_content = "Deixe-me passar! Eu primeiro! Eu trouxe Nightium!",
  ui_story_5038_50380001_136_dialog_content = "Subir! Continue!",
  ui_story_5038_50380001_137_dialog_content = "Huh? Não empurre!",
  ui_story_5038_50380001_138_dialog_content = "Silêncio, todos.",
  ui_story_5038_50380001_139_dialog_content = "...",
  ui_story_5038_50380001_140_dialog_content = "O Shadowind realmente teve uma reforma. Até o capitão é uma cara nova.",
  ui_story_5038_50380001_141_dialog_content = "Eu sou Yuebai, o novo capitão do navio mercante da Lin Guild, o Shadowind.",
  ui_story_5038_50380001_142_dialog_content = "... Parece que todos vocês reconhecem os membros Lin que normalmente viajam com este navio.",
  ui_story_5038_50380001_143_dialog_content = "O último semestre viu algumas mudanças estratégicas na família Lin, que resultaram na impossibilidade de enviar o navio para o mar.",
  ui_story_5038_50380001_144_dialog_content = "Tenho certeza de que cortar a rota entre Longzhou e Astra por tanto tempo tem sido difícil.",
  ui_story_5038_50380001_145_dialog_content = "Mas isso agora é tudo no passado. Agora que o Shadowind me tem no comando,",
  ui_story_5038_50380001_146_dialog_content = "a rota Longzhou-Astra será oficialmente <color=#FFB400>retomar negócios</color>.",
  ui_story_5038_50380001_147_dialog_content = "... Eles realmente fizeram isso, Zhong Xu! Eles realmente vieram!",
  ui_story_5038_50380001_148_dialog_content = "Podemos voltar agora!",
  ui_story_5038_50380001_149_dialog_content = "...",
  ui_story_5038_50380001_150_dialog_content = "Podemos voltar para Longzhou? Bem desse jeito? Mas não me preparei...",
  ui_story_5038_50380001_151_dialog_content = "Sim, já tenho reuniões agendadas com meus parceiros de negócios. Duvido que consiga sair deles...",
  ui_story_5038_50380001_152_dialog_content = "Quem quiser voltar a Longzhou só precisa comprar uma passagem.",
  ui_story_5038_50380001_153_dialog_content = "No entanto, como a rota de retorno foi alterada, esteja ciente de certos <color=#FFB400>riscos</color>.",
  ui_story_5038_50380001_154_dialog_content = "Esqueça isso! Qualquer navio Lin é confiável! Três ingressos para mim, por favor!",
  ui_story_5038_50380001_155_dialog_content = "Dê-me um primeiro! Não quero ter que brigar por eles...",
  ui_story_5038_50380001_156_dialog_content = "Por favor, todos, acalmem-se. Não há necessidade de entrar em pânico.",
  ui_story_5038_50380001_157_dialog_content = "Ainda falta um tempinho para a nossa viagem de volta.",
  ui_story_5038_50380001_158_dialog_content = "Eu poderia dizer que todos aqui eram boas pessoas desde o segundo em que desembarquei.",
  ui_story_5038_50380001_159_dialog_content = "Algum cavalheiro ou mulher poderia desejar que meu humilde eu lesse sua sorte, talvez iluminasse um pouco seu caminho?",
  ui_story_5038_50380001_160_dialog_content = "E Tianxian, o golpista, ataca novamente, enganando as pessoas com sua língua de prata...",
  ui_story_5038_50380001_161_dialog_content = "Ora, princesa Dantang! Ninguém é mentiroso, garanto-lhe.",
  ui_story_5038_50380001_162_dialog_content = "... Cuidado, Princesa!",
  ui_story_5038_50380001_163_dialog_content = "Ooooh!",
  ui_story_5038_50380001_164_dialog_content = "Uau! O Shadowind parece ainda melhor do que antes!",
  ui_story_5038_50380001_165_dialog_content = "Muito mais espaçoso também...",
  ui_story_5038_50380001_166_dialog_content = "Hehehe... Reflexos impressionantemente rápidos, Jiu.",
  ui_story_5038_50380001_167_dialog_content = "<color=#e8d9bb>*multidão murmurando*</color>",
  ui_story_5038_50380001_168_dialog_content = "Suspirar...",
  ui_story_5038_50380001_169_dialog_content = "Tudo bem Piu-Piu?",
  ui_story_5038_50380001_170_dialog_content = "Eu também quero dar uma olhada no Shadowind...",
  ui_story_5038_50380001_171_dialog_content = "Aposto que há muitas coisas legais para ver.",
  ui_story_5038_50380001_172_dialog_content = "Quer dizer assim, pequeno correio?",
  ui_story_5038_50380001_173_dialog_content = "UAU!! Uma pilha enorme de papel de vaca vermelho!",
  ui_story_5038_50380001_174_dialog_content = "Isso é incrível! Isso é exatamente o que eu estou procurando!",
  ui_story_5038_50380001_175_dialog_content = "Ouvi dizer que Twin Pavilions Bay estava ficando sem suprimentos antes mesmo de partirmos, com o Festival da Primavera se aproximando rapidamente, nada menos.",
  ui_story_5038_50380001_176_dialog_content = "Eles não tinham escolha a não ser obter suprimentos de guildas do interior e depois arranjar um monte de mensageiros para entregar tudo.",
  ui_story_5038_50380001_177_dialog_content = "No entanto, agora que o jornal de Longzhou está aqui, as coisas não serão tão complicadas para você.",
  ui_story_5038_50380001_178_dialog_content = "<size=50>YAY! Estou longe agora!!</size>",
  ui_story_5038_50380001_179_dialog_content = "Piu-Piu finalmente está fora do horário.",
  ui_story_5038_50380001_180_dialog_content = "Vocês três são do interior de Astra?",
  ui_story_5038_50380001_181_dialog_content = "Você pode dizer só de olhar para nossas roupas, certo?",
  ui_story_5038_50380001_182_dialog_content = "Aguardo sua hospitalidade, então.",
  ui_story_5038_50380001_183_dialog_content = "O Shadowind permanecerá nas águas do Astra por um tempo.",
  ui_story_5038_50380001_184_dialog_content = "Vamos nos conhecer durante este tempo.",
  ui_story_5038_50380001_185_dialog_content = "(Uau! Que mulher estóica e imponente!)",
  ui_story_5038_50380001_186_dialog_content = "S-Claro. Eu estou PlayerName.",
  ui_story_5038_50380001_187_dialog_content = "Bem-vindo ao Astra, convidados de Longzhou!",
  ui_story_5038_50380101_1_dialog_content = "<color=#e8d9bb>Twin Pavilions Bay Streets</color>",
  ui_story_5038_50380101_2_dialog_content = "(Nosso tempo aqui tem sido como um longo e raro feriado...)",
  ui_story_5038_50380101_3_dialog_content = "(Twin Pavilions Bay é um lugar tão relaxante durante o Festival da Primavera.)",
  ui_story_5038_50380101_4_dialog_content = "O que você está pensando, PlayerName?",
  ui_story_5038_50380101_5_dialog_content = "Só estava pensando na rapidez com que o tempo voa. Nem sei há quanto tempo estamos aqui.",
  ui_story_5038_50380101_6_dialog_content = "Eu faço. Eu mantenho um diário muito detalhado.",
  ui_story_5038_50380101_7_dialog_content = "Deixe-me ver... PlayerName e Tianxian passou os primeiros três dias vagando pela Eastern Specialty Snack Street...",
  ui_story_5038_50380101_8_dialog_content = "Os dias quatro a seis foram gastos conosco participando de vários jogos de xadrez de Twin Pavilions Bay...",
  ui_story_5038_50380101_9_dialog_content = "Dias sete a dez, perdendo miseravelmente no concurso de caligrafia do Festival da Primavera de Dantang...",
  ui_story_5038_50380101_10_dialog_content = "Dias dez a quinze—",
  ui_story_5038_50380101_11_dialog_content = "Ok, ok... Isso serve!",
  ui_story_5038_50380101_12_dialog_content = "De qualquer forma, provavelmente devemos começar a planejar nossa partida em breve.",
  ui_story_5038_50380101_13_dialog_content = "Demore o quanto quiser, PlayerName... Mas preciso partir para Illumina amanhã.",
  ui_story_5038_50380101_14_dialog_content = "Que? Tão cedo?!",
  ui_story_5038_50380101_15_dialog_content = "Bem, é hora de a cadeia de suprimentos especial de inverno da Illumina começar a funcionar.",
  ui_story_5038_50380101_16_dialog_content = "Tenho que ajudar na distribuição.",
  ui_story_5038_50380101_17_dialog_content = "E devo ir para Northland conforme a tradição, para passar o ano novo com a rainha Bethlehem.",
  ui_story_5038_50380101_18_dialog_content = "Se não houve nenhum atraso, meu treinador de Northland deve chegar aqui esta noite.",
  ui_story_5038_50380101_19_dialog_content = "Você também, Carleen?",
  ui_story_5038_50380101_20_dialog_content = "Bem, até logo, feriado. Tem sido divertido...",
  ui_story_5038_50380101_21_dialog_content = "Uau!! Olha quem eu encontrei!",
  ui_story_5038_50380101_22_dialog_content = "Bom dia, Sr. Navegador, Srta. Vice, Srta. Carween!",
  ui_story_5038_50380101_23_dialog_content = "Bom dia Piu!",
  ui_story_5038_50380101_24_dialog_content = "Como está o trabalho? Ainda ocupado?",
  ui_story_5038_50380101_25_dialog_content = "Bem agora! Já voltou ao normal!",
  ui_story_5038_50380101_26_dialog_content = "Só há uma trama de coisa para dewiver!",
  ui_story_5038_50380101_27_dialog_content = "Você ainda precisa de alguma ajuda? Ainda tenho tempo antes de ter que decolar.",
  ui_story_5038_50380101_28_dialog_content = "Obrigado, senhorita Vice, mas eu tenho isso! E adivinha?",
  ui_story_5038_50380101_29_dialog_content = "Eu comprei um <color=#FFB400>bilhete</color> para o Shadowind!",
  ui_story_5038_50380101_30_dialog_content = "Você acreditaria nisso? Esta é uma carta interurbana! Ele precisa ser enviado para Longzhou!",
  ui_story_5038_50380101_31_dialog_content = "Tive o cuidado de desembarcar todos os outros antes, para não perder o navio!",
  ui_story_5038_50380101_32_dialog_content = "Parece uma ótima chance de viajar.",
  ui_story_5038_50380101_33_dialog_content = "Ele Ele! Estou ansioso por isso!",
  ui_story_5038_50380101_34_dialog_content = "Parece que tudo o que alguém pode falar recentemente é a partida iminente do Shadowind.",
  ui_story_5038_50380101_35_dialog_content = "Sim, algumas pessoas ficam um pouco ansiosas.",
  ui_story_5038_50380101_36_dialog_content = "Você sabe... eu tenho o <color=#FFB400>furo interno</color> por que os Lins tiveram que suspender suas rotas por seis meses!",
  ui_story_5038_50380101_37_dialog_content = "Quem é você?",
  ui_story_5038_50380101_38_dialog_content = "Oh, eu me lembro! Você é o cara legal que ajudou o velho na cadeira de rodas!",
  ui_story_5038_50380101_39_dialog_content = "Haha! Eu não sou apenas um cara legal! Zhong Xu é meu amigo, assim como meu paciente.",
  ui_story_5038_50380101_40_dialog_content = "Éramos passageiros juntos no mesmo navio quando viemos de Longzhou.",
  ui_story_5038_50380101_41_dialog_content = "Meu nome é Liqing. Eu sou um médico gato errante, indo por aí e salvando vidas!",
  ui_story_5038_50380101_42_dialog_content = "Miauu!",
  ui_story_5038_50380101_43_dialog_content = "Uau!",
  ui_story_5038_50380101_44_dialog_content = "I-I-Isso é um gatinho!",
  ui_story_5038_50380101_45_dialog_content = "Vamos, Tinytail, comporte-se! Desculpe, ele só estava brincando.",
  ui_story_5038_50380101_46_dialog_content = "Venha aqui, Tinytail.",
  ui_story_5038_50380101_47_dialog_content = "Claramente, ele prefere minha companhia à sua.",
  ui_story_5038_50380101_48_dialog_content = "Só por causa de todos os outros gatos que andam ao seu redor...",
  ui_story_5038_50380101_49_dialog_content = "Com licença, estou aqui para confirmar os dados do passageiro.",
  ui_story_5038_50380101_50_dialog_content = "Os presentes - Tweety Zhong Xu e Liqing - poderiam confirmar sua reserva de volta a Longzhou?",
  ui_story_5038_50380101_51_dialog_content = "Uhum!",
  ui_story_5038_50380101_52_dialog_content = "Muito bom. Antes de partirmos, tenho mais alguns anúncios.",
  ui_story_5038_50380101_53_dialog_content = "Residentes de Longzhou, tenho certeza de que já ouviram falar da lendária bússola oceânica da família Lin.",
  ui_story_5038_50380101_54_dialog_content = "Eles costumavam contar com esse objeto para manter sua supremacia marítima.",
  ui_story_5038_50380101_55_dialog_content = "Infelizmente, este tesouro único foi perdido e até agora ainda não foi recuperado.",
  ui_story_5038_50380101_56_dialog_content = "Eu mencionei isso antes, mas certifique-se de entender os riscos de nossa jornada iminente.",
  ui_story_5038_50380101_57_dialog_content = "Nós realmente não temos nenhuma experiência em navegar sem a bússola, então, de certa forma, esta será uma aventura marítima.",
  ui_story_5038_50380101_58_dialog_content = "Tivemos condições favoráveis no caminho até aqui, o que tornou a viagem segura e tranquila.",
  ui_story_5038_50380101_59_dialog_content = "No entanto, não posso garantir que a viagem de volta será a mesma. Preciso ter certeza de que todos os passageiros estão totalmente cientes disso.",
  ui_story_5038_50380101_60_dialog_content = "Pessoalmente, eu gostaria <color=#FFB400>não aconselho</color> embarcando no Shadowind sem um bom motivo.",
  ui_story_5038_50380101_61_dialog_content = "(Esse foi um dos incidentes com os quais os Lins estavam lidando no último semestre...?)",
  ui_story_5038_50380101_62_dialog_content = "Eu não estou assustado! Eu acredito na senhorita Yuebai!",
  ui_story_5038_50380101_63_dialog_content = "Você é ousado, não é?",
  ui_story_5038_50380101_64_dialog_content = "Coincidência talvez, mas desde que eu tenho andado por aí contando a todos sobre isso...",
  ui_story_5038_50380101_65_dialog_content = "Cada pessoa que teve um ingresso prontamente cancelado.",
  ui_story_5038_50380101_66_dialog_content = "Alguns disseram que tiveram que ficar para trás por motivos familiares, outros que houve uma mudança repentina de planos.",
  ui_story_5038_50380101_67_dialog_content = "Eu suspeito que é porque ninguém está realmente disposto a arriscar suas vidas, quando o empurrão chega.",
  ui_story_5038_50380101_68_dialog_content = "Mas, nesse caso, você também está perdendo sua vida, senhorita Yuebai!",
  ui_story_5038_50380101_69_dialog_content = "... Tenho fé na minha capacidade de lidar com as coisas. De qualquer forma, este é o meu trabalho.",
  ui_story_5038_50380101_70_dialog_content = "Você não parece estar particularmente cheio de confiança.",
  ui_story_5038_50380101_71_dialog_content = "Você não está curioso sobre onde <color=#FFB400>O compasso</color> acabou?",
  ui_story_5038_50380101_72_dialog_content = "?!?",
  ui_story_5038_50380101_73_dialog_content = "Você é um dos Lins? Ou...",
  ui_story_5038_50380101_74_dialog_content = "É legal, Senhora Capitã! Nós estávamos realmente lá durante o <color=#FFB400>incidente</color> seis meses atrás.",
  ui_story_5038_50380101_75_dialog_content = "Impossível... Que eu saiba, nenhuma alma conseguiu escapar das garras dos piratas...",
  ui_story_5038_50380101_76_dialog_content = "Se você nem soubesse, então os piratas certamente não saberiam!",
  ui_story_5038_50380101_77_dialog_content = "E, de qualquer forma, tenho certeza de que não fomos apenas eu e o velho Zhong Xu aqui que não caímos nas profundezas do oceano naquela época.",
  ui_story_5038_50380101_78_dialog_content = "Você é o Sr. Zhong Xu, presumo?",
  ui_story_5038_50380101_79_dialog_content = "Sim, senhora.",
  ui_story_5038_50380101_80_dialog_content = "O Guildmaster tem estado mais preocupado com a sua segurança. Ele ficará feliz em saber que você está vivo.",
  ui_story_5038_50380101_81_dialog_content = "Hehe, então ele conseguiu fugir também, hein?",
  ui_story_5038_50380101_82_dialog_content = "Você é um capitão extraordinariamente corajoso. Admiro a sua tenacidade em retomar o percurso.",
  ui_story_5038_50380101_83_dialog_content = "Imagino que você não esteja aqui apenas em uma viagem de entrega de mercadorias! Certamente sua missão é procurar a Bússola também?",
  ui_story_5038_50380101_84_dialog_content = "... Correto.",
  ui_story_5038_50380101_85_dialog_content = "Se você ainda está determinado a embarcar, por favor, me ajude.",
  ui_story_5038_50380101_86_dialog_content = "É claro! Vamos conversar mais quando estivermos a bordo, não devemos deixar nossos hóspedes do interior parados por aqui.",
  ui_story_5038_50380101_87_dialog_content = "V-você quer dizer nós? Não se importe conosco, realmente...",
  ui_story_5038_50380101_88_dialog_content = "De qualquer forma, partiremos daqui a dois dias. Acho que o verei então, no porto.",
  ui_story_5038_50380101_89_dialog_content = "<color=#e8d9bb>Dois Dias Depois</color>",
  ui_story_5038_50380101_90_dialog_content = "Uau, se não é PlayerName!",
  ui_story_5038_50380101_91_dialog_content = "Venha se despedir de nós, não é?",
  ui_story_5038_50380101_92_dialog_content = "Bem, mais ou menos. Carleen e Vice já foram embora, mas queriam que eu deixasse um recado para vocês.",
  ui_story_5038_50380101_93_dialog_content = "\"Desejamos-lhe uma viagem tranquila e segura e esperamos que volte a visitar o Astra em breve.\"",
  ui_story_5038_50380101_94_dialog_content = "Isso é basicamente o que eu queria dizer também.",
  ui_story_5038_50380101_95_dialog_content = "Sei que nos conhecemos recentemente, mas ainda estou um pouco triste por termos que nos despedir tão cedo.",
  ui_story_5038_50380101_96_dialog_content = "Hehe... Vocês Astra sempre usam seus corações em suas mangas.",
  ui_story_5038_50380101_97_dialog_content = "Princesa Dantang, você gostaria de tentar dizer algo em resposta?",
  ui_story_5038_50380101_98_dialog_content = "Er... M-eu? Uh...",
  ui_story_5038_50380101_99_dialog_content = "Também me lembrarei de você com carinho, PlayerName.",
  ui_story_5038_50380101_100_dialog_content = "Zhong Xu e Tianxian já estão a bordo. Devemos ir também.",
  ui_story_5038_50380101_101_dialog_content = "Oh! Isso me lembra... Onde está aquele passarinho branco do outro dia?",
  ui_story_5038_50380101_102_dialog_content = "... Direita? Eu também queria me despedir do Piu-Piu.",
  ui_story_5038_50380101_103_dialog_content = "<size=50>Wahhhhhhh—</size>",
  ui_story_5038_50380101_104_dialog_content = "<size=50>PlayerName! H-Me ajude!</size>",
  ui_story_5038_50380101_105_dialog_content = "Ah! Aí está você, Piu-Piu!",
  ui_story_5038_50380101_106_dialog_content = "Não consigo terminar de entregar todos os meus posts!",
  ui_story_5038_50380101_107_dialog_content = "De repente, recebi uma entrega urgente em Northland! A União Couwier não pode enviar mais ninguém!",
  ui_story_5038_50380101_108_dialog_content = "Está frio nessas partes e a visibilidade é muito baixa. Eu sou o único familiarizado o suficiente com a área!",
  ui_story_5038_50380101_109_dialog_content = "Então... Você está dizendo que...",
  ui_story_5038_50380101_110_dialog_content = "Entããão... vim perguntar se você poderia me ajudar de novo, PlayerName?",
  ui_story_5038_50380101_111_dialog_content = "Eu estava pensando em contratar você para ir a Wongzhou para mim!",
  ui_story_5038_50380101_112_dialog_content = "Eu posso pagar! Espere até eu receber o salawy do mês que vem! Eu vou dar tudo para você!",
  ui_story_5038_50380101_113_dialog_content = "(Isso soa familiar...)",
  ui_story_5038_50380101_114_dialog_content = "Eu adoraria ajudá-lo, de verdade, e dinheiro não é importante!",
  ui_story_5038_50380101_115_dialog_content = "Mas a questão é, o seu bilhete é transferível?",
  ui_story_5038_50380101_116_dialog_content = "O que foi?",
  ui_story_5038_50380101_117_dialog_content = "Senhorita Yuebai!!",
  ui_story_5038_50380101_118_dialog_content = "Oh... Mmhmm... Eu entendo.",
  ui_story_5038_50380101_119_dialog_content = "Normalmente, os ingressos não são reembolsáveis e intransferíveis.",
  ui_story_5038_50380101_120_dialog_content = "Ah… Entendi.",
  ui_story_5038_50380101_121_dialog_content = "Vou pedir ajuda a um dos passageiros do navio...",
  ui_story_5038_50380101_122_dialog_content = "Como capitão, no entanto, ficaria encantado em convidá-lo a bordo, PlayerName.",
  ui_story_5038_50380101_123_dialog_content = "Huh?! É uma surpresa boa, mas repentina...",
  ui_story_5038_50380101_124_dialog_content = "Você tem que agradecer a Zhong Xu por isso.",
  ui_story_5038_50380101_125_dialog_content = "Eu só decidi procurar The Compass novamente, desde nossa conversa alguns dias atrás.",
  ui_story_5038_50380101_126_dialog_content = "Zhong Xu disse que as coisas podem ficar um pouco mais tranquilas com a ajuda de um Caelestita.",
  ui_story_5038_50380101_127_dialog_content = "(Vá mais suave...? Minha habilidade psíquica deveria ser capaz de sentir tal objeto?)",
  ui_story_5038_50380101_128_dialog_content = "Podemos pelo menos aproveitar nossa experiência de vir aqui para a viagem de volta.",
  ui_story_5038_50380101_129_dialog_content = "Também temos Zhong Xu e Liqing conosco, que estavam lá quando o The Compass desapareceu.",
  ui_story_5038_50380101_130_dialog_content = "A princesa Dantang, Jiu e Tianxian farão tudo o que puderem para manter o navio seguro.",
  ui_story_5038_50380101_131_dialog_content = "Se você confiar em mim para navegar, eu apreciaria sua ajuda.",
  ui_story_5038_50380101_132_dialog_content = "(Eu tive vários encontros com a Lin Guild no passado, e até fiz amizade com vários deles...)",
  ui_story_5038_50380101_133_dialog_content = "(Então, desta vez, se eu puder ajudá-los...)",
  ui_story_5038_50380101_134_option_content = "Eu vou fazer isso!",
  ui_story_5038_50380101_135_dialog_content = "Obrigado por estar tão disposto, PlayerName. Eu vou esperar por você a bordo.",
  ui_story_5038_50380101_136_dialog_content = "Obrigado, Sr. Navegador!",
  ui_story_5038_50380101_137_dialog_content = "O que você está esperando? Venha!",
  ui_story_5038_50380101_138_dialog_content = "A-tudo bem! Estou chegando!",
  ui_story_5038_50380101_139_dialog_content = "Miau!",
  ui_story_5038_50380101_140_dialog_content = "Ooh! Tinytail vê peixes!",
  ui_story_5038_50380101_141_dialog_content = "Não, Cauda Pequena. Não pule!",
  ui_story_5038_50380101_142_dialog_content = "Miau...",
  ui_story_5038_50380101_143_dialog_content = "Os ventos de Astra parecem ser muito mais fortes que os de Longzhou...",
  ui_story_5038_50380101_144_dialog_content = "Simplesmente perfeito para zarpar.",
  ui_story_5038_50380101_145_dialog_content = "Já está pegando as velas do Shadowind. Parece ser do sudoeste.",
  ui_story_5038_50380101_146_dialog_content = "Vou limpar o convés. Por favor, sentem-se bem, todos!",
  ui_story_5038_50380101_147_dialog_content = "Shadowind, zarpe!",
  ui_story_5038_50380201_1_dialog_content = "(Que navio incrível! É maior do que qualquer outro em que já estive.)",
  ui_story_5038_50380201_2_dialog_content = "(Até o design do baralho é rico em características do extremo oriente.)",
  ui_story_5038_50380201_3_dialog_content = "(A vista também é magnífica...)",
  ui_story_5038_50380201_4_dialog_content = "(Ahhh! Céus azuis, ondas, brisa do mar...)",
  ui_story_5038_50380201_5_dialog_content = "Hã?",
  ui_story_5038_50380201_6_dialog_content = "Zhong Xu, por que você está aqui sozinho, olhando para o mar, perdido em pensamentos?",
  ui_story_5038_50380201_7_dialog_content = "Estou observando as ondas.",
  ui_story_5038_50380201_8_dialog_content = "Há... algo para ver lá?",
  ui_story_5038_50380201_9_dialog_content = "As ondas do oceano são as mesmas, onde quer que você vá. E assim, contemplá-los me faz lembrar de minha casa.",
  ui_story_5038_50380201_10_dialog_content = "Você deve sentir muita falta.",
  ui_story_5038_50380201_11_dialog_content = "Ah, isso me lembra. Antes de partirmos, eu tinha a impressão de que muitos dos residentes antigos de Twin Pavilions Bay viriam conosco.",
  ui_story_5038_50380201_12_dialog_content = "Eu nunca teria esperado que acabaria sendo apenas você e Liqing a bordo.",
  ui_story_5038_50380201_13_dialog_content = "Quando você vagueia por muito tempo em terras estrangeiras, muitas vezes deseja voltar para casa.",
  ui_story_5038_50380201_14_dialog_content = "Aqueles que devolveram seus ingressos ainda sentem falta de sua terra natal, mas sementes de pertencimento já criaram raízes para eles em Twin Pavilions Bay.",
  ui_story_5038_50380201_15_dialog_content = "Eles têm família em Twin Pavilions Bay agora e novos amigos. A saudade de sua terra natal é mais uma nostalgia melancólica do que qualquer outra coisa.",
  ui_story_5038_50380201_16_dialog_content = "Somente pessoas como eu podem ir e vir tão livremente quanto o vento, sem que nada as prenda.",
  ui_story_5038_50380201_17_dialog_content = "Acho que entendi o que você quis dizer...",
  ui_story_5038_50380201_18_dialog_content = "Heh... jovem amigo, fico surpreso que alguém tão jovem seja feliz ouvindo as divagações de um velho.",
  ui_story_5038_50380201_19_dialog_content = "Eu gosto de conversar com você, então não há necessidade de você me tratar como seu superior.",
  ui_story_5038_50380201_20_dialog_content = "Espero que possamos ser amigos. Vamos acabar com as formalidades, certo?",
  ui_story_5038_50380201_21_dialog_content = "Como com Liqing, somos iguais.",
  ui_story_5038_50380201_22_dialog_content = "Excelente! Sinto-me honrado e feliz por...",
  ui_story_5038_50380201_23_dialog_content = "<color=#e8d9bb>Splash!</color>",
  ui_story_5038_50380201_24_dialog_content = "Nossa!",
  ui_story_5038_50380201_25_dialog_content = "O que é que foi isso?! Acabei de ficar encharcado!",
  ui_story_5038_50380201_26_dialog_content = "Era um cardume de peixes.",
  ui_story_5038_50380201_27_dialog_content = "Se você encontrar um com uma cauda como a de uma serpente, então é um <color=#FFB400>peixe-serpente</color>!",
  ui_story_5038_50380201_28_dialog_content = "T-Eles surgiram do nada... Estou surpreso que a água espirrou no meu rosto lá de baixo!",
  ui_story_5038_50380201_29_dialog_content = "Bem, isso porque o inverno é quando eles estão mais ativos, sendo que é a época de acasalamento.",
  ui_story_5038_50380201_30_dialog_content = "Eles se agrupam em escolas e nadam no fundo do mar assim que nascem.",
  ui_story_5038_50380201_31_dialog_content = "Não importa o quão longe eles possam nadar, no inverno eles invariavelmente se fundem com outras escolas próximas.",
  ui_story_5038_50380201_32_dialog_content = "Em seguida, eles migram de volta para os portos de Longzhou, onde depositam seus ovos nas águas rasas... E o ciclo recomeça.",
  ui_story_5038_50380201_33_dialog_content = "Como você sabe tanto sobre esse peixe?",
  ui_story_5038_50380201_34_dialog_content = "Ele Ele! Porque o peixe-serpente é uma espécie sagrada para a Lin Guild.",
  ui_story_5038_50380201_35_dialog_content = "Como um totem?",
  ui_story_5038_50380201_36_dialog_content = "Sim algo assim. Os Lins esperam ser como aqueles peixes, retornando em segurança à terra natal após cada viagem.",
  ui_story_5038_50380201_37_dialog_content = "Mestre Bu diz, brotos com potencial podem ser cultivados. Esperto PlayerName!",
  ui_story_5038_50380201_38_dialog_content = "Não seja tão paternalista como se você fosse o adulto aqui!",
  ui_story_5038_50380201_39_dialog_content = "Não julgue um livro pela capa, PlayerName. Quem sabe, eu poderia ser o mais velho aqui.",
  ui_story_5038_50380201_40_dialog_content = "Então é melhor você se dirigir a mim com respeito devido ao seu superior, hehe.",
  ui_story_5038_50380201_41_dialog_content = "Hum? *Sniff sniff* Sinto cheiro de peixe!",
  ui_story_5038_50380201_42_dialog_content = "Talvez porque seja hora do almoço.",
  ui_story_5038_50380201_43_dialog_content = "É o nosso primeiro dia no mar, por isso precisamos de um pouco de ânimo.",
  ui_story_5038_50380201_44_dialog_content = "Venha experimentar, PlayerName. Isso é <color=#FFB400>peixe esquilo</color>, uma especialidade de Longzhou.",
  ui_story_5038_50380201_45_dialog_content = "Desossamos um peixe recém-capturado e marcamos sua carne de maneira cruzada. Em seguida, foi frito até ficar crocante e dourado, antes de finalmente ser coberto com um molho agridoce...",
  ui_story_5038_50380201_46_dialog_content = "Esperar! Com que peixe você fez?!",
  ui_story_5038_50380201_47_dialog_content = "Um peixe-serpente. É bem gostoso e macio.",
  ui_story_5038_50380201_48_dialog_content = "O que?!!",
  ui_story_5038_50380201_49_dialog_content = "Haha, peguei você! Estou brincando, era apenas um peixe comercial comum do porão.",
  ui_story_5038_50380201_50_dialog_content = "Venha comigo para a área de passageiros. Os outros já estão lá.",
  ui_story_5038_50380201_51_dialog_content = "<color=#e8d9bb>Cabine de Passageiros Shadowind</color>",
  ui_story_5038_50380201_52_dialog_content = "Uau! Você é muito talentosa, princesa Dantang. Este peixe é cozido perfeitamente e tem gosto de casa!",
  ui_story_5038_50380201_53_dialog_content = "Dificilmente vale a pena aceitar os elogios de um vigarista.",
  ui_story_5038_50380201_54_dialog_content = "De qualquer forma, Jiu preparou todos esses pratos.",
  ui_story_5038_50380201_55_dialog_content = "A senhora ajudou muito.",
  ui_story_5038_50380201_56_dialog_content = "Duvido que você encontre outro relacionamento empregador-empregado em toda Ji que seja tão respeitoso quanto esses dois!",
  ui_story_5038_50380201_57_dialog_content = "...",
  ui_story_5038_50380201_58_dialog_content = "Oh, desculpe, mas acho que a princesa prefere não falar sobre esse lugar.",
  ui_story_5038_50380201_59_dialog_content = "Por que não pedimos aos dois membros da Lin Guild aqui para nos regalar com o que aconteceu? <color=#FFB400>aquele dia</color>.",
  ui_story_5038_50380201_60_dialog_content = "Om nom nom nom... Delicioso!",
  ui_story_5038_50380201_61_dialog_content = "Aqui, Rabo Minúsculo. Você pode ter alguns também!",
  ui_story_5038_50380201_62_dialog_content = "Miau!",
  ui_story_5038_50380201_63_dialog_content = "Bem, isso vai mantê-lo ocupado por um tempo.",
  ui_story_5038_50380201_64_dialog_content = "Se puder, Sr. Zhong.",
  ui_story_5038_50380201_65_dialog_content = "Eu adoraria, capitão. Mas lembre-se de que já faz mais de meio ano, então alguns detalhes podem estar um pouco confusos.",
  ui_story_5038_50380201_66_dialog_content = "Mas, no entanto, permita-me contar toda a provação, do começo ao fim.",
  ui_story_5038_50380201_67_dialog_content = "Apenas o que eu estava esperando! Onde quer que minhas viagens me levem, minha coisa favorita é ouvir as histórias das pessoas.",
  ui_story_5038_50380201_68_dialog_content = "Ah, mas a história que vou contar pode ser mais sombria do que você está acostumado a ouvir.",
  ui_story_5038_50380201_69_dialog_content = "Tecnicamente falando, Liqing e eu não somos tecnicamente Lins, embora nosso bom capitão certamente seja.",
  ui_story_5038_50380201_70_dialog_content = "Não há necessidade de tal formalidade, meu senhor.",
  ui_story_5038_50380201_71_dialog_content = "Com um sobrenome como Mu, que tipo de Lin eu sou, realmente?",
  ui_story_5038_50380201_72_dialog_content = "Oh, minhas desculpas! eu não pensei. Não quis chamar a atenção para o seu sobrenome.",
  ui_story_5038_50380201_73_dialog_content = "De qualquer forma, sou apenas um velho amigo da família Lin, onde Liqing era um hóspede de longa data.",
  ui_story_5038_50380201_74_dialog_content = "Na verdade, nossas identidades foram a única coisa que salvou nossas vidas após o incidente.",
  ui_story_5038_50380201_75_dialog_content = "Então, o que aconteceu há seis meses?",
  ui_story_5038_50380201_76_dialog_content = "Tudo começou e terminou com The Compass.",
  ui_story_5038_50380201_77_dialog_content = "Essa bússola é o que permitiu aos Lins dominar o comércio marítimo, o que naturalmente atraiu atenção maliciosa.",
  ui_story_5038_50380201_78_dialog_content = "Vários pequenos grupos se uniram sob a liderança de uma das guildas, com a intenção de derrubar os Lins.",
  ui_story_5038_50380201_79_dialog_content = "Eles sabiam que não podiam igualar o poder dos Lins, mas não tinham medo de se rebaixar a truques sujos e táticas vergonhosas.",
  ui_story_5038_50380201_80_dialog_content = "Um dia, Liqing e eu estávamos a caminho de um banquete no Lin Manor, com a presença de muitos dos amigos mais próximos da família.",
  ui_story_5038_50380201_81_dialog_content = "Assim que a noite estava em pleno andamento, ladrões invadiram com intenção assassina...",
  ui_story_5038_50380202_1_dialog_content = "Zhong Xu! Por aqui!",
  ui_story_5038_50380202_2_dialog_content = "Tudo bem?",
  ui_story_5038_50380202_3_dialog_content = "Só um arranhão, não é nada.",
  ui_story_5038_50380202_4_dialog_content = "Pelo menos conseguimos tirar Guildmaster Lin com segurança.",
  ui_story_5038_50380202_5_dialog_content = "O Guildmaster está bem?! Que alivio!",
  ui_story_5038_50380202_6_dialog_content = "Ele escapou, mas os outros...",
  ui_story_5038_50380202_7_dialog_content = "Temo que, depois desta noite, os Lins não tenham mais presença no reino dos mercadores.",
  ui_story_5038_50380202_8_dialog_content = "Como eles puderam simplesmente invadir a mansão de forma tão descarada?",
  ui_story_5038_50380202_9_dialog_content = "Eles eram bandidos contratados. Eles não se importam com o perigo.",
  ui_story_5038_50380202_10_dialog_content = "Alguém deve ter pago caro para eles arriscarem suas vidas.",
  ui_story_5038_50380202_11_dialog_content = "Se não me engano, eles vieram pelo The Compass.",
  ui_story_5038_50380202_12_dialog_content = "O compasso? Mas não é nem no Lin Manor...",
  ui_story_5038_50380202_13_dialog_content = "Eles ainda não sabem.",
  ui_story_5038_50380202_14_dialog_content = "Guildmaster Lin tem um plano de contingência para garantir a segurança do The Compass.",
  ui_story_5038_50380202_15_dialog_content = "Se falhar... vou vingar os Lins.",
  ui_story_5038_50380202_16_dialog_content = "Siga-me, Liqing.",
  ui_story_5038_50380202_17_dialog_content = "Depois disso... Mal escapamos com vida.",
  ui_story_5038_50380202_18_dialog_content = "Foi só naquele momento que percebemos que o alvo naquela noite não era o mestre da guilda.",
  ui_story_5038_50380202_19_dialog_content = "Para proteger a Bússola e evitar que ela seja destruída ou roubada, Guildmaster Lin decidiu fazer com que parentes próximos a levassem embora.",
  ui_story_5038_50380202_20_dialog_content = "O Compass foi carregado em um velho navio, que imediatamente deixou o porto e rumou para o mar aberto. Nós fomos com ele.",
  ui_story_5038_50380202_21_dialog_content = "Eles navegaram COM a Bússola? Eu não entendo... Certamente é mais perigoso no mar?",
  ui_story_5038_50380202_22_dialog_content = "Não seria melhor trancá-lo em um cofre ou algo assim?",
  ui_story_5038_50380202_23_dialog_content = "Para algo nascido do mar, o mar é onde está mais seguro.",
  ui_story_5038_50380202_24_dialog_content = "Hã? Como assim?",
  ui_story_5038_50380202_25_dialog_content = "Enquanto a Bússola estiver guiando um navio, ele nunca se perderá e sempre haverá ventos favoráveis, águas calmas e nenhum acidente.",
  ui_story_5038_50380202_26_dialog_content = "Mas...",
  ui_story_5038_50380202_27_dialog_content = "Ah, mas a Bússola ainda sumiu, não foi? Era isso que ia perguntar, capitão?",
  ui_story_5038_50380202_28_dialog_content = "Não se perdeu por causa dos elementos.",
  ui_story_5038_50380202_29_dialog_content = "...",
  ui_story_5038_50380202_30_dialog_content = "Os piratas estavam no encalço do Shadowind.",
  ui_story_5038_50380202_31_dialog_content = "Nós dois caímos no mar com todo o tumulto e nunca mais conseguimos voltar.",
  ui_story_5038_50380202_32_dialog_content = "Como você sabe, esses bandidos nunca colocaram as mãos no The Compass. Caso contrário, a rota marítima não teria sido cortada por tanto tempo.",
  ui_story_5038_50380202_33_dialog_content = "Logo depois, nós e os piratas fomos pegos em uma <color=#FFB400>poderosa tempestade</color>.",
  ui_story_5038_50380202_34_dialog_content = "Todas as almas a bordo foram perdidas, exceto o jovem Liqing aqui e eu.",
  ui_story_5038_50380202_35_dialog_content = "Foi também quando minhas pernas ficaram feridas.",
  ui_story_5038_50380202_36_dialog_content = "Onde tudo isso aconteceu?",
  ui_story_5038_50380202_37_dialog_content = "Eu não faço ideia. Não tenho senso de direção de marinheiro.",
  ui_story_5038_50380202_38_dialog_content = "De qualquer forma, talvez seja a natureza espiritual de um demônio, mas Liqing me trouxe para Astra.",
  ui_story_5038_50380202_39_dialog_content = "Espere... Que tipo de coisa é um <color=#FFB400>diabólico</color>?",
  ui_story_5038_50380202_40_dialog_content = "Bem, isso não é educado, PlayerName. Fiendlings não são coisas.",
  ui_story_5038_50380202_41_dialog_content = "Deixe-me esclarecer você. Resumindo, fiendlings são aurorianos como eu, que possuem características animais.",
  ui_story_5038_50380202_42_dialog_content = "Enquanto estamos no assunto, Tinytail é na verdade meu irmão mais velho.",
  ui_story_5038_50380202_43_dialog_content = "Silvo-!",
  ui_story_5038_50380202_44_dialog_content = "Oh. Acho que entendi.",
  ui_story_5038_50380202_45_dialog_content = "(Eles são basicamente aurorianos com sangue semi-humano, não são? Talvez seja exatamente isso que eles chamam de semi-humanos em Longzhou.)",
  ui_story_5038_50380202_46_dialog_content = "De acordo com os registros da família Lin, perder The Compass é um evento sem precedentes.",
  ui_story_5038_50380202_47_dialog_content = "Embora nunca o tenha visto com meus próprios olhos, ouvi dizer que é um tesouro que <color=#FFB400>vive e morre com seu navio</color>.",
  ui_story_5038_50380202_48_dialog_content = "Eu ainda quero tentar, pessoal. Mesmo que encontremos apenas um naufrágio, pelo menos saberei onde caiu.",
  ui_story_5038_50380202_49_dialog_content = "Não desejo que corramos para o tipo de perigo de que Zhong Xu falou.",
  ui_story_5038_50380202_50_dialog_content = "Eu entendo. Pelo bem de todos a bordo, não podemos perder a esperança de encontrá-lo.",
  ui_story_5038_50380202_51_dialog_content = "Mesmo que o capitão não tivesse dito isso, eu ainda gostaria de encontrar a coisa.",
  ui_story_5038_50380202_52_dialog_content = "Está ficando tarde, então vamos encontrar um lugar para ancorar durante a noite.",
  ui_story_5038_50380202_53_dialog_content = "Por favor, tenha uma boa noite de descanso. Vou manter vigília com a tripulação.",
  ui_story_5038_50380202_54_dialog_content = "Eu também!",
  ui_story_5038_50380202_55_dialog_content = "As crianças devem dormir bem.",
  ui_story_5038_50380202_56_dialog_content = "Já disse, não sou criança!",
  ui_story_5038_50380202_57_dialog_content = "E, de qualquer maneira, Tinytail e eu não dormimos tão facilmente à noite.",
  ui_story_5038_50380202_58_dialog_content = "Deixe-o ir junto. Caso contrário, ele acabará atrapalhando a todos.",
  ui_story_5038_50380202_59_dialog_content = "Vamos lá! Eu não faria isso!",
  ui_story_5038_50380202_60_dialog_content = "Tudo bem. Nesse caso, siga-me até o convés daqui a pouco, Liqing.",
  ui_story_5038_50380202_61_dialog_content = "As camas foram feitas na cabine de passageiros; cada um tem seu espaço. Se você me seguir, por favor.",
  ui_story_5038_50380301_1_dialog_content = "<color=#e8d9bb>Meia-noite</color>",
  ui_story_5038_50380301_2_dialog_content = "Zzz...",
  ui_story_5038_50380301_3_dialog_content = "<color=#e8d9bb>*Rumindo*</color>",
  ui_story_5038_50380301_4_dialog_content = "(Hein? Aquilo foi um trovão...?)",
  ui_story_5038_50380301_5_dialog_content = "(Está chovendo...?)",
  ui_story_5038_50380301_6_dialog_content = "<color=#e8d9bb>BAQUE!!!</color>",
  ui_story_5038_50380301_7_dialog_content = "Aaaaaah!",
  ui_story_5038_50380301_8_dialog_content = "O que é que foi isso?!",
  ui_story_5038_50380301_9_dialog_content = "<color=#e8d9bb>Miau!</color>",
  ui_story_5038_50380301_10_dialog_content = "<color=#e8d9bb>Miau!!</color>",
  ui_story_5038_50380301_11_dialog_content = "Pronto pronto. Não há nada a temer.",
  ui_story_5038_50380301_12_dialog_content = "Desculpe por acordá-lo, jovem amigo.",
  ui_story_5038_50380301_13_dialog_content = "Yixin, Yimeng e Yinuo... Eles estiveram comigo por toda a vida e até sobreviveram ao incidente no antigo Shadowind...",
  ui_story_5038_50380301_14_dialog_content = "Um clima como este traz de volta memórias de pesadelo para eles.",
  ui_story_5038_50380301_15_dialog_content = "Esqueça os gritos do gato! Você não ouviu esse barulho?!",
  ui_story_5038_50380301_16_dialog_content = "<color=#e8d9bb>BAQUE!!!</color>",
  ui_story_5038_50380301_17_dialog_content = "Todos acordados? Vocês estão bem?",
  ui_story_5038_50380301_18_dialog_content = "Jiu ouviu primeiro. Eu tenho andado com ela, acordando quem conseguiu dormir durante o barulho.",
  ui_story_5038_50380301_19_dialog_content = "Então, o que exatamente aconteceu?",
  ui_story_5038_50380301_20_dialog_content = "Não sei, mas parece que algo está batendo no casco!",
  ui_story_5038_50380301_21_dialog_content = "E... eu não acho que seja <color=#FFB400>uma Coisa</color>.",
  ui_story_5038_50380301_22_dialog_content = "(Não poderia ser Eclipsites, poderia? Em alto mar, no meio da noite?!!)",
  ui_story_5038_50380301_23_dialog_content = "Vou ver o que está acontecendo no convés!",
  ui_story_5038_50380301_24_dialog_content = "Permita-me ir com você, PlayerName.",
  ui_story_5038_50380301_25_dialog_content = "Sr. Zhong Xu, talvez você queira se juntar a mim e Dantang e procurar abrigo?",
  ui_story_5038_50380301_26_dialog_content = "Se bem me lembro, deve haver um escorregador entre as cabines de passageiros no andar de baixo desta.",
  ui_story_5038_50380301_27_dialog_content = "Eh? Como você...",
  ui_story_5038_50380301_28_dialog_content = "Afinal, este Shadowind é estruturado da mesma forma que o antigo.",
  ui_story_5038_50380301_29_dialog_content = "Venha então, vamos nos apressar.",
  ui_story_5038_50380301_30_dialog_content = "Só tenho uma coisa a dizer, jovem amigo. Se vocês dois não puderem ajudar Liqing e Yuebai,",
  ui_story_5038_50380301_31_dialog_content = "então saia de lá e vá para o abrigo abaixo do convés. Não seja um herói.",
  ui_story_5038_50380301_32_dialog_content = "Eu vou, não se preocupe.",
  ui_story_5038_50380301_33_dialog_content = "<color=#e8d9bb>no convés</color>",
  ui_story_5038_50380301_34_dialog_content = "Está chovendo muito...",
  ui_story_5038_50380301_35_dialog_content = "Yuebai! Liqing!",
  ui_story_5038_50380301_36_dialog_content = "Capitão Yuebai! Gatinho!",
  ui_story_5038_50380301_37_dialog_content = "Bem, isso não está funcionando. Eles nunca vão nos ouvir com esse aguaceiro.",
  ui_story_5038_50380301_38_dialog_content = "Acha que poderia encontrá-los psiquicamente, Sr. Lendário Celestita?",
  ui_story_5038_50380301_39_option_content = "Aumento de Força",
  ui_story_5038_50380301_40_dialog_content = "Urgh... Nada bom. Estou recebendo apenas um leve traço de Lumina e Darkflow.",
  ui_story_5038_50380301_41_dialog_content = "Hã?!",
  ui_story_5038_50380301_42_dialog_content = "Há algo mais... algo que eu nunca encontrei antes...",
  ui_story_5038_50380301_43_dialog_content = "O atendente de Dantang estava certo... Tem todo um grupo do que quer que seja!",
  ui_story_5038_50380301_44_dialog_content = "E não apenas isso... eu posso sentir uma energia poderosa...",
  ui_story_5038_50380301_45_dialog_content = "Tente encontrá-los novamente!",
  ui_story_5038_50380301_46_dialog_content = "Não adianta. Não consigo senti-los de jeito nenhum...",
  ui_story_5038_50380301_47_dialog_content = "<color=#e8d9bb>BATER!!!</color>",
  ui_story_5038_50380301_48_dialog_content = "<size=50><color=#e8d9bb>BAQUE!!!</color></size>",
  ui_story_5038_50380301_49_dialog_content = "Uau, cuidado!",
  ui_story_5038_50380301_50_dialog_content = "Vamos descobrir o que está fazendo esse som!",
  ui_story_5038_50380301_51_dialog_content = "Tá bom...",
  ui_story_5038_50380301_52_dialog_content = "É... É um...",
  ui_story_5038_50380301_53_dialog_content = "Rabo minúsculo! Pare com isso! Pare de se contorcer!",
  ui_story_5038_50380301_54_dialog_content = "Eu não posso esperar!",
  ui_story_5038_50380301_55_dialog_content = "Capitão! Tudo bem aí?!",
  ui_story_5038_50380301_56_dialog_content = "Cuide-se primeiro, Liqing! Agarre-se a algo! Tente não se mexer!",
  ui_story_5038_50380301_57_dialog_content = "Liqing! Yuebai!",
  ui_story_5038_50380301_58_dialog_content = "Uau! Isso é PlayerName e Tianxian!",
  ui_story_5038_50380301_59_dialog_content = "O que vocês estão fazendo aqui?!",
  ui_story_5038_50380301_60_dialog_content = "Pegue Liqing e coloque-se em segurança, rapidamente!",
  ui_story_5038_50380301_61_dialog_content = "<size=50><color=#e8d9bb>BAQUE!!!</color></size>",
  ui_story_5038_50380301_62_dialog_content = "Seu... <color=#FFB400>peixe-serpente</color>!",
  ui_story_5038_50380301_63_dialog_content = "Eles estão batendo em nosso casco! Armador!!",
  ui_story_5038_50380301_64_dialog_content = "Sim, capitão?",
  ui_story_5038_50380301_65_dialog_content = "Leve alguém para o convés inferior e inicie um protocolo de emergência para evitar quebras e vazamentos no casco!",
  ui_story_5038_50380301_66_dialog_content = "Sim!",
  ui_story_5038_50380301_67_dialog_content = "peixe-serpente...",
  ui_story_5038_50380301_68_dialog_content = "Mas por que...? Por que eles atacariam o Shadowind?",
  ui_story_5038_50380301_69_dialog_content = "(Estes são os peixes de que Liqing estava falando...)",
  ui_story_5038_50380301_70_dialog_content = "(Eles são inegavelmente lindos quando em massa... Mas sua força combinada é aterrorizante!)",
  ui_story_5038_50380301_71_dialog_content = "<size=50><color=#e8d9bb>BAQUE!!!</color></size>",
  ui_story_5038_50380301_72_dialog_content = "Foco, gatinha! Fique longe do trilho, ou você pode cair no mar!",
  ui_story_5038_50380301_73_dialog_content = "Como podemos detê-los, Liqing?!",
  ui_story_5038_50380301_74_dialog_content = "Nós... Não podemos. Sem a Bússola, não há nada que possamos fazer...",
  ui_story_5038_50380301_75_dialog_content = "<size=50><color=#e8d9bb>BATER!</color></size>",
  ui_story_5038_50380301_76_dialog_content = "Essa não...",
  ui_story_5038_50380301_77_dialog_content = "Saia daqui! Vou tentar segurá-la firme e ganhar algum tempo para você!",
  ui_story_5038_50380301_78_dialog_content = "Estamos começando a listar! Vá para os botes salva-vidas!",
  ui_story_5038_50380301_79_dialog_content = "Espere aí!",
  ui_story_5038_50380301_80_dialog_content = "O que??",
  ui_story_5038_50380301_81_dialog_content = "Algo mais está na lista Shadowind! Eu posso sentir isso! É como...",
  ui_story_5038_50380301_82_dialog_content = "Algo veio a bordo em grande número...",
  ui_story_5038_50380301_83_dialog_content = "Ah...",
  ui_story_5038_50380301_84_dialog_content = "Graaagh!",
  ui_story_5038_50380301_85_dialog_content = "Claro que é Eclipsites!",
  ui_story_5038_50380301_86_dialog_content = "... Temos sorte de ter você conosco, PlayerName.",
  ui_story_5038_50380301_87_dialog_content = "Vamos cuidar deles!",
  ui_story_5038_50380302_1_dialog_content = "Vamos eliminá-los todos de uma vez!",
  ui_story_5038_50380302_2_dialog_content = "Fico grato pela sua ajuda, PlayerName.",
  ui_story_5038_50380302_3_dialog_content = "Parece que o navio ainda está adernado, no entanto...",
  ui_story_5038_50380302_4_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5038_50380302_5_dialog_content = "Traga itens pesados e mercadorias para a popa para equilibrar o navio, marinheiro!",
  ui_story_5038_50380302_6_dialog_content = "Sim!",
  ui_story_5038_50380302_7_dialog_content = "Os peixes estão puxando uma corda na proa, foi assim que os Eclipsitas conseguiram subir a bordo.",
  ui_story_5038_50380302_8_dialog_content = "PlayerName, Liqing, Tianxian! Se puder, siga o barqueiro à ré.",
  ui_story_5038_50380302_9_dialog_content = "Beleza!",
  ui_story_5038_50380302_10_dialog_content = "Aqui, PlayerName, pegue isso!",
  ui_story_5038_50380302_11_dialog_content = "Uau, isso é pesado!! O que é isso?",
  ui_story_5038_50380302_12_dialog_content = "Um baú cheio de pesos de ferro vindos de Longzhou!",
  ui_story_5038_50380302_13_dialog_content = "...O que uma coisa dessas está fazendo a bordo?!",
  ui_story_5038_50380302_14_dialog_content = "Para contabilidade, pesagem de mercadorias e assim por diante. Você ficaria surpreso com a frequência com que eles são úteis.",
  ui_story_5038_50380302_15_dialog_content = "Quero dizer, evidentemente, precisamos deles agora.",
  ui_story_5038_50380302_16_dialog_content = "Vou pegar um baú também. Vamos levá-los para a popa, para consertar a inclinação do navio.",
  ui_story_5038_50380302_17_dialog_content = "Você não precisa carregar nada, gatinha. Você provavelmente se machucaria.",
  ui_story_5038_50380302_18_dialog_content = "Eu vou ficar aqui.",
  ui_story_5038_50380302_19_dialog_content = "Você está tentando ser engraçado? Vamos, mexa-se.",
  ui_story_5038_50380302_20_dialog_content = "Eu disse, vou ficar aqui mesmo.",
  ui_story_5038_50380302_21_dialog_content = "(Liqing está examinando a água há anos, quase como se estivesse procurando por algo...)",
  ui_story_5038_50380302_22_dialog_content = "Você pensou em algo, Liqing? Você sabe por que os peixes-serpentes estão atacando?",
  ui_story_5038_50380302_23_dialog_content = "Não. Nenhum palpite...",
  ui_story_5038_50380302_24_dialog_content = "Mas o peixe-serpente nunca ataca as pessoas sem razão!",
  ui_story_5038_50380302_25_dialog_content = "Eles devem estar seguindo as ordens do líder da escola, o peixe alfa.",
  ui_story_5038_50380302_26_dialog_content = "Mas por que ele iria querer atacar nossa nave? O que ele quer...?",
  ui_story_5038_50380302_27_dialog_content = "Você está tentando encontrar este peixe alfa?",
  ui_story_5038_50380302_28_dialog_content = "Pelo menos... eu preciso ver claramente de onde <color=#FFB400>direção</color> Eles estão vindo.",
  ui_story_5038_50380302_29_dialog_content = "<color=#e8d9bb>BATER!!!</color>",
  ui_story_5038_50380302_30_dialog_content = "(Os peixes-serpente estão ficando cada vez mais agitados. Se isso continuar por muito mais tempo...)",
  ui_story_5038_50380302_31_option_content = "Aumento de Força!",
  ui_story_5038_50380302_32_dialog_content = "Isso vai funcionar?!",
  ui_story_5038_50380302_33_dialog_content = "Eu realmente não sei! Mas não custa tentar!",
  ui_story_5038_50380302_34_dialog_content = "(Vou tentar fazer o que fiz antes...)",
  ui_story_5038_50380302_35_dialog_content = "(Essas criaturas parecem estar vindo do leste... Deixe-me tentar acalmá-las...)",
  ui_story_5038_50380302_36_dialog_content = "(Droga, não está funcionando desta vez!)",
  ui_story_5038_50380302_37_dialog_content = "Eles parecem estar parando. Veja!",
  ui_story_5038_50380302_38_dialog_content = "Seriamente? Minha ideia maluca funcionou?!",
  ui_story_5038_50380302_39_dialog_content = "De repente, eles se viraram de uma só vez, formando um longo cinturão de peixes...",
  ui_story_5038_50380302_40_dialog_content = "... Não, espere! Algo está errado!!",
  ui_story_5038_50380302_41_dialog_content = "O-o que você quer dizer?",
  ui_story_5038_50380302_42_dialog_content = "Pessoal! Agarre-se ao corrimão e deite-se no chão!",
  ui_story_5038_50380302_43_dialog_content = "Eles estão... nos cobrando!",
  ui_story_5038_50380302_44_dialog_content = "Capitão! Vire o navio, rapidamente!",
  ui_story_5038_50380302_45_dialog_content = "(Esses peixes-serpente já causaram sérios estragos. Sem contar essa tempestade...)",
  ui_story_5038_50380302_46_dialog_content = "(Eu mal consigo mover o leme...)",
  ui_story_5038_50380302_47_dialog_content = "Força, todos! Segure-se e proteja suas cabeças!",
  ui_story_5038_50380302_48_dialog_content = "(O Shadowind vai sucumbir ao poder do oceano mais uma vez?)",
  ui_story_5038_50380302_49_dialog_content = "<size=45><color=#e8d9bb>BAQUE!!!</color></size>",
  ui_story_5038_50380402_1_dialog_content = "Ufa!",
  ui_story_5038_50380402_2_dialog_content = "(Meu corpo todo dói... Minhas costas doem...)",
  ui_story_5038_50380402_3_dialog_content = "(Eu estou vivo embora... apenas.)",
  ui_story_5038_50380402_4_dialog_content = "Você tá bem, PlayerName?",
  ui_story_5038_50380402_5_dialog_content = "Yuebai! Você está vivo!",
  ui_story_5038_50380402_6_dialog_content = "E quanto a... todos os outros?",
  ui_story_5038_50380402_7_dialog_content = "Levante-se antes que o sol queime sua pele, PlayerName.",
  ui_story_5038_50380402_8_dialog_content = "Você parece relativamente ileso, jovem.",
  ui_story_5038_50380402_9_dialog_content = "Você nos deixou preocupados por um segundo.",
  ui_story_5038_50380402_10_dialog_content = "Minha cabeça ainda está doendo... O que exatamente aconteceu ontem à noite?",
  ui_story_5038_50380402_11_dialog_content = "Perdemos o controle do Shadowind depois que ele foi violentamente atingido.",
  ui_story_5038_50380402_12_dialog_content = "Acabamos atingindo alguns recifes.",
  ui_story_5038_50380402_13_dialog_content = "O vento e as ondas diminuíram gradualmente, depois que o peixe-serpente se dispersou.",
  ui_story_5038_50380402_14_dialog_content = "Você e Tianxian ficaram inconscientes em meio ao caos, então foram levados para a cabine de passageiros pela tripulação.",
  ui_story_5038_50380402_15_dialog_content = "Felizmente, nosso pequeno médico Liqing estava disponível. Ele já receitou remédios apropriados para vocês dois.",
  ui_story_5038_50380402_16_dialog_content = "Trazê-los de volta para cá para tomar um pouco de sol também foi ideia minha.",
  ui_story_5038_50380402_17_dialog_content = "Aqui é gostoso e quentinho...",
  ui_story_5038_50380402_18_dialog_content = "Hã?!",
  ui_story_5038_50380402_19_dialog_content = "Eca! O-o que tem na minha boca? É muito amargo!",
  ui_story_5038_50380402_20_dialog_content = "Ei, não cuspa ainda. É uma coisinha para o enjôo.",
  ui_story_5038_50380402_21_dialog_content = "Devil's Breath, madressilva e um pouco de hortelã.",
  ui_story_5038_50380402_22_dialog_content = "Se é amargo, então é bom para você, PlayerName. Mantenha-se firme!",
  ui_story_5038_50380402_23_dialog_content = "T-Tá...",
  ui_story_5038_50380402_24_dialog_content = "Como você consegue se levantar e se movimentar bem, não há muito com o que se preocupar.",
  ui_story_5038_50380402_25_dialog_content = "Mais importante, como está o Shadowind? Depois de tudo que ela passou ontem à noite.",
  ui_story_5038_50380402_26_dialog_content = "Não muito bem.",
  ui_story_5038_50380402_27_dialog_content = "A tempestade quebrou o mastro e o porão está vazando.",
  ui_story_5038_50380402_28_dialog_content = "Você poderia dizer que ela está em suporte de vida. Eu ficaria cauteloso ao levá-la para águas levemente agitadas.",
  ui_story_5038_50380402_29_dialog_content = "Tão ruim?!",
  ui_story_5038_50380402_30_dialog_content = "É muito arriscado zarpar então, não é?",
  ui_story_5038_50380402_31_dialog_content = "... A história está se repetindo. Isso é exatamente o que aconteceu da última vez.",
  ui_story_5038_50380402_32_dialog_content = "Eu teimosamente desejava retomar a rota marítima e fui tolo o suficiente para acreditar que poderia chegar até Astra com minhas próprias habilidades marítimas.",
  ui_story_5038_50380402_33_dialog_content = "Eu estava tão confiante que, mesmo sem o The Compass, teria a sorte de voltar vivo.",
  ui_story_5038_50380402_34_dialog_content = "Olhando para as coisas agora... Acho que os Lins realmente precisam de sua proteção.",
  ui_story_5038_50380402_35_dialog_content = "Pensando na noite passada, aqueles peixes-serpente eram realmente estranhos.",
  ui_story_5038_50380402_36_dialog_content = "Capitão, você é um membro do Lin, deve saber como o peixe-serpente normalmente se comporta.",
  ui_story_5038_50380402_37_dialog_content = "São animais extremamente sociais, e jamais teriam atacado sem as ordens de algum líder.",
  ui_story_5038_50380402_38_dialog_content = "Isso é o que costumávamos pensar.",
  ui_story_5038_50380402_39_dialog_content = "O temperamento desses andarilhos do oceano mudou no último semestre.",
  ui_story_5038_50380402_40_dialog_content = "Eles começaram a atacar navios sem qualquer provocação, não parando até que o navio e todos a bordo morressem.",
  ui_story_5038_50380402_41_dialog_content = "Agora, sou conhecido por me fixar em meus objetivos únicos, mas não vou arriscar com um navio cheio de vidas.",
  ui_story_5038_50380402_42_dialog_content = "Receio que o resto da viagem...",
  ui_story_5038_50380402_43_dialog_content = "O-O quê? Se não podemos continuar, nem podemos ficar aqui para sempre...",
  ui_story_5038_50380402_44_dialog_content = "Não somos apenas patos sentados esperando para morrer?",
  ui_story_5038_50380402_45_dialog_content = "...",
  ui_story_5038_50380402_46_dialog_content = "Capitão...",
  ui_story_5038_50380402_47_dialog_content = "É quase meio-dia, o que há com toda a desgraça e melancolia?",
  ui_story_5038_50380402_48_dialog_content = "Tenho aqui três fortunas para contar. Quem quer isso?",
  ui_story_5038_50380402_49_dialog_content = "Ninguém está com disposição para suas bobagens supersticiosas em um momento como este.",
  ui_story_5038_50380402_50_dialog_content = "Definitivamente não é um absurdo. Os outros podem não estar interessados, capitão, mas acho que você definitivamente deveria me ouvir.",
  ui_story_5038_50380402_51_dialog_content = "Por que eu?",
  ui_story_5038_50380402_52_dialog_content = "Acordei do sonho mais estranho, então tive uma premonição de que algo estava para acontecer.",
  ui_story_5038_50380402_53_dialog_content = "Cada vez que me lembro dos acontecimentos da noite passada, lembro-me de que as revelações tendem a ocorrer em meio à adversidade.",
  ui_story_5038_50380402_54_dialog_content = "Você pode ir direto ao ponto, por favor.",
  ui_story_5038_50380402_55_dialog_content = "Bem bem. Basicamente, decidi perscrutar as brumas do futuro do Shadowind.",
  ui_story_5038_50380402_56_dialog_content = "As ferramentas simples de minha Adivinhação do Hexagrama Celestial, o símbolo yin-yang e os animais do zodíaco, falam de sabedoria para aqueles que se importam em ouvir.",
  ui_story_5038_50380402_57_dialog_content = "Infelizmente, embora eu seja hábil em prever o futuro e calcular destinos, não estou familiarizado com o navio.",
  ui_story_5038_50380402_58_dialog_content = "Portanto, preciso da orientação do nosso bom capitão, para me ajudar a decifrar as respostas fornecidas.",
  ui_story_5038_50380402_59_dialog_content = "Chega de teatralidade. Apenas vá direto ao ponto.",
  ui_story_5038_50380402_60_dialog_content = "A situação do Shadowind é grave. Só podemos fazer o que podemos e rezar para que a sorte esteja do nosso lado.",
  ui_story_5038_50380402_61_dialog_content = "Fui apresentado a um grupo muito estranho de três animais: o rato hesitante, o macaco tolo e o coelho astuto.",
  ui_story_5038_50380402_62_dialog_content = "Em todos os meus anos contando fortunas por toda parte, nunca encontrei uma combinação tão enigmática.",
  ui_story_5038_50380402_63_dialog_content = "Todos os três apareceram com as mesmas combinações de hexagramas yin-yang, o que parece indicar a mesma coisa.",
  ui_story_5038_50380402_64_dialog_content = "Um rato, macaco e coelho...?",
  ui_story_5038_50380402_65_dialog_content = "Qual é a sua interpretação, então?",
  ui_story_5038_50380402_66_dialog_content = "Não sou especialista, mas minha conclusão é que se referem a algo relacionado à troca de uma mercadoria por outra.",
  ui_story_5038_50380402_67_dialog_content = "\"O que é ilusão torna-se real, quando o que é real torna-se ilusão.\" Essencialmente, está nos dizendo para <color=#FFB400>substituir</color> aquilo que perdemos.",
  ui_story_5038_50380402_68_dialog_content = "Substituir...?",
  ui_story_5038_50380402_69_dialog_content = "Oh! Acho que entendi!",
  ui_story_5038_50380402_70_dialog_content = "O costume de nossa pátria é nomear as partes importantes do casco de um navio com os nomes dos 12 animais do zodíaco.",
  ui_story_5038_50380402_71_dialog_content = "Rezamos para que isso nos traga boa sorte, para que possamos navegar pelo mar tão firmemente quanto as criaturas que pisam na terra.",
  ui_story_5038_50380402_72_dialog_content = "Muitas seções do casco foram danificadas na tempestade da noite passada.",
  ui_story_5038_50380402_73_dialog_content = "Incluindo a cauda do rato na popa e a cabeça do macaco na proa. O primeiro está totalmente perdido e o outro está danificado.",
  ui_story_5038_50380402_74_dialog_content = "Mas as grades laterais, as orelhas de coelho, estão boas.",
  ui_story_5038_50380402_75_dialog_content = "Hmm... Então vou meditar mais sobre as orelhas de coelho.",
  ui_story_5038_50380402_76_dialog_content = "Mas se você encontrar algo para substituir os dois primeiros, o Shadowind pelo menos poderá navegar?",
  ui_story_5038_50380402_77_dialog_content = "Isso ajudará a torná-la navegável, mas não é suficiente.",
  ui_story_5038_50380402_78_dialog_content = "O casco está danificado em vários lugares, então não podemos cortar nenhum canto. Temos que consertar o navio, seção por seção.",
  ui_story_5038_50380402_79_dialog_content = "Além disso, onde exatamente devo encontrar as substituições para essas peças?",
  ui_story_5038_50380402_80_dialog_content = "Posso ter uma ideia.",
  ui_story_5038_50380402_81_dialog_content = "Logo abaixo de nós está um dos maiores cofres do tesouro - o mar.",
  ui_story_5038_50380501_1_dialog_content = "(Zhong Xu e Yuebai decidiram no final não usar os botes salva-vidas e permanecer no Shadowind.)",
  ui_story_5038_50380501_2_dialog_content = "(Eles até levantaram a âncora.)",
  ui_story_5038_50380501_3_dialog_content = "(... Está tudo bem em zarpar tão cedo?)",
  ui_story_5038_50380501_4_dialog_content = "Fizemos uma escolha arriscada.",
  ui_story_5038_50380501_5_dialog_content = "No entanto, o oceano engoliu inúmeras embarcações. Se pudéssemos chegar onde os piratas nos atacaram meio ano atrás...",
  ui_story_5038_50380501_6_dialog_content = "Talvez possamos salvar algumas peças úteis.",
  ui_story_5038_50380501_7_dialog_content = "Embora eu saiba que isso é equivalente a procurar uma agulha no palheiro.",
  ui_story_5038_50380501_8_dialog_content = "No entanto, estamos no nosso último recurso.",
  ui_story_5038_50380501_9_dialog_content = "Concordo.",
  ui_story_5038_50380501_10_dialog_content = "De qualquer maneira, os botes salva-vidas a bordo não seriam capazes de resistir a uma tempestade.",
  ui_story_5038_50380501_11_dialog_content = "Nem podemos ficar à deriva na água para sempre.",
  ui_story_5038_50380501_12_dialog_content = "É melhor pelo menos remar com bom tempo do que sentar e apodrecer.",
  ui_story_5038_50380501_13_dialog_content = "Tudo bem, tripulação. Traga a vela danificada e estenda os remos.",
  ui_story_5038_50380501_14_dialog_content = "Seguiremos as cartas náuticas e remaremos até o local do naufrágio.",
  ui_story_5038_50380501_15_dialog_content = "Mesmo que sejam ordens do Capitão, ainda acho muito arriscado...",
  ui_story_5038_50380501_16_dialog_content = "Cuidado com a língua, rapaz. Melhor não dizer essas coisas ainda a bordo.",
  ui_story_5038_50380501_17_dialog_content = "Mesmo que nos deparemos com um desastre, não é como se tivéssemos qualquer controle sobre nossas vidas.",
  ui_story_5038_50380501_18_dialog_content = "O capitão Yuebai é alguém cujo julgamento você deveria questionar?",
  ui_story_5038_50380501_19_dialog_content = "P-Princesa Dantang...",
  ui_story_5038_50380501_20_dialog_content = "Se você tem reclamações, a porta dela está sempre aberta. Tenho certeza que ela ficaria feliz em trabalhar juntos para encontrar uma solução.",
  ui_story_5038_50380501_21_dialog_content = "Sobre essas águas turbulentas, se não se teme nem a morte, que medo teria de insultar alguém na cara?",
  ui_story_5038_50380501_22_dialog_content = "O que tá acontecendo aqui?",
  ui_story_5038_50380501_23_dialog_content = "Ah, Yuebai. Esses caras têm algo que gostariam de dizer a você.",
  ui_story_5038_50380501_24_dialog_content = "N-Não, eu não. Não. Nenhuma coisa.",
  ui_story_5038_50380501_25_dialog_content = "Eu também não. Por favor, princesa... Poupe-nos.",
  ui_story_5038_50380501_26_dialog_content = "...",
  ui_story_5038_50380501_27_dialog_content = "<color=#e8d9bb>Swish... Swash!</color>",
  ui_story_5038_50380501_28_dialog_content = "H-Tenha piedade de nós, capitão! Nós...",
  ui_story_5038_50380501_29_dialog_content = "Inversão de marcha.",
  ui_story_5038_50380501_30_dialog_content = "Ahn???",
  ui_story_5038_50380501_31_dialog_content = "Graah...",
  ui_story_5038_50380501_32_dialog_content = "Embarcar em um navio em plena luz do dia? Quão terrivelmente rude!",
  ui_story_5038_50380501_33_dialog_content = "Você não pode ensinar boas maneiras a essas coisas.",
  ui_story_5038_50380501_34_dialog_content = "Fique atrás de mim, vocês dois.",
  ui_story_5038_50380501_35_dialog_content = "Eu não vou simplesmente deixar você morrer.",
  ui_story_5038_50380501_36_dialog_content = "A-Sim, capitão!",
  ui_story_5038_50380602_1_dialog_content = "Rabo de rato, cabeça de macaco, orelhas de coelho...",
  ui_story_5038_50380602_2_dialog_content = "Que enigmático. Os nomes realmente não oferecem muitas pistas sobre o que são, miau.",
  ui_story_5038_50380602_3_dialog_content = "Simplificando, eles representam um cata-vento, uma polia e uma prancha.",
  ui_story_5038_50380602_4_dialog_content = "<color=#FFB400>cata-ventos</color> precisa ser instalado bem no topo do mastro.",
  ui_story_5038_50380602_5_dialog_content = "A corda amarrada à popa lembra um pouco o rabo de um rato.",
  ui_story_5038_50380602_6_dialog_content = "Ele flutua, por ser tão leve.",
  ui_story_5038_50380602_7_dialog_content = "<color=#FFB400>Polias</color> são bastante padrão, visto que são necessários para gerenciar as velas.",
  ui_story_5038_50380602_8_dialog_content = "Eles são chamados de \"cabeças de macaco\" por causa de seu tamanho e forma.",
  ui_story_5038_50380602_9_dialog_content = "Se conseguirmos encontrar substitutos para esses dois, poderemos usar nossas velas novamente.",
  ui_story_5038_50380602_10_dialog_content = "Uau, você faz parecer tão fácil!",
  ui_story_5038_50380602_11_dialog_content = "E as orelhas de coelho, então?",
  ui_story_5038_50380602_12_dialog_content = "... Esses são especiais e não são facilmente substituídos.",
  ui_story_5038_50380602_13_dialog_content = "Felizmente, nossas orelhas de coelho não foram danificadas, então vamos nos concentrar nas outras duas primeiro.",
  ui_story_5038_50380602_14_dialog_content = "Sim!",
  ui_story_5038_50380602_15_dialog_content = "Você poderia nos dar uma mão, PlayerName, Dantang?",
  ui_story_5038_50380602_16_dialog_content = "Claro que não!",
  ui_story_5038_50380602_17_dialog_content = "(Eu não tenho ideia do que está acontecendo...!)",
  ui_story_5038_50380602_18_dialog_content = "Não precisa fingir, Alteza. Em casa, você raramente se aventurava fora do terreno, afinal.",
  ui_story_5038_50380602_19_dialog_content = "É natural que você não entenda essas coisas.",
  ui_story_5038_50380602_20_dialog_content = "... Pode ser como você diz, mas ainda quero ajudar.",
  ui_story_5038_50380602_21_dialog_content = "Bem, visto que você não acha que eu preciso me provar, então eu acho que você não precisa me seguir por toda parte.",
  ui_story_5038_50380602_22_dialog_content = "P-Princesa...",
  ui_story_5038_50380602_23_dialog_content = "Que teimoso, miau!",
  ui_story_5038_50380602_24_dialog_content = "Por favor, evite tais avaliações indelicadas da princesa.",
  ui_story_5038_50380602_25_dialog_content = "Está bem, está bem! Vamos seguir em frente, PlayerName.",
  ui_story_5038_50380602_26_dialog_content = "Mas... não faço ideia de onde devemos ir, ou como devemos começar a procurar.",
  ui_story_5038_50380602_27_dialog_content = "Hum, vamos ver...",
  ui_story_5038_50380602_28_dialog_content = "Tinytail e eu vamos farejar as coisas primeiro. Vamos farejar pelo convés!",
  ui_story_5038_50380602_29_dialog_content = "Nós, gatos, podemos sentir o cheiro do rabo de um rato a um quilômetro de distância!",
  ui_story_5038_50380602_30_dialog_content = "Hum, não tenho certeza se estamos falando da mesma coisa...!",
  ui_story_5038_50380602_31_dialog_content = "<color=#e8d9bb>Cabine de Passageiros Shadowind</color>",
  ui_story_5038_50380602_32_dialog_content = "Hrrgh...",
  ui_story_5038_50380602_33_dialog_content = "(Tenho que procurar em todos os lugares...)",
  ui_story_5038_50380602_34_dialog_content = "O que você está procurando, princesa?",
  ui_story_5038_50380602_35_dialog_content = "Nada que seja da sua conta.",
  ui_story_5038_50380602_36_dialog_content = "Ei, não seja tão rápido em me recusar! Em vez de olhar cegamente, por que não me deixa adivinhar para você, hmm?",
  ui_story_5038_50380602_37_dialog_content = "... Você está realmente comprometido com o seu golpe.",
  ui_story_5038_50380602_38_dialog_content = "Bem, certamente os eventos recentes provaram que isso não é um golpe.",
  ui_story_5038_50380602_39_dialog_content = "Eu admito isso... Embora possa ter sido um palpite de sorte.",
  ui_story_5038_50380602_40_dialog_content = "Estou procurando o rabo de rato que o capitão disse que estava faltando.",
  ui_story_5038_50380602_41_dialog_content = "Você está procurando no navio?",
  ui_story_5038_50380602_42_dialog_content = "Sim, considerando tudo, essa é minha conclusão provisória.",
  ui_story_5038_50380602_43_dialog_content = "O capitão disse que esse rabo de rato era muito leve e flutuaria se jogado na água.",
  ui_story_5038_50380602_44_dialog_content = "A tripulação tem patrulhado o navio constantemente desde o incidente da noite passada.",
  ui_story_5038_50380602_45_dialog_content = "Os marinheiros da Lin Guild são lendários no que fazem. Eles notariam até mesmo um alfinete que caísse no mar.",
  ui_story_5038_50380602_46_dialog_content = "Então, o que quer que seja, ainda deve estar no navio.",
  ui_story_5038_50380602_47_dialog_content = "Muito perspicaz, princesa! Concordo com sua linha de pensamento.",
  ui_story_5038_50380602_48_dialog_content = "Assim sendo, vamos revistar o navio.",
  ui_story_5038_50380602_49_dialog_content = "Squawk! Jabber!",
  ui_story_5038_50380602_50_dialog_content = "Sim, eu sei.",
  ui_story_5038_50380602_51_dialog_content = "Pare de empurrar, pare de empurrar.",
  ui_story_5038_50380602_52_dialog_content = "Estorninhos falantes?!",
  ui_story_5038_50380602_53_dialog_content = "Eu os treinei para imitar a fala humana.",
  ui_story_5038_50380602_54_dialog_content = "Vá agora, Squawk e Jabber, veja se consegue encontrar este misterioso cata-vento parecido com um rato.",
  ui_story_5038_50380602_55_dialog_content = "Tenho mimos esperando por você.",
  ui_story_5038_50380602_56_dialog_content = "<color=#e8d9bb>*Bater*... *Bater*...</color>",
  ui_story_5038_50380602_57_dialog_content = "Não vai confiar em sua adivinhação confiável desta vez?",
  ui_story_5038_50380602_58_dialog_content = "Bons pássaros escolhem bons mestres. E de qualquer maneira, em momentos como este, uma visão panorâmica é melhor do que adivinhação.",
  ui_story_5038_50380602_59_dialog_content = "Vamos, princesa. Vamos seguir nossos dois caçadores de tesouros.",
  ui_story_5038_50380602_60_dialog_content = "Esse rabinho de rato não vai ficar escondido por muito mais tempo.",
  ui_story_5038_50380602_61_dialog_content = "<color=#e8d9bb>Cau! Cau!</color>",
  ui_story_5038_50380602_62_dialog_content = "Dê-me tâmaras gordas e doces, caw!",
  ui_story_5038_50380602_63_dialog_content = "Dê-me deliciosas e doces sementes de melão, caw!",
  ui_story_5038_50380602_64_dialog_content = "Eu sei eu sei. Você receberá suas guloseimas. Você achou isso?",
  ui_story_5038_50380602_65_dialog_content = "Isso...",
  ui_story_5038_50380602_66_dialog_content = "Parece muito com um rabo... Deve ser isso!",
  ui_story_5038_50380602_67_dialog_content = "Sim! Parece que você está absolutamente certo.",
  ui_story_5038_50380602_68_dialog_content = "Sorte que vocês dois conseguiram localizá-lo no meio de toda aquela sujeira.",
  ui_story_5038_50380602_69_dialog_content = "Você receberá suas tâmaras saborosas e sementes de melão em breve!",
  ui_story_5038_50380602_70_dialog_content = "Pegue, princesa.",
  ui_story_5038_50380602_71_dialog_content = "Vá trazê-lo para o capitão Yuebai.",
  ui_story_5038_50380701_1_dialog_content = "(Depois que Dantang deu o \"rabo do rato\" para Yuebai...)",
  ui_story_5038_50380701_2_dialog_content = "(Os reparos do navio estão indo bem e o mastro está quase restaurado.)",
  ui_story_5038_50380701_3_dialog_content = "(Está navegando muito mais suavemente, quase como se o acidente nunca tivesse acontecido.)",
  ui_story_5038_50380701_4_dialog_content = "(É apenas...)",
  ui_story_5038_50380701_5_dialog_content = "O vento mudou. Prepare-se para parar de remar e lançar âncora!",
  ui_story_5038_50380701_6_dialog_content = "Sim!",
  ui_story_5038_50380701_7_dialog_content = "(Exceto que ainda temos que parar de repente de vez em quando.)",
  ui_story_5038_50380701_8_dialog_content = "Você parece preocupado, jovem.",
  ui_story_5038_50380701_9_dialog_content = "Eu não sou. Eu acho... eu confio no julgamento de Yuebai.",
  ui_story_5038_50380701_10_dialog_content = "Não há necessidade de esconder como você se sente. Suspeito que estamos pensando a mesma coisa.",
  ui_story_5038_50380701_11_dialog_content = "(Ele viu através de mim...)",
  ui_story_5038_50380701_12_dialog_content = "Estamos indo para o último local conhecido do The Compass com a ajuda das cartas náuticas.",
  ui_story_5038_50380701_13_dialog_content = "Mas o navio ainda está em condições precárias, e os reparos temporários são mais um reboco do que uma cura.",
  ui_story_5038_50380701_14_dialog_content = "Velejar é uma habilidade muito precisa com pouco espaço para erros.",
  ui_story_5038_50380701_15_dialog_content = "Orações por si só não garantirão que tudo corra bem.",
  ui_story_5038_50380701_16_dialog_content = "... É apenas uma pequena preocupação minha, no entanto.",
  ui_story_5038_50380701_17_dialog_content = "Não leve isso a sério.",
  ui_story_5038_50380701_18_dialog_content = "Certo. Vou tentar me recompor. E Zhong Xu, lembre-se de não se preocupar muito também!",
  ui_story_5038_50380701_19_dialog_content = "O Shadowind experimentou todos os tipos de obstáculos, mas conseguiu chegar com segurança em Astra; de jeito nenhum ela nos deixaria morrer no mar.",
  ui_story_5038_50380701_20_dialog_content = "Silêncio!",
  ui_story_5038_50380701_21_dialog_content = "O-o que?!",
  ui_story_5038_50380701_22_dialog_content = "... Desculpe, eu exagerei.",
  ui_story_5038_50380701_23_dialog_content = "Na minha cidade natal, dizer essas coisas é considerado um tabu quando a chegada de um novo ano está se aproximando.",
  ui_story_5038_50380701_24_dialog_content = "Sei que é apenas um pequeno costume inofensivo, mas espero que entenda.",
  ui_story_5038_50380701_25_dialog_content = "Agora com licença, vou me despedir.",
  ui_story_5038_50380701_26_dialog_content = "(Ele quis dizer... falar sobre a morte é um tabu?)",
  ui_story_5038_50380701_27_dialog_content = "Você não costuma ver Zhong Xu ficar tão agitado.",
  ui_story_5038_50380701_28_dialog_content = "Acho que ele está preocupado em cometer os mesmos erros de seis meses atrás.",
  ui_story_5038_50380701_29_dialog_content = "PlayerName, você poderia me dar uma mão?",
  ui_story_5038_50380701_30_dialog_content = "Estou apenas movendo silenciosamente este pequeno barco salva-vidas de madeira para os trilhos.",
  ui_story_5038_50380701_31_dialog_content = "Huh? Espere! Isso não é basicamente apenas <color=#FFB400>roubando</color>?",
  ui_story_5038_50380701_32_dialog_content = "Vamos, não seja dramático, miau.",
  ui_story_5038_50380701_33_dialog_content = "Olha, o capitão e Zhong Xu estão discutindo infiltrações e prevenção de vazamentos.",
  ui_story_5038_50380701_34_dialog_content = "Eu não poderia interrompê-los por isso.",
  ui_story_5038_50380701_35_dialog_content = "Mas o que você pretende fazer com o bote salva-vidas?",
  ui_story_5038_50380701_36_dialog_content = "Salve a \"cabeça de macaco\", é claro!",
  ui_story_5038_50380701_37_dialog_content = "De jeito nenhum! É muito perigoso!",
  ui_story_5038_50380701_38_dialog_content = "Escute-me, PlayerName. Se o Shadowind fosse uma pessoa, ela estaria doente agora.",
  ui_story_5038_50380701_39_dialog_content = "As doenças precisam ser tratadas com a cura certa. Algumas ervas são simples de obter.",
  ui_story_5038_50380701_40_dialog_content = "Enquanto alguns crescem no meio de um penhasco vertical, longe do alcance de qualquer pessoa.",
  ui_story_5038_50380701_41_dialog_content = "A cabeça do macaco está danificada e não há substituto adequado a bordo.",
  ui_story_5038_50380701_42_dialog_content = "Para curar a doença, preciso sair para o mar.",
  ui_story_5038_50380701_43_dialog_content = "O mar?? Achas que vais encontrar alguma coisa lá fora quando nem a bordo consegues encontrar?",
  ui_story_5038_50380701_44_dialog_content = "Não sei se você notou, mas tem todo tipo de coisa flutuando por aqui.",
  ui_story_5038_50380701_45_dialog_content = "Esses restos são tudo o que resta de navios desconhecidos do passado, perdidos no mar sabe-se lá quando.",
  ui_story_5038_50380701_46_dialog_content = "Se eu conseguir encontrar outra \"cabeça de macaco\" em uma dessas naves, com certeza isso resolveria o problema do Shadowind.",
  ui_story_5038_50380701_47_dialog_content = "Iremos muito mais rápido quando pudermos içar as velas! Podemos nos preocupar com as \"orelhas de coelho\" então!",
  ui_story_5038_50380701_48_dialog_content = "Você tem razão, mas isso é realmente viável?",
  ui_story_5038_50380701_49_dialog_content = "É como procurar uma agulha no palheiro que é o oceano.",
  ui_story_5038_50380701_50_dialog_content = "É viável se eu disser que é, PlayerName. Eu sou o demônio aqui, afinal.",
  ui_story_5038_50380701_51_dialog_content = "Minhas <color=#FFB400>amigos marinhos</color> me dará sinais e sinais.",
  ui_story_5038_50380701_52_dialog_content = "você é de verdade?",
  ui_story_5038_50380701_53_dialog_content = "É claro. Costumo falar com eles quando estou no mar.",
  ui_story_5038_50380701_54_dialog_content = "Se eu pedir ajuda, eles irão fornecer.",
  ui_story_5038_50380701_55_dialog_content = "Incluindo ajudá-lo a encontrar a \"cabeça de macaco\" de outro navio?",
  ui_story_5038_50380701_56_dialog_content = "Mas... como eles saberiam como é uma coisa dessas?",
  ui_story_5038_50380701_57_dialog_content = "Não se preocupe com isso. Eu posso descrevê-lo para eles.",
  ui_story_5038_50380701_58_dialog_content = "De qualquer forma, obrigado por ajudar, PlayerName! Eu posso pegar daqui!",
  ui_story_5038_50380701_59_dialog_content = "Ainda estou um pouco preocupado. Estarei de olho em você via telepatia.",
  ui_story_5038_50380701_60_dialog_content = "Se você tiver algum problema, é melhor me avisar através do nosso link, entendeu?",
  ui_story_5038_50380701_61_dialog_content = "Está bem, está bem. Apenas aguente firme e espere pelas minhas boas notícias!",
  ui_story_5038_50380701_62_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5038_50380701_63_dialog_content = "Yaaaaah!!!",
  ui_story_5038_50380701_64_dialog_content = "Que? O que é isso?! Liqing!",
  ui_story_5038_50380701_65_option_content = "Aumento de Força!",
  ui_story_5038_50380701_66_dialog_content = "(Muita água! Muita água! Água, água, por todo lado...!)",
  ui_story_5038_50380701_67_dialog_content = "Wah... PlayerName! Tem, tipo, água EM TODO LUGAR!",
  ui_story_5038_50380701_68_dialog_content = "Você está no mar, o que você esperava?!",
  ui_story_5038_50380701_69_dialog_content = "Espere, você não está dizendo que tem medo de água, está?",
  ui_story_5038_50380701_70_dialog_content = "Bem, duh! Gatos que não gostam de água não é novidade!",
  ui_story_5038_50380701_71_dialog_content = "(Oh, o pobre Liqing está tremendo violentamente. O acidente há seis meses deve tê-lo deixado profundamente marcado.)",
  ui_story_5038_50380701_72_dialog_content = "C-volte, rápido! Tente não se mover muito, e eu vou içar você e o barco de volta...",
  ui_story_5038_50380701_73_dialog_content = "Huff... Huff",
  ui_story_5038_50380701_74_dialog_content = "Miau...",
  ui_story_5038_50380701_75_dialog_content = "O que diabos você estava pensando? Por que você insiste em descer quando tem tanto medo de água?",
  ui_story_5038_50380701_76_dialog_content = "Eu pensei que poderia fazer isso sozinho...",
  ui_story_5038_50380701_77_dialog_content = "Hum... Enfim, PlayerName, agora que estamos aqui, receio ter que pedir um favor.",
  ui_story_5038_50380701_78_dialog_content = "Deixa eu adivinhar: você vai ficar bem se eu for com você?",
  ui_story_5038_50380701_79_dialog_content = "Bem, todo mundo está ocupado consertando a nave. Vamos ser rápidos sobre isso.",
  ui_story_5038_50380701_80_dialog_content = "Beleza!",
  ui_story_5038_50380701_81_dialog_content = "(Antes de sair, provavelmente devo refrescar minha memória sobre o protocolo de segurança...)",
  ui_story_5038_50380701_82_dialog_content = "Graah!!",
  ui_story_5038_50380701_83_dialog_content = "Só podes estar a brincar comigo...",
  ui_story_5038_50380701_84_dialog_content = "Eles escolheram agora, de todos os tempos, escalar aquela corda?!",
  ui_story_5038_50380702_1_dialog_content = "Ouçam-me, amigos! Estou procurando um objeto que se pareça com a silhueta da cabeça de um macaco.",
  ui_story_5038_50380702_2_dialog_content = "Algo grande, redondo e resistente.",
  ui_story_5038_50380702_3_dialog_content = "Pode estar emaranhado com algumas cordas.",
  ui_story_5038_50380702_X3_dialog_content = "Então, seus amigos são... esses peixes?",
  ui_story_5038_50380702_4_dialog_content = "Urgh... *Tosse*...",
  ui_story_5038_50380702_5_dialog_content = "Você está bem? Sentindo-se enjoado?",
  ui_story_5038_50380702_6_dialog_content = "Buzi diz que os médicos não devem tratar-se sozinhos. Acho que era disso que ele estava falando.",
  ui_story_5038_50380702_7_dialog_content = "Posso fazer alguma coisa para você?",
  ui_story_5038_50380702_8_dialog_content = "Já que você perguntou... Um belo arranhão no queixo seria ótimo—",
  ui_story_5038_50380702_9_dialog_content = "MAS! *Tosse*... Coçar o queixo e tudo mais ao estilo do Tinytail!",
  ui_story_5038_50380702_10_dialog_content = "Não sou mais apenas um gato, então obviamente não gostaria dessas coisas!",
  ui_story_5038_50380702_11_dialog_content = "(Que fofo...)",
  ui_story_5038_50380702_12_dialog_content = "Falando nisso, há algum demônio de onde você vem, PlayerName?",
  ui_story_5038_50380702_13_dialog_content = "Bem, eu tenho alguns amigos aurorianos que são demi-humanos.",
  ui_story_5038_50380702_14_dialog_content = "A maioria deles são descendentes de semi-humanos e aurorianos, e são bastante raros.",
  ui_story_5038_50380702_15_dialog_content = "Eu vejo. Soa um pouco diferente para fiendlings.",
  ui_story_5038_50380702_16_dialog_content = "Você sabe que Tinytail é meu irmão mais velho?",
  ui_story_5038_50380702_17_dialog_content = "V-seu o que...?!",
  ui_story_5038_50380702_18_dialog_content = "É por isso que Tianxian está sempre chamando você de gatinho? Porque você realmente é um?",
  ui_story_5038_50380702_19_dialog_content = "E-É muito rude da parte dele me chamar assim.",
  ui_story_5038_50380702_20_dialog_content = "Mas você está certo. Em minha terra natal, os demônios são animais que se transformaram em aurorianos.",
  ui_story_5038_50380702_21_dialog_content = "As famílias influentes em Longzhou que defendem a paz costumam convidar demônios para suas casas como convidados.",
  ui_story_5038_50380702_22_dialog_content = "Eles meio que funcionam como retentores.",
  ui_story_5038_50380702_23_dialog_content = "Na verdade, foi assim que conheci o Lin Guildmaster.",
  ui_story_5038_50380702_24_dialog_content = "Ele parece ser uma pessoa que realmente valoriza a amizade.",
  ui_story_5038_50380702_25_dialog_content = "Ehh... Para ser honesto, mal consigo entender uma palavra das coisas de negócios sobre as quais todos aqueles velhos tagarelam.",
  ui_story_5038_50380702_26_dialog_content = "Os Lins me convidaram para sua mansão porque queriam que eu os ajudasse <color=#FFB400>cuidar de seus peixes</color>.",
  ui_story_5038_50380702_27_dialog_content = "Eu sei que todo mundo pensa que os gatos comem peixe, mas os peixes do mar são meus amigos.",
  ui_story_5038_50380702_28_dialog_content = "Você quer dizer que pode se comunicar com o peixe-serpente?",
  ui_story_5038_50380702_29_dialog_content = "Mais ou menos. É verdade, mas olhe para a outra noite. Não pude fazer nada para ajudar, em meio a uma crise...",
  ui_story_5038_50380702_30_dialog_content = "Oh! Nossos amigos aquáticos responderam.",
  ui_story_5038_50380702_31_dialog_content = "A \"cabeça de macaco\" está logo abaixo de nós, PlayerName!",
  ui_story_5038_50380702_32_dialog_content = "Sério?",
  ui_story_5038_50380702_33_dialog_content = "Sim. Provavelmente está emaranhado em algas marinhas.",
  ui_story_5038_50380702_34_dialog_content = "Espere, deixe-me dar uma olhada com a minha rede...",
  ui_story_5038_50380702_35_dialog_content = "Ei... Ho—",
  ui_story_5038_50380702_36_dialog_content = "Confira, PlayerName.",
  ui_story_5038_50380702_37_dialog_content = "T-Isso é incrível!",
  ui_story_5038_50380702_38_dialog_content = "Quase como mágica!",
  ui_story_5038_50380702_39_dialog_content = "Disse que meus amigos do oceano viriam.",
  ui_story_5038_50380702_40_dialog_content = "Agora que temos uma nova \"cabeça de macaco\", podemos contribuir com os reparos do navio!",
  ui_story_5038_50380702_41_dialog_content = "Sim, embora tenhamos que voltar primeiro!",
  ui_story_5038_50380702_42_dialog_content = "Isso certamente levantará o ânimo de todos a bordo.",
  ui_story_5038_50380702_43_dialog_content = "Tudo bem.",
  ui_story_5038_50380702_44_dialog_content = "(Eu me pergunto como ele está fazendo...)",
  ui_story_5038_50380702_45_dialog_content = "<color=#e8d9bb>no convés</color>",
  ui_story_5038_50380702_46_dialog_content = "Ei! Liqing e PlayerName estão de volta!",
  ui_story_5038_50380702_47_dialog_content = "Eu disse que aqueles dois ficariam bem.",
  ui_story_5038_50380702_48_dialog_content = "Hehe, com certeza você fez. Mas você também não parecia ter muito apetite antes.",
  ui_story_5038_50380702_49_dialog_content = "PlayerName, Liqing! O que você fez foi incrivelmente arriscado!",
  ui_story_5038_50380702_50_dialog_content = "Você pensou nas consequências antes de partir?",
  ui_story_5038_50380702_51_dialog_content = "Olha, capitão.",
  ui_story_5038_50380702_52_dialog_content = "...!",
  ui_story_5038_50380702_53_dialog_content = "Uma polia?!",
  ui_story_5038_50380702_54_dialog_content = "Obviamente, foi imerso em água do mar, mas deve ser reparado após uma boa limpeza.",
  ui_story_5038_50380702_55_dialog_content = "Onde você achou isso?",
  ui_story_5038_50380702_56_dialog_content = "No mar!",
  ui_story_5038_50380702_57_dialog_content = "Vocês dois fugiram do navio?",
  ui_story_5038_50380702_58_dialog_content = "Isso foi uma coisa incrivelmente perigosa de se fazer. Com todos absortos em seu trabalho, o que teria acontecido se você tivesse problemas? Ninguém teria sido capaz de ajudar.",
  ui_story_5038_50380702_59_dialog_content = "Mas estamos bem, não estamos? Nada de ruim aconteceu!",
  ui_story_5038_50380702_60_dialog_content = "Pode ter sido um pouco arriscado, mas acabou bem.",
  ui_story_5038_50380702_61_dialog_content = "Você mesmo disse, Yuebai. Esta jornada estava fadada a ser arriscada.",
  ui_story_5038_50380702_62_dialog_content = "Graças a Liqing, temos nossa polia \"cabeça de macaco\". Ele deve ser elogiado!",
  ui_story_5038_50380702_63_dialog_content = "Vocês...",
  ui_story_5038_50380702_64_dialog_content = "Multar. Não posso negar que ter isso ajudará muito no progresso do reparo da nave. Então, por isso, eu agradeço.",
  ui_story_5038_50380702_65_dialog_content = "Mas é melhor eu não pegar você fugindo do navio sem permissão novamente.",
  ui_story_5038_50380702_66_dialog_content = "Demitido. Vá jantar.",
  ui_story_5038_50380702_67_dialog_content = "Venham aqui, rapazes.",
  ui_story_5038_50380702_68_dialog_content = "Enquanto todos estavam ocupados, Jiu preparou alguns pratos tradicionais de volta para casa.",
  ui_story_5038_50380702_69_dialog_content = "Hum! Eu não percebi como eu estava com fome!",
  ui_story_5038_50380702_70_dialog_content = "Cheira bem, Princesa Dantan! Não me diga que vamos comer carne de porco assada?!",
  ui_story_5038_50380702_71_dialog_content = "Que olfato aguçado! O almoço de hoje é mesmo <color=#FFB400>Carne de porco assada</color>!",
  ui_story_5038_50380702_72_dialog_content = "Você pega um bom e sólido pedaço de carne e o amarra, coloca em uma panela cheia de vários temperos e deixa ferver...",
  ui_story_5038_50380702_73_dialog_content = "Podemos estar um pouco limitados em ingredientes no navio, mas acho que o sabor está próximo o suficiente.",
  ui_story_5038_50380702_74_dialog_content = "Vá comer. Eu ainda tenho algum trabalho a fazer.",
  ui_story_5038_50380702_75_dialog_content = "Com a polia de substituição, devo conseguir terminar de reparar o mastro rapidamente.",
  ui_story_5038_50380702_76_dialog_content = "Em breve poderemos retomar a velocidade normal.",
  ui_story_5038_50380702_77_dialog_content = "Eu posso ajudar!",
  ui_story_5038_50380702_78_dialog_content = "<color=#e8d9bb>Rosnar-</color>",
  ui_story_5038_50380702_79_dialog_content = "Haha... Parece que você deveria ir com eles primeiro.",
  ui_story_5038_50380702_80_dialog_content = "Jamais se dirá que um hóspede dos Lins foi posto para trabalhar de estômago vazio.",
  ui_story_5038_50380801_1_dialog_content = "(A velocidade do navio pode ter voltado ao normal, mas o estado do casco ainda é um pouco preocupante.)",
  ui_story_5038_50380801_2_dialog_content = "(Todos estão trabalhando sem parar, como se o Shadowind fosse afundar se eles parassem por um segundo.)",
  ui_story_5038_50380801_3_dialog_content = "(Parece que pensamos que nos exaurirmos é um antídoto para a preocupação.)",
  ui_story_5038_50380801_4_dialog_content = "Navega um pouco mais para bombordo, tripulação. O vento mudou.",
  ui_story_5038_50380801_5_dialog_content = "Sim!",
  ui_story_5038_50380801_6_dialog_content = "Como está o porão de carga?",
  ui_story_5038_50380801_7_dialog_content = "Ainda vazando, então temos que enviar alguém para tirar a água.",
  ui_story_5038_50380801_8_dialog_content = "Felizmente não está piorando e ainda podemos lidar com isso.",
  ui_story_5038_50380801_9_dialog_content = "Entendido. Elabore um cronograma e faça turnos para descansar.",
  ui_story_5038_50380801_10_dialog_content = "Não temos ideia de quanto tempo essas circunstâncias vão durar, então precisamos nos controlar.",
  ui_story_5038_50380801_11_dialog_content = "Sim!",
  ui_story_5038_50380801_12_dialog_content = "Espero que nosso curso esteja se mantendo. Estou indo para a ponte para verificar as coisas.",
  ui_story_5038_50380801_13_dialog_content = "(Yuebai está constantemente em movimento. Ela nem para quando fala.)",
  ui_story_5038_50380801_14_dialog_content = "(Ela tem mais em que pensar do que o resto de nós, e isso obviamente coloca ainda mais pressão sobre ela.)",
  ui_story_5038_50380801_15_dialog_content = "(Talvez seus passos possam tapar alguns dos buracos em The Shadowind.)",
  ui_story_5038_50380801_16_dialog_content = "Outro avistamento...",
  ui_story_5038_50380801_17_dialog_content = "Quantos são agora, Jiu?",
  ui_story_5038_50380801_18_dialog_content = "42, Alteza.",
  ui_story_5038_50380801_19_dialog_content = "Tantos já.",
  ui_story_5038_50380801_20_dialog_content = "Eles continuam vindo da direção que estamos seguindo... É realmente muito preocupante.",
  ui_story_5038_50380801_21_dialog_content = "(Muita madeira flutuante foi avistada desde a manhã.)",
  ui_story_5038_50380801_22_dialog_content = "(A cabeça do macaco ontem era apenas a ponta do iceberg. Agora estamos vendo os restos de incontáveis destroços, todos perdidos no mar aqui.)",
  ui_story_5038_50380801_23_dialog_content = "(Dantang descansa constantemente ao lado do navio, olhando para o mar, contando cada pedaço de madeira flutuante.)",
  ui_story_5038_50380801_24_dialog_content = "(Somente nós testemunhamos esses remanescentes daqueles que sucumbiram às ondas.)",
  ui_story_5038_50380801_25_dialog_content = "O que é preocupante? Acho que é um bom sinal.",
  ui_story_5038_50380801_26_dialog_content = "Se houver destroços em nosso caminho, significa que estamos no caminho certo.",
  ui_story_5038_50380801_27_dialog_content = "Você não acha que um oceano totalmente deserto e vazio é muito mais assustador?",
  ui_story_5038_50380801_28_dialog_content = "(Liqing passa, peixe seco pendurado em sua boca.)",
  ui_story_5038_50380801_29_dialog_content = "(Ele está ajudando, mas sempre parece ter uma atitude tão indiferente.)",
  ui_story_5038_50380801_30_dialog_content = "(Talvez ele esteja tentando transformar todo o trabalho em um jogo.)",
  ui_story_5038_50380801_31_dialog_content = "Ahhh... estou exausta.",
  ui_story_5038_50380801_32_dialog_content = "A água no porão de carga continua chegando, não importa o quanto você saia.",
  ui_story_5038_50380801_33_dialog_content = "Decidiu vir se juntar a nós, PlayerName?",
  ui_story_5038_50380801_34_dialog_content = "Sim. Disseram-me para descansar um pouco.",
  ui_story_5038_50380801_35_dialog_content = "(Tianxian é o seu eu habitual. Apenas um tagarela ininterrupto.)",
  ui_story_5038_50380801_36_dialog_content = "E muito certo. Não é bom se cansar.",
  ui_story_5038_50380801_37_dialog_content = "Quando o resgate de hoje terminar, haverá mais amanhã.",
  ui_story_5038_50380801_38_dialog_content = "Devemos ser mais pacientes do que o próprio oceano nesta viagem.",
  ui_story_5038_50380801_39_dialog_content = "Você parece ter um ditado para todas as ocasiões.",
  ui_story_5038_50380801_40_dialog_content = "É claro. Tenho que me convencer a enfrentar esses dias intermináveis com serenidade.",
  ui_story_5038_50380801_41_dialog_content = "Sendo o Sr. Cadeira de Rodas nosso último recurso, se ele ainda não está de pé e trabalhando, então a situação não pode ser tão ruim assim.",
  ui_story_5038_50380801_42_dialog_content = "Não confunda deficiência com ociosidade.",
  ui_story_5038_50380801_43_dialog_content = "Ei, olha quem é! Senhor Zhong!",
  ui_story_5038_50380801_44_dialog_content = "Raramente vemos você tomando um pouco de ar no convés!",
  ui_story_5038_50380801_45_dialog_content = "Não há necessidade de me tratar como uma espécie de nobre. Não tenho esse tipo de poder em terra e muito menos em um navio.",
  ui_story_5038_50380801_46_dialog_content = "Você é muito modesto, senhor. Um tigre sem dentes ainda é uma criatura formidável, digna de respeito. Muito menos um ex-Grande General.",
  ui_story_5038_50380801_47_dialog_content = "Você realmente é um especialista em bajulação.",
  ui_story_5038_50380801_48_dialog_content = "Na verdade, tenho uma ideia que pode ajudar a aliviar algumas de nossas dificuldades atuais.",
  ui_story_5038_50380801_49_dialog_content = "Mas preciso da sua ajuda para fazer funcionar.",
  ui_story_5038_50380801_50_dialog_content = "Sério? O que é isso?",
  ui_story_5038_50380801_51_dialog_content = "Ficarei feliz em ajudar!",
  ui_story_5038_50380801_52_dialog_content = "Seria uma honra ajudar um cavalheiro tão sábio e talentoso!",
  ui_story_5038_50380801_53_dialog_content = "Não é particularmente árduo. Eu gostaria de pedir a você para me ajudar a coletar alguns troncos.",
  ui_story_5038_50380801_54_dialog_content = "Coletar madeira flutuante?",
  ui_story_5038_50380801_55_dialog_content = "Não poderíamos apenas puxar alguns com uma rede?",
  ui_story_5038_50380801_56_dialog_content = "Direita? Se tem uma coisa que não falta aqui é madeira flutuante.",
  ui_story_5038_50380801_57_dialog_content = "Nem toda a madeira flutuante é utilizável. Por favor, colete apenas os que eu indico.",
  ui_story_5038_50380801_58_dialog_content = "Huh? Como eles são diferentes?",
  ui_story_5038_50380801_59_dialog_content = "Esqueça isso. Apenas faça o que ele diz por enquanto, tenho certeza que ele sabe do que está falando.",
  ui_story_5038_50380801_60_dialog_content = "Vamos ver se conseguimos tirar uma rede de um dos marinheiros.",
  ui_story_5038_50380801_61_dialog_content = "Transporte!",
  ui_story_5038_50380801_62_dialog_content = "Quase lá! Mais um rebocador!",
  ui_story_5038_50380801_63_dialog_content = "Argh!",
  ui_story_5038_50380801_64_dialog_content = "<color=#e8d9bb>Baque, baque!</color>",
  ui_story_5038_50380801_65_dialog_content = "Ufa! Sucesso!",
  ui_story_5038_50380801_66_dialog_content = "Sucesso, meu rabo.",
  ui_story_5038_50380801_67_dialog_content = "Não vejo nem meio peixe lá dentro. Você chama pegar uma prancha de sucesso?",
  ui_story_5038_50380801_68_dialog_content = "Liqing? Não, isso não é para—",
  ui_story_5038_50380801_69_dialog_content = "Pedi-lhes que me ajudassem a recolhê-lo.",
  ui_story_5038_50380801_70_dialog_content = "Huh? Isso é meio estranho. O que há de tão especial em um pedaço de madeira?",
  ui_story_5038_50380801_71_dialog_content = "Olhe mais de perto a peça que eles coletaram. Não é uma prancha normal.",
  ui_story_5038_50380801_72_dialog_content = "Nos navios, essas peças são comumente conhecidas como \"orelhas de coelho\".",
  ui_story_5038_50380801_73_dialog_content = "Ah! Agora que você mencionou, realmente se parece com orelhas de coelho.",
  ui_story_5038_50380801_74_dialog_content = "Isso faz sentido! Lord Zhong, você realmente acertou em cheio!",
  ui_story_5038_50380801_75_dialog_content = "\"Orelhas de coelho\" foram a última das três coisas que calculei com os hexagramas.",
  ui_story_5038_50380801_76_dialog_content = "Para que serve?",
  ui_story_5038_50380801_77_dialog_content = "É uma prancha especial afixada no exterior. Geralmente há apenas dois por navio.",
  ui_story_5038_50380801_78_dialog_content = "É trabalhada de forma mais meticulosa do que outras pranchas e é à prova d'água.",
  ui_story_5038_50380801_79_dialog_content = "Por isso, pedi que fosse coletado.",
  ui_story_5038_50380801_80_dialog_content = "Você está... interessado nele porque é à prova d'água?",
  ui_story_5038_50380801_81_dialog_content = "De fato.",
  ui_story_5038_50380801_82_dialog_content = "Você pode estar se perguntando o porquê. Algo à prova d'água garante que a água não vá para onde não deveria.",
  ui_story_5038_50380801_83_dialog_content = "Repelindo a água...",
  ui_story_5038_50380801_84_dialog_content = "Ah! Eu vejo! É para o porão de carga, certo?",
  ui_story_5038_50380801_85_dialog_content = "Você planeja usar essas pranchas para parar o vazamento!",
  ui_story_5038_50380801_86_dialog_content = "Muito inteligente, jovem amigo.",
  ui_story_5038_50380801_87_dialog_content = "Basta pregar a \"orelha de coelho\" contra o vazamento.",
  ui_story_5038_50380801_88_dialog_content = "É apenas temporário, mas deve ajudar a aliviar um pouco da pressão, para que não fiquemos todos sobrecarregados.",
  ui_story_5038_50380801_89_dialog_content = "Maravilhoso! Como moldar flores falsas em uma árvore real.",
  ui_story_5038_50380801_90_dialog_content = "Então era ISSO que o bastão da sorte significava!",
  ui_story_5038_50380801_91_dialog_content = "Parece um ótimo plano!",
  ui_story_5038_50380801_92_dialog_content = "Se realmente funcionar para parar o vazamento, liberará todos os outros para ajudar com outras coisas.",
  ui_story_5038_50380801_93_dialog_content = "Rápido, vamos ver se encontramos mais algum!",
  ui_story_5038_50380801_94_dialog_content = "Já olhando, PlayerName.",
  ui_story_5038_50380801_95_dialog_content = "Olhe para lá! Outra daquelas tábuas de orelha de coelho.",
  ui_story_5038_50380801_96_dialog_content = "A rede! Pressa!",
  ui_story_5038_50380801_97_dialog_content = "A água ainda está vindo?",
  ui_story_5038_50380801_98_dialog_content = "Sim. Não podemos desistir, nem por um segundo.",
  ui_story_5038_50380801_99_dialog_content = "Não fique aí parado! Ajuda fiança.",
  ui_story_5038_50380801_100_dialog_content = "Oh, desculpe...",
  ui_story_5038_50380801_101_dialog_content = "Ei, alguém pode me dar uma mão?",
  ui_story_5038_50380801_102_dialog_content = "Huh? Isso não é Liqing?",
  ui_story_5038_50380801_103_dialog_content = "Depressa, é muito pesado!",
  ui_story_5038_50380801_104_dialog_content = "Chegando! O que você faz...",
  ui_story_5038_50380801_105_dialog_content = "<color=#e8d9bb>Baque, baque!</color>",
  ui_story_5038_50380801_106_dialog_content = "Eh?!",
  ui_story_5038_50380801_107_dialog_content = "Uau! Era muito pesado.",
  ui_story_5038_50380801_108_dialog_content = "Mas chegar até aqui conta como uma missão cumprida.",
  ui_story_5038_50380801_109_dialog_content = "O que você está fazendo aqui com uma prancha, Liqing?",
  ui_story_5038_50380801_110_dialog_content = "É tudo culpa de Zhong Xu por me colocar em trabalho de parto.",
  ui_story_5038_50380801_111_dialog_content = "Ele disse que essas pranchas podem selar vazamentos.",
  ui_story_5038_50380801_112_dialog_content = "Você o retirou do mar?",
  ui_story_5038_50380801_113_dialog_content = "Provavelmente está muito desgastado para ser útil.",
  ui_story_5038_50380801_114_dialog_content = "Eu acho que não, parece muito pesado para mim.",
  ui_story_5038_50380801_115_dialog_content = "Vá em frente, sinta.",
  ui_story_5038_50380801_116_dialog_content = "Acho que é a sua falta de força que é o problema.",
  ui_story_5038_50380801_117_dialog_content = "Vejamos...",
  ui_story_5038_50380801_118_dialog_content = "Espere um minuto, isso é uma orelha de coelho!",
  ui_story_5038_50380801_119_dialog_content = "Ah-ha, impressionado agora?",
  ui_story_5038_50380801_120_dialog_content = "Orelha de coelho... Quer saber, isso pode funcionar.",
  ui_story_5038_50380801_121_dialog_content = "Dê-me um martelo!",
  ui_story_5038_50380801_122_dialog_content = "Três dois um!",
  ui_story_5038_50380801_123_dialog_content = "<color=#e8d9bb>Baque, baque!</color>",
  ui_story_5038_50380801_124_dialog_content = "Eba, mais um!",
  ui_story_5038_50380801_125_dialog_content = "Mole-mole.",
  ui_story_5038_50380801_126_dialog_content = "V-você não diz? Preciso recuperar o fôlego...",
  ui_story_5038_50380801_127_dialog_content = "O que está fazendo?",
  ui_story_5038_50380801_128_dialog_content = "Estamos coletando madeira flutuante do mar, capitão.",
  ui_story_5038_50380801_129_dialog_content = "Lord Zhong diz que os aparadores desses navios naufragados podem ajudar a consertar o vazamento.",
  ui_story_5038_50380801_130_dialog_content = "As orelhas de coelho...",
  ui_story_5038_50380801_131_dialog_content = "Conseguimos! As orelhas de coelho selaram o vazamento!",
  ui_story_5038_50380801_132_dialog_content = "Liqing está de volta! Então funcionou mesmo?",
  ui_story_5038_50380801_133_dialog_content = "Sim. Usamos a orelha de coelho que acabamos de encontrar para selar um vazamento.",
  ui_story_5038_50380801_134_dialog_content = "Mas há muito mais vazamentos no casco e a tripulação precisa de mais orelhas de coelho.",
  ui_story_5038_50380801_135_dialog_content = "Não fiquem aí parados, pessoal. Vá buscar mais!",
  ui_story_5038_50380801_136_dialog_content = "Ok, ok, já estou indo...",
  ui_story_5038_50380801_137_dialog_content = "Por favor, não se preocupe com isso.",
  ui_story_5038_50380801_138_dialog_content = "Já que funcionou, enviarei marinheiros para recuperar as orelhas de coelho.",
  ui_story_5038_50380801_139_dialog_content = "Nenhum convidado no Shadowind deve trabalhar duro.",
  ui_story_5038_50380801_140_dialog_content = "Ok, puxe!",
  ui_story_5038_50380801_141_dialog_content = "Ei-já!",
  ui_story_5038_50380801_142_dialog_content = "<color=#e8d9bb>Baque, baque!</color>",
  ui_story_5038_50380801_143_dialog_content = "Tem um aqui!",
  ui_story_5038_50380801_144_dialog_content = "<color=#e8d9bb>Baque, baque!</color>",
  ui_story_5038_50380801_145_dialog_content = "Baixe isso aí!",
  ui_story_5038_50380801_146_dialog_content = "Estamos sem pregos, vim buscar mais.",
  ui_story_5038_50380801_147_dialog_content = "Calma aí, uma coisa de cada vez!",
  ui_story_5038_50380801_148_dialog_content = "O trabalho tem sido muito mais eficiente depois que todos começaram a ajudar.",
  ui_story_5038_50380801_149_dialog_content = "Perdi a conta de quantas tábuas eles já juntaram.",
  ui_story_5038_50380801_150_dialog_content = "Parece que podemos consertar o fundo do casco hoje.",
  ui_story_5038_50380801_151_dialog_content = "Ei, essa orelha de coelho aqui...",
  ui_story_5038_50380801_152_dialog_content = "Venha ver isto, Liu.",
  ui_story_5038_50380801_153_dialog_content = "O que, há algum problema com isso?",
  ui_story_5038_50380801_154_dialog_content = "Não. Parece familiar.",
  ui_story_5038_50380801_155_dialog_content = "Sabe, agora que mencionou...",
  ui_story_5038_50380801_156_dialog_content = "Isso não é do barco de pesca de Liu Ge?",
  ui_story_5038_50380801_157_dialog_content = "Sim. Ele partiu em um dia de primavera para pescar no mar e nunca mais se ouviu falar dele.",
  ui_story_5038_50380801_158_dialog_content = "Não esperava ver isso aqui...",
  ui_story_5038_50380801_159_dialog_content = "Eles... reconhecem os destroços?",
  ui_story_5038_50380801_160_dialog_content = "De uma vez só.",
  ui_story_5038_50380801_161_dialog_content = "De apenas uma placa?",
  ui_story_5038_50380801_162_dialog_content = "A orelha de coelho é um acessório muito especial de um navio.",
  ui_story_5038_50380801_163_dialog_content = "Existem apenas dois em cada navio e em posições bastante proeminentes.",
  ui_story_5038_50380801_164_dialog_content = "Os proprietários de navios gostam de gravar padrões neles para distinguir uma embarcação da outra.",
  ui_story_5038_50380801_165_dialog_content = "Então é assim que eles foram capazes de reconhecê-lo!",
  ui_story_5038_50380801_166_dialog_content = "É uma prática comum para os marítimos de Longzhou.",
  ui_story_5038_50380801_167_dialog_content = "Notei você, capitão Yuebai, também inspecionando as \"orelhas de coelho\" que puxamos.",
  ui_story_5038_50380801_168_dialog_content = "Você deve ter identificado muito mais dessas naves do que sua tripulação.",
  ui_story_5038_50380801_169_dialog_content = "Sim...",
  ui_story_5038_50380801_170_dialog_content = "Alguns eram navios de passageiros que enfrentavam furacões nas temporadas de verão e nunca mais voltavam.",
  ui_story_5038_50380801_171_dialog_content = "Suas vistosas \"orelhas de coelho\" as tornavam prontamente reconhecíveis.",
  ui_story_5038_50380801_172_dialog_content = "Existem pouquíssimos barcos de pesca, porque os pescadores conhecem os perigos que o mar oferece.",
  ui_story_5038_50380801_173_dialog_content = "Mas, dada a recessão econômica do ano, alguns ainda optaram por correr o risco.",
  ui_story_5038_50380801_174_dialog_content = "A maioria dessas peças, no entanto, são de navios mercantes.",
  ui_story_5038_50380801_175_dialog_content = "Eles cobiçaram as riquezas do continente do outro lado e tentaram seguir o Shadowind original.",
  ui_story_5038_50380801_176_dialog_content = "Mas até o momento, o Shadowind continua sendo o único navio a atravessar as duas terras com segurança.",
  ui_story_5038_50380801_177_dialog_content = "Aah...",
  ui_story_5038_50380801_178_dialog_content = "Acabei de perceber a gravidade da situação.",
  ui_story_5038_50380801_179_dialog_content = "Existem apenas duas \"orelhas de coelho\" em um navio.",
  ui_story_5038_50380801_180_dialog_content = "Em outras palavras, para cada duas orelhas de coelho que encontramos, é mais um navio afundado.",
  ui_story_5038_50380801_181_dialog_content = "Aqueles que são reconhecíveis desencadeiam um ataque de memórias.",
  ui_story_5038_50380801_182_dialog_content = "Aqueles que não são apenas forragem para números.",
  ui_story_5038_50380801_183_dialog_content = "E já desenterramos tantas orelhas de coelho...",
  ui_story_5038_50380801_184_dialog_content = "Isso é o que herdamos ao navegar pelos mares.",
  ui_story_5038_50380801_185_dialog_content = "O mar não poupa ninguém. Construímos sobre a experiência daqueles que navegaram antes.",
  ui_story_5038_50380801_186_dialog_content = "Os reparos estão quase prontos.",
  ui_story_5038_50380801_187_dialog_content = "Navio mercante, barco de pesca, este também é um navio mercante...",
  ui_story_5038_50380801_188_dialog_content = "Um navio mercante, outro navio mercante...",
  ui_story_5038_50380801_189_dialog_content = "O que você está anotando, Dantang?",
  ui_story_5038_50380801_190_dialog_content = "Oh, estou descobrindo a origem dessas orelhas de coelho.",
  ui_story_5038_50380801_191_dialog_content = "O capitão disse que devemos denunciá-los quando voltarmos a Longzhou.",
  ui_story_5038_50380801_192_dialog_content = "Entendo...",
  ui_story_5038_50380801_193_dialog_content = "Terminei de contar todos os que estavam no porão. Há novos?",
  ui_story_5038_50380801_194_dialog_content = "Não. Acabamos de sair daquela área cheia de troncos.",
  ui_story_5038_50380801_195_dialog_content = "Além disso, o que temos deve ser suficiente.",
  ui_story_5038_50380801_196_dialog_content = "O porão é quase fixo. Todo mundo está apenas encerrando as coisas agora.",
  ui_story_5038_50380801_197_dialog_content = "Isso é ótimo. Acho que posso fazer o mesmo.",
  ui_story_5038_50380801_198_dialog_content = "Pena que não encontrei nenhuma pista...",
  ui_story_5038_50380801_199_dialog_content = "Conduz?",
  ui_story_5038_50380801_200_dialog_content = "Sim, eu ia procurar pistas no The Compass.",
  ui_story_5038_50380801_201_dialog_content = "Muitos desses navios afundados navegaram na mesma frota que o Shadowind original.",
  ui_story_5038_50380801_202_dialog_content = "Como todos eles afundaram, imaginei que as \"orelhas de coelho\" do velho Shadowind poderiam ser levantadas em algum momento.",
  ui_story_5038_50380801_203_dialog_content = "Exceto que não é tão simples quanto pensei que seria.",
  ui_story_5038_50380801_204_dialog_content = "Isso faz sentido. As pistas do paradeiro do velho Shadowind podem estar entre os destroços.",
  ui_story_5038_50380801_205_dialog_content = "Devemos fazer uma pesquisa completa, já que a Bússola é tão importante.",
  ui_story_5038_50380801_206_dialog_content = "Devemos falar com o capitão?",
  ui_story_5038_50380801_207_dialog_content = "Mas, pensando bem, Zhong Xu não parecia muito preocupado com as orelhas de coelho.",
  ui_story_5038_50380801_208_dialog_content = "Talvez ele tivesse certeza de que nenhum deles seria do Shadowind.",
  ui_story_5038_50380801_209_dialog_content = "Como ele poderia ter tanta certeza?",
  ui_story_5038_50380801_210_dialog_content = "Talvez eles tivessem uma forma única, facilmente reconhecível à distância?",
  ui_story_5038_50380801_211_dialog_content = "Isso soa um pouco hiperbólico.",
  ui_story_5038_50380801_212_dialog_content = "Ninguém pode distinguir nada tão pequeno à distância no mar.",
  ui_story_5038_50380801_213_dialog_content = "Espere um minuto, e se o velho Shadowind não tivesse orelhas de coelho?",
  ui_story_5038_50380801_214_dialog_content = "Não, mesmo que não, suas outras partes ainda deveriam estar entre os destroços.",
  ui_story_5038_50380801_215_dialog_content = "Mas Zhong Xu não mostrou nenhum interesse em nenhum dos destroços...",
  ui_story_5038_50380801_216_dialog_content = "Será que...",
  ui_story_5038_50380801_217_dialog_content = "É natural não encontrar nenhum resquício do antigo Shadowind!",
  ui_story_5038_50380801_218_dialog_content = "Nunca se tornou destroços em primeiro lugar.",
  ui_story_5038_50380801_219_dialog_content = "O que... De onde você veio, Liqing?!",
  ui_story_5038_50380801_220_dialog_content = "Não estragou...",
  ui_story_5038_50380801_221_dialog_content = "Navios perdidos e naufrágios são duas coisas diferentes.",
  ui_story_5038_50380801_222_dialog_content = "Ele tem o The Compass a bordo para mantê-lo seguro, então como poderia afundar?",
  ui_story_5038_50380801_223_dialog_content = "A Bússola é tão poderosa assim?",
  ui_story_5038_50380801_224_dialog_content = "É claro. Caso contrário, você não teria tantas pessoas indo atrás dele.",
  ui_story_5038_50380801_225_dialog_content = "De qualquer forma, agora não é hora de discutir isso.",
  ui_story_5038_50380801_226_dialog_content = "A ceia está prestes a começar. Todo mundo está esperando por você.",
  ui_story_5038_50380801_227_dialog_content = "Me siga.",
  ui_story_5038_50380801_228_dialog_content = "Todos? Você quer dizer todos em todo o navio?",
  ui_story_5038_50380801_229_dialog_content = "Sim. A nave está consertada, então todos nós temos um raro momento de folga pela primeira vez.",
  ui_story_5038_50380801_230_dialog_content = "Não nos segure. Até o velho Zhong Xu veio.",
  ui_story_5038_50380801_231_dialog_content = "Depressa!",
  ui_story_5038_50380801_232_dialog_content = "Aí está você, finalmente!",
  ui_story_5038_50380801_233_dialog_content = "O cheiro de comida finalmente atraiu você?",
  ui_story_5038_50380801_234_dialog_content = "Sente-se aqui!",
  ui_story_5038_50380801_235_dialog_content = "Uau, é animado aqui!",
  ui_story_5038_50380801_236_dialog_content = "Uau, cheira muito bem!",
  ui_story_5038_50380801_237_dialog_content = "É claro. Eles foram todos para a cozinha.",
  ui_story_5038_50380801_238_dialog_content = "Agora, isso é o que você chama de festa de celebração!",
  ui_story_5038_50380801_239_dialog_content = "Festa de celebração?",
  ui_story_5038_50380801_240_dialog_content = "Sim, comemorando o conserto do Shadowind e retomando a viagem.",
  ui_story_5038_50380801_241_dialog_content = "Mas espere, eu não deveria estar roubando palavras do capitão agora. Capitão, continue!",
  ui_story_5038_50380801_242_dialog_content = "M-Eu?",
  ui_story_5038_50380801_243_dialog_content = "Sinto muito, mas não sou de palavras.",
  ui_story_5038_50380801_244_dialog_content = "Todos... apenas aproveitem o banquete, suponho.",
  ui_story_5038_50380801_245_dialog_content = "Sinta-se à vontade para pedir qualquer prato que desejar. Enquanto o tivermos, você o receberá.",
  ui_story_5038_50380801_246_dialog_content = "Sério? O presunto na despensa para mim, então!",
  ui_story_5038_50380801_247_dialog_content = "Estou tão cansado de comer peixe todos os dias!",
  ui_story_5038_50380801_248_dialog_content = "Ei, o que há de errado com o peixe?",
  ui_story_5038_50380801_249_dialog_content = "Eu levo tudo se você não quiser!",
  ui_story_5038_50380801_250_dialog_content = "Você está bem longe de todos os outros, Lorde Zhong.",
  ui_story_5038_50380801_251_dialog_content = "Devo trazer-lhe alguma comida?",
  ui_story_5038_50380801_252_dialog_content = "Está tudo bem. Este local tranquilo me convém muito bem.",
  ui_story_5038_50380801_253_dialog_content = "Você não gosta de reuniões barulhentas?",
  ui_story_5038_50380801_254_dialog_content = "Muito pelo contrário, eu faço.",
  ui_story_5038_50380801_255_dialog_content = "Quando eu era oficial, participava de funções sociais.",
  ui_story_5038_50380801_256_dialog_content = "Foi só quando me aposentei que percebi que é muito melhor observar de longe.",
  ui_story_5038_50380801_257_dialog_content = "Aprecio absorver todas as emoções muito mais do que aqueles que realmente se deleitam com elas.",
  ui_story_5038_50380801_258_dialog_content = "Entendo... Isso é muito profundo...",
  ui_story_5038_50380801_259_dialog_content = "Aqui está, Jiu!",
  ui_story_5038_50380801_260_dialog_content = "Você me assustou, senhorita...",
  ui_story_5038_50380801_261_dialog_content = "A turma ali quer dançar. Você está vindo?",
  ui_story_5038_50380801_262_dialog_content = "Você é a melhor dançarina que eu conheço!",
  ui_story_5038_50380801_263_dialog_content = "Fico lisonjeado, mas não sou tão bom...",
  ui_story_5038_50380801_264_dialog_content = "Então vamos pegar algo para comer! Eles estão servindo novos pratos agora!",
  ui_story_5038_50380801_265_dialog_content = "A boa comida está indo rápido!",
  ui_story_5038_50380801_266_dialog_content = "Você parece realmente animado!",
  ui_story_5038_50380801_267_dialog_content = "Porque eu estou super feliz!",
  ui_story_5038_50380801_268_dialog_content = "Nós mesmos içamos as velas lá e fixamos o navio sob nossos pés com nossas próprias mãos.",
  ui_story_5038_50380801_269_dialog_content = "Isso não é incrível?",
  ui_story_5038_50380801_270_dialog_content = "Partimos nessa jornada e todos acabamos no mesmo barco.",
  ui_story_5038_50380801_271_dialog_content = "Sim você está certo. O Shadowind está começando a se sentir em casa.",
  ui_story_5038_50380801_272_dialog_content = "Veja, isso é algo que apenas passageiros como nós sentiriam.",
  ui_story_5038_50380801_273_dialog_content = "Claro, há outro tipo de felicidade que todos a bordo podem desfrutar.",
  ui_story_5038_50380801_274_dialog_content = "Verifique-os.",
  ui_story_5038_50380801_275_dialog_content = "Enfim, depois de trabalhar por tanto tempo!",
  ui_story_5038_50380801_276_dialog_content = "Finalmente teremos uma boa noite de sono esta noite.",
  ui_story_5038_50380801_277_dialog_content = "Sim, não precisamos mais consertar o mastro ou tirar água.",
  ui_story_5038_50380801_278_dialog_content = "Finalmente vamos voltar para Longzhou.",
  ui_story_5038_50380901_1_dialog_content = "<color=#e8d9bb>5 dias depois...</color>",
  ui_story_5038_50380901_2_dialog_content = "Tudo está funcional e funcionando bem, capitão.",
  ui_story_5038_50380901_3_dialog_content = "Ainda há um pequeno vazamento no porão, mas não piorou da noite para o dia.",
  ui_story_5038_50380901_4_dialog_content = "Obrigado pelo relatório.",
  ui_story_5038_50380901_5_dialog_content = "As provisões húmidas foram eliminadas?",
  ui_story_5038_50380901_6_dialog_content = "Sim. Nós descartamos os completamente arruinados e estamos secando ao sol os que estão em condições transitáveis no convés.",
  ui_story_5038_50380901_7_dialog_content = "No entanto, agora não temos muita comida sobrando.",
  ui_story_5038_50380901_8_dialog_content = "Comida...",
  ui_story_5038_50380901_9_dialog_content = "Quanta água doce nos resta?",
  ui_story_5038_50380901_10_dialog_content = "O suficiente para cerca de meio mês.",
  ui_story_5038_50380901_11_dialog_content = "A que distância estamos da costa, capitão?",
  ui_story_5038_50380901_12_dialog_content = "Sinto muito, mas isso ainda é indeterminado no momento.",
  ui_story_5038_50380901_13_dialog_content = "Os mapas desta região estão incompletos e sofremos um ataque.",
  ui_story_5038_50380901_14_dialog_content = "Estamos sozinhos em território desconhecido.",
  ui_story_5038_50380901_15_dialog_content = "Diga a todos para economizar nossas provisões por enquanto e tentar pescar com mais frequência.",
  ui_story_5038_50380901_16_dialog_content = "Mesmo com a água doce. Use-o criteriosamente fora do consumo normal.",
  ui_story_5038_50380901_17_dialog_content = "Você está dispensado.",
  ui_story_5038_50380901_18_dialog_content = "Sim, capitão.",
  ui_story_5038_50380901_19_dialog_content = "<color=#e8d9bb>5 dias depois</color>",
  ui_story_5038_50380901_20_dialog_content = "O almoço foi bastante escasso novamente.",
  ui_story_5038_50380901_21_dialog_content = "Sim, mas não há nada que possamos fazer.",
  ui_story_5038_50380901_22_dialog_content = "Você está satisfeito?",
  ui_story_5038_50380901_23_dialog_content = "Nem mesmo perto. Eu quase nem dei uma mordida.",
  ui_story_5038_50380901_24_dialog_content = "Dei minha porção para Tinytail.",
  ui_story_5038_50380901_25_dialog_content = "Que? Você não pode fazer isso, você ainda está crescendo!",
  ui_story_5038_50380901_26_dialog_content = "E-É só com isso que você está preocupado?!",
  ui_story_5038_50380901_27_dialog_content = "Vou verificar como estão as coisas no convés.",
  ui_story_5038_50380901_28_dialog_content = "Se tiver sorte, terá peixe no jantar.",
  ui_story_5038_50380901_29_dialog_content = "Peixe? Sério, miau?",
  ui_story_5038_50380901_30_dialog_content = "Se tiver sorte.",
  ui_story_5038_50380901_31_dialog_content = "Eu não sou... bom em pescar...",
  ui_story_5038_50380901_32_dialog_content = "Enfim... espere aqui...",
  ui_story_5038_50380901_33_dialog_content = "Você está cambaleando... O que há de errado?",
  ui_story_5038_50380901_34_dialog_content = "Que? Não, eu sou...",
  ui_story_5038_50380901_35_dialog_content = "Deixe-me tomar seu pulso.",
  ui_story_5038_50380901_36_dialog_content = "Eu...",
  ui_story_5038_50380901_37_dialog_content = "Tu estás doente.",
  ui_story_5038_50380901_38_dialog_content = "<color=#e8d9bb>5 dias depois</color>",
  ui_story_5038_50380901_39_dialog_content = "Pare de correr por aí, Tinytail!",
  ui_story_5038_50380901_40_dialog_content = "Não quero ver você cair no oceano!",
  ui_story_5038_50380901_41_dialog_content = "Miau.",
  ui_story_5038_50380901_42_dialog_content = "É da minha conta cuidar de você. Você não percebe como está ventando?",
  ui_story_5038_50380901_43_dialog_content = "Uma única rajada poderia levá-lo para sabe-se lá onde.",
  ui_story_5038_50380901_44_dialog_content = "Volte para a cabana comigo.",
  ui_story_5038_50380901_45_dialog_content = "Miauu!",
  ui_story_5038_50380901_46_dialog_content = "*Ofegante* Nossa, ele pode realmente correr.",
  ui_story_5038_50380901_47_dialog_content = "Não se preocupe. Os animais têm instintos muito mais aguçados do que nós.",
  ui_story_5038_50380901_48_dialog_content = "Somos nós que temos que confiar neles quando o verdadeiro perigo surge.",
  ui_story_5038_50380901_49_dialog_content = "Que bom ver você aqui, Yuebai!",
  ui_story_5038_50380901_50_dialog_content = "Você viu Liqing? Eu não o vi hoje.",
  ui_story_5038_50380901_51_dialog_content = "Eu não teria que me preocupar com Tinytail se ele estivesse por perto.",
  ui_story_5038_50380901_52_dialog_content = "Ele está ocupado com os pacientes.",
  ui_story_5038_50380901_53_dialog_content = "Mais dois tripulantes tiveram febre hoje.",
  ui_story_5038_50380901_54_dialog_content = "Ele deve estar ocupado.",
  ui_story_5038_50380901_55_dialog_content = "Mais doença...",
  ui_story_5038_50380901_56_dialog_content = "Quanto tempo até chegarmos a Longzhou, Yuebai?",
  ui_story_5038_50380901_57_dialog_content = "...",
  ui_story_5038_50380901_58_dialog_content = "Não sei mesmo.",
  ui_story_5038_50380901_59_dialog_content = "(Ela parece um pouco desanimada...)",
  ui_story_5038_50380901_60_dialog_content = "(Talvez porque ela simplesmente não saiba responder.)",
  ui_story_5038_50380901_61_dialog_content = "(Podemos recorrer a Yuebai, mas a quem ela pode recorrer?)",
  ui_story_5038_50380901_62_dialog_content = "O mar é imenso. Longzhou está muito além do horizonte, fora da minha vista.",
  ui_story_5038_50380901_63_dialog_content = "Só posso cuidar das coisas que estão ao meu alcance, que posso ver.",
  ui_story_5038_50380901_64_dialog_content = "Você deve voltar para sua cabine. Uma tempestade se aproxima.",
  ui_story_5038_50380901_65_dialog_content = "<color=#e8d9bb>No dia seguinte</color>",
  ui_story_5038_50380901_66_dialog_content = "Capitão, amarramos tudo no convés e toda a tripulação está instalada também.",
  ui_story_5038_50380901_67_dialog_content = "Temos lastro suficiente?",
  ui_story_5038_50380901_68_dialog_content = "Sim. O peso deve suportar o swell.",
  ui_story_5038_50380901_69_dialog_content = "Ok, devemos acabar com as medidas preventivas então.",
  ui_story_5038_50380901_70_dialog_content = "Aguarde minhas ordens na popa.",
  ui_story_5038_50380901_71_dialog_content = "Hum, não deveríamos enrolar as velas, capitão?",
  ui_story_5038_50380901_72_dialog_content = "Não. Vamos navegar a todo vapor.",
  ui_story_5038_50380901_73_dialog_content = "Na tempestade?",
  ui_story_5038_50380901_74_dialog_content = "Isso é muito perigoso! Não seremos capazes de controlar a nave!",
  ui_story_5038_50380901_75_dialog_content = "Sem mencionar que mais Eclipsites poderiam embarcar no navio como antes!",
  ui_story_5038_50380901_76_dialog_content = "Eu sei, mas não podemos esperar mais.",
  ui_story_5038_50380901_77_dialog_content = "O tempo também é um adversário agora.",
  ui_story_5038_50380901_78_dialog_content = "Perderemos a oportunidade de chegar à costa se pararmos agora.",
  ui_story_5038_50380901_79_dialog_content = "Mas...",
  ui_story_5038_50380901_80_dialog_content = "Temos que aproveitar cada pedacinho de vento que temos, mesmo dentro de uma tempestade.",
  ui_story_5038_50380901_81_dialog_content = "Quanto aos Eclipsites, são os intrusos que devem temer pisar nesta nave, não nós.",
  ui_story_5038_50380901_82_dialog_content = "Não faltam convidados a bordo em busca de ação.",
  ui_story_5038_50380901_83_dialog_content = "Já que você colocou assim...",
  ui_story_5038_50380901_84_dialog_content = "Ah, tanto faz! Sou apenas um marinheiro. São ordens do capitão.",
  ui_story_5038_50380901_85_dialog_content = "Tudo bem. Posicione-se na popa.",
  ui_story_5038_50380901_86_dialog_content = "A onda virá em breve. Aguardem minhas ordens.",
  ui_story_5038_50380901_87_dialog_content = "Sim!",
  ui_story_5038_50381001_1_dialog_content = "(A tempestade abalou o Shadowind por um dia inteiro.)",
  ui_story_5038_50381001_2_dialog_content = "(Já nos deparamos com tantos problemas, desde enjôo, ataque de cardumes de peixes até eclipsites.)",
  ui_story_5038_50381001_3_dialog_content = "(Mas agora mesmo, o barulho aterrorizante do vendaval rasgando as velas finalmente começou a diminuir consideravelmente.)",
  ui_story_5038_50381001_4_dialog_content = "(É assim que sabemos que conseguimos.)",
  ui_story_5038_50381001_5_dialog_content = "O deck parece estar seguro agora.",
  ui_story_5038_50381001_6_dialog_content = "Pareceria assim. Conseguimos passar pela tempestade?",
  ui_story_5038_50381001_7_dialog_content = "Sim, a parte mais difícil da jornada acabou.",
  ui_story_5038_50381001_8_dialog_content = "Só pequenas turbulências daqui pra frente, nada que precaução não resolva.",
  ui_story_5038_50381001_9_dialog_content = "Graças a Deus acabou.",
  ui_story_5038_50381001_10_dialog_content = "Vou vomitar todos os meus órgãos se o navio continuar balançando.",
  ui_story_5038_50381001_11_dialog_content = "Você está bem, Tianxian? Você parece bem rude.",
  ui_story_5038_50381001_12_dialog_content = "Estou aguentando firme. Pegar ar fresco no convés ajuda muito.",
  ui_story_5038_50381001_13_dialog_content = "Não é hora de uma refeição, capitão?",
  ui_story_5038_50381001_14_dialog_content = "Temos que conseguir algo dentro de nós depois de um dia inteiro naquela tempestade de pernas para o ar.",
  ui_story_5038_50381001_15_dialog_content = "Sim, você tem razão.",
  ui_story_5038_50381001_16_dialog_content = "Marinheiro, diga aos cozinheiros da cozinha para preparar o jantar.",
  ui_story_5038_50381001_17_dialog_content = "De uma vez só.",
  ui_story_5038_50381001_18_dialog_content = "No entanto, capitão, estamos ficando sem suprimentos, então devemos racioná-los.",
  ui_story_5038_50381001_19_dialog_content = "Preciso saber quantos dias mais vamos navegar.",
  ui_story_5038_50381001_20_dialog_content = "... Isso é atualmente indeterminado.",
  ui_story_5038_50381001_21_dialog_content = "Vamos encher o estômago de todos primeiro.",
  ui_story_5038_50381001_22_dialog_content = "Não, talvez apenas meio cheio.",
  ui_story_5038_50381001_23_dialog_content = "Ei, quantas rações nos restam?",
  ui_story_5038_50381001_24_dialog_content = "...",
  ui_story_5038_50381001_25_dialog_content = "Eu sei que você sabe, então me diga.",
  ui_story_5038_50381001_26_dialog_content = "Eu entendo que a situação é muito terrível, mas eu gostaria de saber o quão terrível.",
  ui_story_5038_50381001_27_dialog_content = "Não podemos continuar assim.",
  ui_story_5038_50381001_28_dialog_content = "O quê?",
  ui_story_5038_50381001_29_dialog_content = "Vir. Chame todo mundo para começar a pescar.",
  ui_story_5038_50381001_30_dialog_content = "Agora mesmo? Mas há trabalhos a fazer—",
  ui_story_5038_50381001_31_dialog_content = "Os sem importância podem esperar.",
  ui_story_5038_50381001_32_dialog_content = "Diga a todos para arranjar tempo para pescar.",
  ui_story_5038_50381001_33_dialog_content = "Caso contrário, não teremos nada para comer em alguns dias.",
  ui_story_5038_50381001_34_dialog_content = "É tão sério...?",
  ui_story_5038_50381001_35_dialog_content = "Tudo bem, vou reunir a tripulação.",
  ui_story_5038_50381001_36_dialog_content = "Esta rede está cheia!",
  ui_story_5038_50381001_37_dialog_content = "Rápido, me ajude a puxá-lo para cima!",
  ui_story_5038_50381001_38_dialog_content = "Ei, ho!",
  ui_story_5038_50381001_39_dialog_content = "Por que toda a tripulação está pescando no convés?",
  ui_story_5038_50381001_40_dialog_content = "Existe... um problema com nossos suprimentos de comida?",
  ui_story_5038_50381001_41_dialog_content = "É claro. A comida é a necessidade mais básica e primordial.",
  ui_story_5038_50381001_42_dialog_content = "O navio está bem agora, mas e quanto a nós? Podemos suportar?",
  ui_story_5038_50381001_43_dialog_content = "Suspirar...",
  ui_story_5038_50381001_44_dialog_content = "Pelo menos estamos no oceano onde os peixes são abundantes.",
  ui_story_5038_50381001_45_dialog_content = "Não é tão simples assim.",
  ui_story_5038_50381001_46_dialog_content = "Mesmo que todos não se importem de comer peixe o tempo todo, ainda estamos consumindo água fresca todos os dias.",
  ui_story_5038_50381001_47_dialog_content = "Quando isso acabar, significa o fim da nossa viagem.",
  ui_story_5038_50381001_48_dialog_content = "Afinal, somos criaturas terrestres.",
  ui_story_5038_50381001_49_dialog_content = "Assim que estivermos no mar, a contagem regressiva começa.",
  ui_story_5038_50381001_50_dialog_content = "Contagem regressiva, hein...",
  ui_story_5038_50381001_51_dialog_content = "Imagino quanto tempo nos resta.",
  ui_story_5038_50381001_52_dialog_content = "Peguei outro! É um grande também!",
  ui_story_5038_50381001_53_dialog_content = "Tudo bem, precisamos de todos para isso!",
  ui_story_5038_50381001_54_dialog_content = "Três dois um!",
  ui_story_5038_50381001_55_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5038_50381001_56_dialog_content = "Uau, é enorme!",
  ui_story_5038_50381001_57_dialog_content = "Sim, jackpot!",
  ui_story_5038_50381001_58_dialog_content = "Deve ser o suficiente para cinco ou seis pessoas!",
  ui_story_5038_50381001_59_dialog_content = "Sim, é enorme!",
  ui_story_5038_50381001_60_dialog_content = "Nunca vi um peixe tão grande antes!",
  ui_story_5038_50381001_61_dialog_content = "Vamos, vamos transportá-lo para a cozinha.",
  ui_story_5038_50381001_62_dialog_content = "Isso deve compensar o pouco que tivemos esta noite!",
  ui_story_5038_50381001_63_dialog_content = "<size=50>Sim!</size>",
  ui_story_5038_50381001_64_dialog_content = "Solte-o.",
  ui_story_5038_50381001_65_dialog_content = "Que? Quem disse isso?",
  ui_story_5038_50381001_66_dialog_content = "Era eu, e eu disse, solte.",
  ui_story_5038_50381001_67_dialog_content = "Senhor Zhong? Mas por que?",
  ui_story_5038_50381001_68_dialog_content = "Ele tem razão. Solte-o de uma vez.",
  ui_story_5038_50381001_69_dialog_content = "Olhe bem, isso é um peixe-serpente!",
  ui_story_5038_50381001_70_dialog_content = "Peixe Serpente!?",
  ui_story_5038_50381001_X70_dialog_content = "Droga, eu não estava prestando atenção agora. Não é o que nos atacou antes...",
  ui_story_5038_50381001_71_dialog_content = "<color=#e8d9bb>Bata!</color>",
  ui_story_5038_50381001_72_dialog_content = "Ai...",
  ui_story_5038_50381001_73_dialog_content = "Nossa!",
  ui_story_5038_50381001_74_dialog_content = "O que está acontecendo? Nós colidimos com alguma coisa?",
  ui_story_5038_50381001_75_dialog_content = "<color=#e8d9bb>Bata!</color>",
  ui_story_5038_50381001_76_dialog_content = "T-Aí está de novo!",
  ui_story_5038_50381001_77_dialog_content = "Olhar para baixo!",
  ui_story_5038_50381001_78_dialog_content = "Escola de peixe! Eles estão batendo em nós!",
  ui_story_5038_50381001_79_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5038_50381001_80_dialog_content = "Olhe! Eles estão pulando no convés!",
  ui_story_5038_50381002_1_dialog_content = "<color=#e8d9bb>Bata!</color>",
  ui_story_5038_50381002_2_dialog_content = "Ahhhh!",
  ui_story_5038_50381002_3_dialog_content = "E agora? Eles ainda estão nos atacando...",
  ui_story_5038_50381002_4_dialog_content = "Acabamos de consertar o casco inferior. Se eles o violarem...",
  ui_story_5038_50381002_5_dialog_content = "Dê-me esse peixe grande!",
  ui_story_5038_50381002_6_dialog_content = "Hã?",
  ui_story_5038_50381002_7_dialog_content = "Por favor, volte para onde você veio, venerável!",
  ui_story_5038_50381002_8_dialog_content = "Aqui está!",
  ui_story_5038_50381002_9_dialog_content = "<color=#e8d9bb>Splash!</color>",
  ui_story_5038_50381002_10_dialog_content = "Ok, tudo deve estar bem agora.",
  ui_story_5038_50381002_11_dialog_content = "Convocou os outros peixes?",
  ui_story_5038_50381002_12_dialog_content = "Sim. Os peixes-serpente estão sempre nas escolas e seu senso de unidade é forte.",
  ui_story_5038_50381002_13_dialog_content = "A escola inteira virá em auxílio de qualquer membro em apuros.",
  ui_story_5038_50381002_14_dialog_content = "Não é sábio irritar o peixe-serpente no mar.",
  ui_story_5038_50381002_15_dialog_content = "Mentalidade de bando... Que característica única.",
  ui_story_5038_50381002_16_dialog_content = "Obrigado pelo aviso, Liqing, Lord Zhong.",
  ui_story_5038_50381002_17_dialog_content = "Pedimos desculpas por nossa imprudência.",
  ui_story_5038_50381002_18_dialog_content = "Está bem. Estamos todos no mesmo barco. Literalmente.",
  ui_story_5038_50381002_19_dialog_content = "Nenhum dano resultou disso, então vamos esquecer que aconteceu.",
  ui_story_5038_50381002_20_dialog_content = "Não posso acreditar que peixes-serpente estão nessas águas. Não me diga que eles vão nos atacar de novo...",
  ui_story_5038_50381002_21_dialog_content = "Não seremos capazes de suportar outra onda...",
  ui_story_5038_50381002_22_dialog_content = "<color=#e8d9bb>No dia seguinte</color>",
  ui_story_5038_50381002_23_dialog_content = "Outro peixe-serpente! Solte-o agora!",
  ui_story_5038_50381002_24_dialog_content = "Eu sei eu sei. Não é como se fosse a primeira vez.",
  ui_story_5038_50381002_25_dialog_content = "Suspiro... Eles não podem parar de arruinar nossas chances de pescar algum peixe?",
  ui_story_5038_50381002_26_dialog_content = "A sétima...",
  ui_story_5038_50381002_27_dialog_content = "Aí está você, Yuebai!",
  ui_story_5038_50381002_28_dialog_content = "Mandaram-me avisar que o almoço está pronto.",
  ui_story_5038_50381002_29_dialog_content = "Adivinha? Vamos comer bem hoje! Embora tudo seja cozido com peixe.",
  ui_story_5038_50381002_30_dialog_content = "Vocês vão em frente. Eu vou esperar por agora.",
  ui_story_5038_50381002_31_dialog_content = "O quê? Como assim?",
  ui_story_5038_50381002_32_dialog_content = "Algo está te incomodando?",
  ui_story_5038_50381002_33_dialog_content = "Existe, e eu gostaria de descobrir, para aliviar minhas preocupações.",
  ui_story_5038_50381002_34_dialog_content = "O que foi?",
  ui_story_5038_50381002_35_dialog_content = "Esses peixes-serpente estão se comportando de maneira altamente incomum.",
  ui_story_5038_50381002_36_dialog_content = "Eles são uma espécie migratória que viaja entre as costas de Astra e Longzhou em grupos.",
  ui_story_5038_50381002_37_dialog_content = "Eles nunca ficam muito tempo em qualquer parte do oceano, exceto brevemente quando estão perto da costa.",
  ui_story_5038_50381002_38_dialog_content = "Mas agora, grupos deles parecem estar vagando pela área.",
  ui_story_5038_50381002_39_dialog_content = "É verdade que a tripulação continuou pegando-os hoje.",
  ui_story_5038_50381002_40_dialog_content = "Eles não estão nos atacando de novo, estão?",
  ui_story_5038_50381002_41_dialog_content = "Não parece ser o caso no momento.",
  ui_story_5038_50381002_42_dialog_content = "Estou fazendo o meu melhor para navegar ao redor deles para evitar a repetição do que aconteceu antes.",
  ui_story_5038_50381002_43_dialog_content = "Mas seu comportamento peculiar é indicativo de condições incomuns à frente.",
  ui_story_5038_50381002_44_dialog_content = "Algo aqui é mais atraente para o peixe-serpente do que Longzhou.",
  ui_story_5038_50381002_45_dialog_content = "Hum...",
  ui_story_5038_50381002_46_dialog_content = "Vá almoçar. Eu tenho que olhar para os gráficos.",
  ui_story_5038_50381002_47_dialog_content = "Onde no mundo nós navegamos para...?",
  ui_story_5038_50381002_48_dialog_content = "A direção e a velocidade do vento ontem...",
  ui_story_5038_50381002_49_dialog_content = "Não, um pouco mais ao norte.",
  ui_story_5038_50381002_50_dialog_content = "<color=#e8d9bb>Toc, toc.</color>",
  ui_story_5038_50381002_51_dialog_content = "Quem é esse?",
  ui_story_5038_50381002_52_dialog_content = "Sou eu, Zhong Xu.",
  ui_story_5038_50381002_53_dialog_content = "O que o traz aqui, Senhor Zhong?",
  ui_story_5038_50381002_54_dialog_content = "Estou neste navio balançando há muito tempo para saber para que lado estamos indo.",
  ui_story_5038_50381002_55_dialog_content = "Posso perguntar onde estamos agora?",
  ui_story_5038_50381002_56_dialog_content = "Onde...",
  ui_story_5038_50381002_57_dialog_content = "Francamente, com esses mapas incompletos, não posso lhe dizer nossa localização exata.",
  ui_story_5038_50381002_58_dialog_content = "Por favor, me dê mais tempo para resolver o problema.",
  ui_story_5038_50381002_59_dialog_content = "É claro. Não sei nada de velejar. Eu estava apenas curioso.",
  ui_story_5038_50381002_60_dialog_content = "Você é o capitão, então tenho certeza que tem um plano.",
  ui_story_5038_50381002_61_dialog_content = "...",
  ui_story_5038_50381002_62_dialog_content = "A menos, claro, como eu, você não.",
  ui_story_5038_50381002_63_dialog_content = "Suspirar...",
  ui_story_5038_50381002_64_dialog_content = "Receio não ter a arrogância de afirmar descontroladamente que sei onde estamos, meu senhor.",
  ui_story_5038_50381002_65_dialog_content = "A única coisa que posso prometer é que farei o meu melhor.",
  ui_story_5038_50381002_66_dialog_content = "Ninguém pode prever o futuro.",
  ui_story_5038_50381002_67_dialog_content = "Admiro sua determinação, capitão.",
  ui_story_5038_50381002_68_dialog_content = "Mas o futuro não é totalmente imprevisível no mar.",
  ui_story_5038_50381002_69_dialog_content = "...",
  ui_story_5038_50381002_70_dialog_content = "Está se referindo ao The Compass, senhor?",
  ui_story_5038_50381002_71_dialog_content = "Sim. Entendo que sua prioridade é completar a viagem.",
  ui_story_5038_50381002_72_dialog_content = "Mas o navio está ficando sem provisões e praticamente perdido. Apenas The Compass pode nos colocar no caminho certo.",
  ui_story_5038_50381002_73_dialog_content = "O compasso...",
  ui_story_5038_50381002_74_dialog_content = "Mesmo que seja tão poderoso quanto você afirma, meu senhor...",
  ui_story_5038_50381002_75_dialog_content = "Não temos recursos para procurá-lo.",
  ui_story_5038_50381002_76_dialog_content = "E se não tivermos que procurar muito e muito longe?",
  ui_story_5038_50381002_77_dialog_content = "Aquele tesouro Lin está nesta vizinhança.",
  ui_story_5038_50381002_78_dialog_content = "O quê?!",
  ui_story_5038_50381002_79_dialog_content = "Suspirar...",
  ui_story_5038_50381002_80_dialog_content = "Mais uma caixa de comida estragada...",
  ui_story_5038_50381002_81_dialog_content = "Provavelmente não deveria jogá-lo, no entanto.",
  ui_story_5038_50381002_82_dialog_content = "Comida estragada é melhor do que nada.",
  ui_story_5038_50381002_83_dialog_content = "E a água doce...",
  ui_story_5038_50381002_84_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5038_50381002_85_dialog_content = "Este barril está vazio.",
  ui_story_5038_50381002_86_dialog_content = "Nós poderíamos usar um pouco de chuva agora.",
  ui_story_5038_50381002_87_dialog_content = "Quantos faltam? Vejo um, dois, três...",
  ui_story_5038_50381002_88_dialog_content = "Aí está você!",
  ui_story_5038_50381002_89_dialog_content = "O que está fazendo aqui?",
  ui_story_5038_50381002_90_dialog_content = "Siga-me, o capitão quer vê-lo agora mesmo!",
  ui_story_5038_50381101_1_dialog_content = "Não se concentre apenas no peixe, mantenha os olhos no horizonte também!",
  ui_story_5038_50381101_2_dialog_content = "Temos que vasculhar a área imediata, ordens do capitão!",
  ui_story_5038_50381101_3_dialog_content = "Informe-me no instante em que detectar algo!",
  ui_story_5038_50381101_4_dialog_content = "Sim!",
  ui_story_5038_50381101_5_dialog_content = "Estamos procurando pela Bússola, não estamos, Liqing?",
  ui_story_5038_50381101_6_dialog_content = "É claro. Por que outro motivo o navio inteiro receberia ordens de olhar para o mar?",
  ui_story_5038_50381101_7_dialog_content = "A Bússola deve estar na outra nave Lin...",
  ui_story_5038_50381101_8_dialog_content = "É isso mesmo, eu me lembro de você me dizendo que o navio não afundou.",
  ui_story_5038_50381101_9_dialog_content = "Pelo menos não quando Zhong Xu e eu partimos.",
  ui_story_5038_50381101_10_dialog_content = "Então pode ter estado flutuando sozinho todo esse tempo?",
  ui_story_5038_50381101_11_dialog_content = "Isso soa estranho...",
  ui_story_5038_50381101_12_dialog_content = "Isso não é uma coisa boa? Torna mais fácil de encontrar.",
  ui_story_5038_50381101_13_dialog_content = "Mas é provável que tenha enfrentado ondas e vendavais depois de todo esse tempo.",
  ui_story_5038_50381101_14_dialog_content = "Sem ninguém controlando, é provável que já tenha afundado.",
  ui_story_5038_50381101_15_dialog_content = "Sem chance.",
  ui_story_5038_50381101_16_dialog_content = "Não quando está carregando a preciosa Bússola que procuramos!",
  ui_story_5038_50381101_17_dialog_content = "Já está escuro...",
  ui_story_5038_50381101_18_dialog_content = "Devemos parar por hoje?",
  ui_story_5038_50381101_19_dialog_content = "Não podemos ver nada no escuro.",
  ui_story_5038_50381101_20_dialog_content = "Mas não fizemos nenhum progresso hoje...",
  ui_story_5038_50381101_21_dialog_content = "E estamos ficando sem tempo.",
  ui_story_5038_50381101_22_dialog_content = "Bem ali!",
  ui_story_5038_50381101_23_dialog_content = "O que é isso? Onde?!",
  ui_story_5038_50381101_24_dialog_content = "Olhe para onde estou apontando!",
  ui_story_5038_50381101_25_dialog_content = "Sim, algo está flutuando por aqui!",
  ui_story_5038_50381101_26_dialog_content = "Isso é... uma placa?",
  ui_story_5038_50381101_27_dialog_content = "Mais perto... Mais perto...",
  ui_story_5038_50381101_28_dialog_content = "Acho que posso ver!",
  ui_story_5038_50381101_29_dialog_content = "É uma placa! Ele lê...",
  ui_story_5038_50381101_30_dialog_content = "Lin!",
  ui_story_5038_50381101_31_dialog_content = "É da Guilda Lin!",
  ui_story_5038_50381101_32_dialog_content = "A Guilda Lin? Poderia ser o velho Shadowind?",
  ui_story_5038_50381101_33_dialog_content = "Parece que caiu na água não faz muito tempo!",
  ui_story_5038_50381101_34_dialog_content = "É um sinal claro de que o navio está próximo!",
  ui_story_5038_50381101_35_dialog_content = "Onde está o bote? Eu estou levando!",
  ui_story_5038_50381101_36_dialog_content = "Agora mesmo?",
  ui_story_5038_50381101_37_dialog_content = "Você não deveria conversar sobre isso com Yuebai primeiro—",
  ui_story_5038_50381101_38_dialog_content = "Isso não é necessário.",
  ui_story_5038_50381101_39_dialog_content = "Yuebai...?",
  ui_story_5038_50381101_40_dialog_content = "<color=#e8d9bb>Splash!</color>",
  ui_story_5038_50381101_41_dialog_content = "S-Ela, ela simplesmente mergulhou direto na água!",
  ui_story_5038_50381101_42_dialog_content = "Eu invejo as pessoas que não temem a água!",
  ui_story_5038_50381101_43_dialog_content = "De jeito nenhum, não posso ficar para trás!",
  ui_story_5038_50381101_44_dialog_content = "Rápido, abaixe o bote!",
  ui_story_5038_50381101_45_dialog_content = "(A água tem um cheiro forte de madeira.)",
  ui_story_5038_50381101_46_dialog_content = "(Vindo de mais abaixo.)",
  ui_story_5038_50381101_47_dialog_content = "(O navio Lin afundou aqui?)",
  ui_story_5038_50381101_48_dialog_content = "(Espero que a Bússola não tenha corroído...)",
  ui_story_5038_50381101_49_dialog_content = "(Suspiro, só posso depender de outra coisa no final, afinal.)",
  ui_story_5038_50381101_50_dialog_content = "(Eu deveria continuar descendo.)",
  ui_story_5038_50381101_51_dialog_content = "(Preciso mergulhar mais fundo.)",
  ui_story_5038_50381101_52_dialog_content = "(Para o fundo do oceano...)",
  ui_story_5038_50381101_53_dialog_content = "(Espere, isso é...)",
  ui_story_5038_50381101_54_dialog_content = "(!!!)",
  ui_story_5038_50381101_55_dialog_content = "(Navios afundados... múltiplos.)",
  ui_story_5038_50381101_56_dialog_content = "(Então é assim que os navios que estou tão acostumado a ver no fundo do mar.)",
  ui_story_5038_50381101_57_dialog_content = "(Eles parecem tão serenos, incomumente.)",
  ui_story_5038_50381101_58_dialog_content = "(Não importa o que eles encontraram antes, no fundo do oceano, há apenas serenidade.)",
  ui_story_5038_50381101_59_dialog_content = "(A quietude beira o medo.)",
  ui_story_5038_50381101_60_dialog_content = "(O mar devorou não só os navios, mas também as tripulações e seus gritos angustiados.)",
  ui_story_5038_50381101_61_dialog_content = "(Absorve tudo em suas garras abissais; nem mesmo as ondas são poupadas.)",
  ui_story_5038_50381101_62_dialog_content = "(Isto é como um cemitério para navios naufragados, seu porto final.)",
  ui_story_5038_50381101_63_dialog_content = "(Uma vez ancorados aqui, eles nunca mais zarparam.)",
  ui_story_5038_50381101_64_dialog_content = "(Devo dar uma olhada neles?)",
  ui_story_5038_50381101_65_dialog_content = "(Mas eu não vejo a nave Lin...)",
  ui_story_5038_50381101_66_dialog_content = "<color=#e8d9bb>Splash!</color>",
  ui_story_5038_50381101_67_dialog_content = "Ok, o bote está pronto para você.",
  ui_story_5038_50381101_68_dialog_content = "Você está indo agora?",
  ui_story_5038_50381101_69_dialog_content = "Sim, agora!",
  ui_story_5038_50381101_70_dialog_content = "Deixe-me ir com você, Liqing.",
  ui_story_5038_50381101_71_dialog_content = "Você ir sozinha me deixa um pouco...",
  ui_story_5038_50381101_72_dialog_content = "A-Você não tem medo de água?",
  ui_story_5038_50381101_73_dialog_content = "Hum...",
  ui_story_5038_50381101_74_dialog_content = "Tudo bem, você pode vir junto.",
  ui_story_5038_50381101_75_dialog_content = "O remo é muito longo para eu remar sozinho.",
  ui_story_5038_50381101_76_dialog_content = "Perfeito, vamos lá!",
  ui_story_5038_50381101_77_dialog_content = "Mova o bote para—",
  ui_story_5038_50381101_78_dialog_content = "Graah...",
  ui_story_5038_50381101_79_dialog_content = "O que é que foi isso?!",
  ui_story_5038_50381101_80_dialog_content = "Algo se apoderou do bote!",
  ui_story_5038_50381101_81_dialog_content = "O quê?!",
  ui_story_5038_50381101_82_dialog_content = "Quem seria estúpido o suficiente...",
  ui_story_5038_50381101_83_dialog_content = "Ahhh!",
  ui_story_5038_50381101_84_dialog_content = "Ei, ei!",
  ui_story_5038_50381101_85_dialog_content = "De onde veio tanta escória?!",
  ui_story_5038_50381101_86_dialog_content = "Lá em baixo! A corda amarrada ao bote!",
  ui_story_5038_50381101_87_dialog_content = "Eclipsitos estão subindo nele!",
  ui_story_5038_50381102_1_dialog_content = "Ah...",
  ui_story_5038_50381102_2_dialog_content = "Isso é péssimo... Minha mão está suja agora.",
  ui_story_5038_50381102_3_dialog_content = "Algum outro Eclipsite?",
  ui_story_5038_50381102_4_dialog_content = "Não, eles estão todos mortos.",
  ui_story_5038_50381102_5_dialog_content = "Bom ouvir. Vamos, temos que ir!",
  ui_story_5038_50381102_6_dialog_content = "Tem certeza que quer ir lá embaixo?",
  ui_story_5038_50381102_7_dialog_content = "Pode ser mais perigoso no mar.",
  ui_story_5038_50381102_8_dialog_content = "Bem, seu capitão acabou de mergulhar.",
  ui_story_5038_50381102_9_dialog_content = "Você deveria se preocupar mais com ela.",
  ui_story_5038_50381102_10_dialog_content = "Vamos, PlayerName.",
  ui_story_5038_50381102_11_dialog_content = "Claro!",
  ui_story_5038_50381102_12_dialog_content = "Não nos siga, Tinytail.",
  ui_story_5038_50381102_13_dialog_content = "Miau?",
  ui_story_5038_50381102_14_dialog_content = "Você não percebe o quão vasto é o oceano até estar em um bote.",
  ui_story_5038_50381102_15_dialog_content = "Você acha que vamos encontrar o velho navio Lin?",
  ui_story_5038_50381102_16_dialog_content = "Bem, a pista que temos indica que não está longe.",
  ui_story_5038_50381102_17_dialog_content = "Mas...",
  ui_story_5038_50381102_18_dialog_content = "Você está preocupado que tenha afundado?",
  ui_story_5038_50381102_19_dialog_content = "Uhum.",
  ui_story_5038_50381102_20_dialog_content = "A placa estava flutuando sozinha como todos os destroços que vimos antes.",
  ui_story_5038_50381102_21_dialog_content = "Talvez o vento tenha soprado.",
  ui_story_5038_50381102_22_dialog_content = "Ou foi arrancado por Eclipsites embarcando no navio.",
  ui_story_5038_50381102_23_dialog_content = "De qualquer forma, o importante é o fato de sabermos que está em algum lugar próximo.",
  ui_story_5038_50381102_24_dialog_content = "Devemos encontrá-lo.",
  ui_story_5038_50381102_25_dialog_content = "Eu gosto de como você está confiante naquele navio.",
  ui_story_5038_50381102_26_dialog_content = "É claro. Está carregando a Bússola.",
  ui_story_5038_50381102_27_dialog_content = "(Tenho a sensação de que Liqing está especialmente empenhado em encontrar The Compass.)",
  ui_story_5038_50381102_28_dialog_content = "(Mas seu motivo é diferente do de Yuebai.)",
  ui_story_5038_50381102_29_dialog_content = "(Eu posso entender por que ela está com pressa, mas não o quão sério Liqing leva isso.)",
  ui_story_5038_50381102_30_dialog_content = "(Talvez eu esteja mais acostumado com o quão descontraído ele costuma ser.)",
  ui_story_5038_50381102_31_dialog_content = "O que houve?",
  ui_story_5038_50381102_32_dialog_content = "Névoa?",
  ui_story_5038_50381102_33_dialog_content = "Sim, estamos perdendo visibilidade rapidamente.",
  ui_story_5038_50381102_34_dialog_content = "Isso é irritante. Onde está o vento quando você precisa dele?",
  ui_story_5038_50381102_35_dialog_content = "Como vamos encontrar alguma coisa nisso?",
  ui_story_5038_50381102_36_dialog_content = "Uh, de repente eu pensei em algo ainda mais preocupante...",
  ui_story_5038_50381102_37_dialog_content = "Como vamos voltar para Shadowind se não podemos ver?",
  ui_story_5038_50381102_38_dialog_content = "D-Você se lembra para que lado está o navio?",
  ui_story_5038_50381102_39_dialog_content = "Uh, de volta por ali?",
  ui_story_5038_50381102_40_dialog_content = "Ou talvez para a esquerda?",
  ui_story_5038_50381102_41_dialog_content = "Então você não sabe.",
  ui_story_5038_50381102_42_dialog_content = "Se perdermos o navio...",
  ui_story_5038_50381102_43_dialog_content = "Vamos. Não é tão ruim.",
  ui_story_5038_50381102_44_dialog_content = "Aqui temos uma vara de pescar. Podemos viver de peixe por alguns dias.",
  ui_story_5038_50381102_45_dialog_content = "Eu gostaria de viver mais do que \"alguns dias\", muito obrigado...",
  ui_story_5038_50381102_46_dialog_content = "Além disso, se chegarmos ao velho navio e à Bússola primeiro...",
  ui_story_5038_50381102_47_dialog_content = "Podemos até chegar antes deles em Longzhou.",
  ui_story_5038_50381102_48_dialog_content = "Como começamos a encontrar algo em meio a tanto nevoeiro?",
  ui_story_5038_50381102_49_dialog_content = "Não deveríamos ficar parados e esperar que o nevoeiro passe?",
  ui_story_5038_50381102_50_dialog_content = "Você tem razão.",
  ui_story_5038_50381102_51_dialog_content = "<color=#e8d9bb>Splash!</color>",
  ui_story_5038_50381102_52_dialog_content = "Aaaaaaaargh!!",
  ui_story_5038_50381102_53_dialog_content = "O que foi?",
  ui_story_5038_50381102_54_dialog_content = "Estou toda encharcada!!!!!!!",
  ui_story_5038_50381102_55_dialog_content = "Fique atrás de mim, Liqing—",
  ui_story_5038_50381102_56_dialog_content = "Pare de gritar, sou só eu.",
  ui_story_5038_50381102_57_dialog_content = "Yuebai?",
  ui_story_5038_50381102_58_dialog_content = "Você saiu do oceano?",
  ui_story_5038_50381102_59_dialog_content = "Você vê mais alguma coisa aqui?",
  ui_story_5038_50381102_60_dialog_content = "D-Você tinha que continuar assim?",
  ui_story_5038_50381102_61_dialog_content = "Ugh, estou tão repugnantemente molhada...",
  ui_story_5038_50381102_62_dialog_content = "Desculpe, não estou acostumado a atender às necessidades de um hidrófobo na água.",
  ui_story_5038_50381102_63_dialog_content = "Mas por que...",
  ui_story_5038_50381102_64_dialog_content = "Vamos ser sérios por um momento.",
  ui_story_5038_50381102_65_dialog_content = "Acabei de descobrir um cemitério de navios lá embaixo.",
  ui_story_5038_50381102_66_dialog_content = "Então realmente existem navios naufragados...",
  ui_story_5038_50381102_67_dialog_content = "Espere, você mergulhou até o fundo do oceano?",
  ui_story_5038_50381102_68_dialog_content = "Eu não teria feito isso se não fosse um ótimo nadador.",
  ui_story_5038_50381102_69_dialog_content = "Falando no cemitério, está cheio de navios mercantes.",
  ui_story_5038_50381102_70_dialog_content = "Olhei em volta, mas não encontrei a nave Lin.",
  ui_story_5038_50381102_71_dialog_content = "Então não está aí...",
  ui_story_5038_50381102_72_dialog_content = "Você notou alguma coisa na superfície?",
  ui_story_5038_50381102_73_dialog_content = "Não.",
  ui_story_5038_50381102_74_dialog_content = "É difícil ver à noite e agora a névoa está obscurecendo tudo.",
  ui_story_5038_50381102_75_dialog_content = "Esqueça a nave Lin, nem sabemos onde nosso Shadowind está agora.",
  ui_story_5038_50381102_76_dialog_content = "Eu esperava tanto.",
  ui_story_5038_50381102_77_dialog_content = "Provavelmente não vamos encontrar nada neste nevoeiro.",
  ui_story_5038_50381102_78_dialog_content = "Vamos voltar. Passe-me o remo.",
  ui_story_5038_50381102_79_dialog_content = "Certo! Você sabe onde o Shadowind?",
  ui_story_5038_50381102_80_dialog_content = "É claro. Como um capitão poderia perder seu navio?",
  ui_story_5038_50381102_81_dialog_content = "Maravilhoso! Isso me faz sentir muito melhor!",
  ui_story_5038_50381102_82_dialog_content = "R-Reme mais rápido, tenho que me secar em uma fornalha o mais rápido possível.",
  ui_story_5038_50381102_83_dialog_content = "Sim, não vou perder tempo.",
  ui_story_5038_50381102_84_dialog_content = "(Yuebai rema muito melhor do que Liqing ou eu.)",
  ui_story_5038_50381102_85_dialog_content = "(Com toda essa névoa densa nos cercando, não sei dizer se o barco está realmente se movendo, muito menos em que direção estamos indo.)",
  ui_story_5038_50381102_86_dialog_content = "(Yuebai pode realmente encontrar seu caminho no nevoeiro?)",
  ui_story_5038_50381102_87_dialog_content = "(Eu confio nela, no entanto. Ela encontrou o bote, não é? Um grande navio como o Shadowind não deve ser um problema.)",
  ui_story_5038_50381102_88_dialog_content = "Atchim!",
  ui_story_5038_50381102_89_dialog_content = "Quando eu voltar, tenho que fazer um...",
  ui_story_5038_50381102_90_dialog_content = "Ei, isso é...?",
  ui_story_5038_50381102_91_dialog_content = "Sim, estamos em casa!",
  ui_story_5038_50381102_92_dialog_content = "Sim, nós somos. Eu não poderia dizer até que estivéssemos tão perto.",
  ui_story_5038_50381102_93_dialog_content = "E esta é a primeira vez que vejo o Shadowind deste ângulo.",
  ui_story_5038_50381102_94_dialog_content = "Tão grande e magnífico...",
  ui_story_5038_50381102_95_dialog_content = "Vamos arranjar alguém para nos puxar para cima.",
  ui_story_5038_50381102_96_dialog_content = "Ei, tripulação!",
  ui_story_5038_50381102_97_dialog_content = "Aqui embaixo!",
  ui_story_5038_50381102_98_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5038_50381102_99_dialog_content = "Sem resposta... Estão todos na cama?",
  ui_story_5038_50381102_100_dialog_content = "Sim, por que está tão quieto?",
  ui_story_5038_50381102_101_dialog_content = "Ei, alguém pode me ouvir?",
  ui_story_5038_50381102_102_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5038_50381102_103_dialog_content = "Isso é estranho, eu não poderia ser mais alto.",
  ui_story_5038_50381102_104_dialog_content = "Eu sei que é difícil ver no nevoeiro, mas não deve ser difícil de ouvir, não é?",
  ui_story_5038_50381102_105_dialog_content = "Este navio...",
  ui_story_5038_50381102_106_dialog_content = "O que você acha que está acontecendo, Yuebai?",
  ui_story_5038_50381102_107_dialog_content = "Vamos embarcar e dar uma olhada.",
  ui_story_5038_50381102_108_dialog_content = "Eu vejo uma corda ali. Podemos nos levantar.",
  ui_story_5038_50381201_1_dialog_content = "De onde veio toda essa névoa?",
  ui_story_5038_50381201_2_dialog_content = "Diz-me tu. O capitão, Liqing, e PlayerName ainda estão por aí. Se eles se perderem...",
  ui_story_5038_50381201_3_dialog_content = "Quem sabe se algum dia os veremos novamente?",
  ui_story_5038_50381201_4_dialog_content = "Eles estão lá fora? Pelo que?",
  ui_story_5038_50381201_5_dialog_content = "Eles encontraram uma pista para o Shadowind original e foram procurá-lo em um bote.",
  ui_story_5038_50381201_6_dialog_content = "Ninguém esperava que essa névoa repentina caísse sobre nós.",
  ui_story_5038_50381201_7_dialog_content = "Diga a todos para levantar tochas e ficar de vigília na proa.",
  ui_story_5038_50381201_8_dialog_content = "Já dobrei as velas para minimizar o movimento do navio.",
  ui_story_5038_50381201_9_dialog_content = "O capitão tem um grande senso de direção e deve ser capaz de encontrar o caminho de volta.",
  ui_story_5038_50381201_10_dialog_content = "Mas os outros dois, porém...",
  ui_story_5038_50381201_11_dialog_content = "Então, Sr. Swindler, por que convocou Jiu e eu aqui?",
  ui_story_5038_50381201_12_dialog_content = "Temos três pessoas desaparecidas e gostaria de ajudar a encontrá-las.",
  ui_story_5038_50381201_13_dialog_content = "Você não será capaz de fazer nenhuma diferença dada a densidade da névoa.",
  ui_story_5038_50381201_14_dialog_content = "É melhor você se juntar a mim na cabine para apoio emocional.",
  ui_story_5038_50381201_15_dialog_content = "Suporte emocional? O que você está fazendo?",
  ui_story_5038_50381201_16_dialog_content = "Vou ver o Senhor Zhong.",
  ui_story_5038_50381201_17_dialog_content = "Huh? Ele te assusta ou algo assim?",
  ui_story_5038_50381201_18_dialog_content = "<color=#e8d9bb>Tum, tum...</color>",
  ui_story_5038_50381201_19_dialog_content = "Perdoe-me, Senhor Zhong.",
  ui_story_5038_50381201_20_dialog_content = "Vejo que há neblina lá fora. Há algo de errado?",
  ui_story_5038_50381201_21_dialog_content = "A tripulação disse que o capitão, Liqing, e PlayerName saiu em busca do velho navio, e agora eles estão desaparecidos...",
  ui_story_5038_50381201_22_dialog_content = "Essa névoa é muito inoportuna...",
  ui_story_5038_50381201_23_dialog_content = "Se eles conseguirem encontrar o velho navio, eles ficarão bem.",
  ui_story_5038_50381201_24_dialog_content = "Caso contrário, o mar está repleto de perigos.",
  ui_story_5038_50381201_25_dialog_content = "Isso é verdade, especialmente com o peixe-serpente que pode atacar a qualquer momento.",
  ui_story_5038_50381201_26_dialog_content = "Devido aos nossos problemas de visibilidade, até o Shadowind está em perigo.",
  ui_story_5038_50381201_27_dialog_content = "Estamos, não estamos?",
  ui_story_5038_50381201_28_dialog_content = "E a nave não pode sobreviver a outro ataque.",
  ui_story_5038_50381201_29_dialog_content = "Talvez eu devesse adivinhar o futuro do Shadowind.",
  ui_story_5038_50381201_30_dialog_content = "Se posso prever o que vai nos atacar, podemos pelo menos tentar nos preparar para isso.",
  ui_story_5038_50381201_31_dialog_content = "Você pode calcular esse tipo de coisa?",
  ui_story_5038_50381201_32_dialog_content = "O timing é tudo, e agora é o momento mais oportuno.",
  ui_story_5038_50381201_33_dialog_content = "No entanto, sou apenas um amador, então minhas habilidades são limitadas.",
  ui_story_5038_50381201_34_dialog_content = "Espero que isso funcione.",
  ui_story_5038_50381201_35_dialog_content = "<color=#e8d9bb>Ruído, farfalhar...</color>",
  ui_story_5038_50381201_36_dialog_content = "Tão? O que você tem?",
  ui_story_5038_50381201_37_dialog_content = "Agradeço aos céus por sua benevolência em me fornecer respostas.",
  ui_story_5038_50381201_38_dialog_content = "A verdade será revelada aqui, de onde este fio do destino começou.",
  ui_story_5038_50381201_39_dialog_content = "Foi aqui que o Shadowind encontrou seu perigo.",
  ui_story_5038_50381201_40_dialog_content = "Senhor Zhong, este bastão indica você como a causa!",
  ui_story_5038_50381201_41_dialog_content = "Olá...!",
  ui_story_5038_50381201_42_dialog_content = "Você deveria ter vergonha de si mesmo, PlayerName, precisando de mim para puxá-lo pela corda.",
  ui_story_5038_50381201_43_dialog_content = "Desculpe, nem todo mundo está acostumado a escalar em todo lugar.",
  ui_story_5038_50381201_44_dialog_content = "Ok, estamos a bordo, mas...",
  ui_story_5038_50381201_45_dialog_content = "Não vejo ninguém por perto.",
  ui_story_5038_50381201_46_dialog_content = "O que está acontecendo? Todos saíram à nossa procura?",
  ui_story_5038_50381201_47_dialog_content = "Vamos verificar as cabines, talvez estejam se protegendo da neblina.",
  ui_story_5038_50381201_48_dialog_content = "Espere, não entramos na cabana daqui?",
  ui_story_5038_50381201_49_dialog_content = "Uh, acho que me virei na subida. Talvez seja desta forma...",
  ui_story_5038_50381201_50_dialog_content = "Não.",
  ui_story_5038_50381201_51_dialog_content = "Hã?",
  ui_story_5038_50381201_52_dialog_content = "Tudo está desligado.",
  ui_story_5038_50381201_53_dialog_content = "O mastro, as grades, o convés...",
  ui_story_5038_50381201_54_dialog_content = "Não estamos no Shadowind.",
  ui_story_5038_50381201_55_dialog_content = "Cuidado, atrás de você!",
  ui_story_5038_50381201_56_dialog_content = "Há Eclipsites no navio...",
  ui_story_5038_50381201_57_dialog_content = "Um monte deles.",
  ui_story_5038_50381201_58_dialog_content = "Oh não, estamos cercados...",
  ui_story_5038_50381201_59_dialog_content = "Lide com os da esquerda primeiro, Yuebai!",
  ui_story_5038_50381201_60_dialog_content = "Eu estou trabalhando nisso.",
  ui_story_5038_50381201_61_dialog_content = "Você parece ter um talento especial para lidar com situações como esta.",
  ui_story_5038_50381201_62_dialog_content = "Não é de surpreender, considerando que até sonho com Eclipsites aparecendo do nada.",
  ui_story_5038_50381201_63_dialog_content = "Agora temos que tomar cuidado com—",
  ui_story_5038_50381201_64_dialog_content = "Eu descobri!",
  ui_story_5038_50381201_65_dialog_content = "O que você descobriu?",
  ui_story_5038_50381201_66_dialog_content = "Eu reconheço isso! Eu já estive aqui antes!",
  ui_story_5038_50381201_67_dialog_content = "Este é o Shadowind! O Shadowind original!!",
  ui_story_5038_50381201_68_dialog_content = "O quê?!",
  ui_story_5038_50381201_69_dialog_content = "Sim...",
  ui_story_5038_50381201_70_dialog_content = "Nós o encontramos por pura sorte?",
  ui_story_5038_50381201_71_dialog_content = "Estou certo disso! Este é o trilho que eu dobrei antes!",
  ui_story_5038_50381201_72_dialog_content = "Incrível, finalmente encontramos!",
  ui_story_5038_50381201_73_dialog_content = "Nós fizemos, mas eu não chamaria exatamente nossa situação atual de \"incrível\"...",
  ui_story_5038_50381201_74_dialog_content = "O Compass está nas cabines. Eu sei exatamente onde é!",
  ui_story_5038_50381201_75_dialog_content = "Me siga. Vou levá-lo para ele!",
  ui_story_5038_50381201_76_dialog_content = "Ei, calma, você não sabe se tem Eclipsites lá dentro!",
  ui_story_5038_50381201_77_dialog_content = "Espere por nós, pelo menos...",
  ui_story_5038_50381201_78_dialog_content = "E lá vai ele.",
  ui_story_5038_50381201_79_dialog_content = "Pessoal, acompanhem!",
  ui_story_5038_50381201_80_dialog_content = "Acho que ele não vai te ouvir.",
  ui_story_5038_50381201_81_dialog_content = "Venha, vamos seguir.",
  ui_story_5038_50381201_82_dialog_content = "Os eclipses não vão me parar.",
  ui_story_5038_50381202_1_dialog_content = "Você está dizendo que Lorde Zhong fez com que o Shadowind fosse atacado? Como isso é possível?",
  ui_story_5038_50381202_2_dialog_content = "Sua adivinhação é confiável?",
  ui_story_5038_50381202_3_dialog_content = "Li Tianxian, você estava atrás de mim o tempo todo.",
  ui_story_5038_50381202_4_dialog_content = "Você fez esta leitura antes do tempo, não é?",
  ui_story_5038_50381202_5_dialog_content = "Muito perspicaz, Senhor Zhong.",
  ui_story_5038_50381202_6_dialog_content = "Eu verifiquei minhas baquetas quando o peixe-serpente apareceu pela segunda vez.",
  ui_story_5038_50381202_X6_dialog_content = "Quando o fiz, o símbolo que me foi revelado foi o Tigre Yin.",
  ui_story_5038_50381202_X7_dialog_content = "Eu não conseguia descobrir o que isso significava.",
  ui_story_5038_50381202_X8_dialog_content = "Até que de repente me lembrei do velho ditado: \"Quem tem o tigre, lidera o batalhão\".",
  ui_story_5038_50381202_X9_dialog_content = "Você já comandou milhares de soldados empunhando um tigre em uma bandeira de guerra. Você é a pessoa implicada por esta adivinhação.",
  ui_story_5038_50381202_X10_dialog_content = "Interessante. Continue.",
  ui_story_5038_50381202_X11_dialog_content = "A palavra \"Xu\" em seu nome pode significar borboleta.",
  ui_story_5038_50381202_7_dialog_content = "Talvez você tenha batido suas asas naquela época, o que resultou nesta tempestade que se forma hoje.",
  ui_story_5038_50381202_8_dialog_content = "Uma vez você nos contou a história da desventura do velho navio.",
  ui_story_5038_50381202_9_dialog_content = "O navio Lin carregado de tesouros foi saqueado por piratas.",
  ui_story_5038_50381202_10_dialog_content = "No entanto, de alguma forma, no final, os únicos sobreviventes foram você e Liqing, que eram apenas convidados de honra.",
  ui_story_5038_50381202_11_dialog_content = "Que papéis vocês dois desempenharam no encontro?",
  ui_story_5038_50381202_12_dialog_content = "Espero que você possa responder a esta e outras perguntas.",
  ui_story_5038_50381202_13_dialog_content = "Você está aqui para me interrogar; portanto, você pode dispensar as formalidades.",
  ui_story_5038_50381202_14_dialog_content = "Você trouxe Dantang e Jiu com medo de me enfurecer, não trouxe?",
  ui_story_5038_50381202_15_dialog_content = "V-É por isso que você pediu apoio emocional...",
  ui_story_5038_50381202_16_dialog_content = "Apesar de estar confinado a uma cadeira de rodas, continua bastante intimidador, meu senhor.",
  ui_story_5038_50381202_17_dialog_content = "Eu provavelmente teria sido reduzido a gaguejar se estivesse sozinho na sua presença.",
  ui_story_5038_50381202_18_dialog_content = "Tudo bem, já que você perguntou, vou elaborar.",
  ui_story_5038_50381202_19_dialog_content = "Na verdade, também tenho suspeitado que o peixe-serpente veio por minha causa.",
  ui_story_5038_50381202_20_dialog_content = "Ou melhor, que sou responsável por seu comportamento errático.",
  ui_story_5038_50381202_21_dialog_content = "Como assim?",
  ui_story_5038_50381202_22_dialog_content = "Vamos começar com o antigo Shadowind.",
  ui_story_5038_50381202_23_dialog_content = "É verdade que os Lins têm um tesouro no navio e atraíram piratas gananciosos.",
  ui_story_5038_50381202_24_dialog_content = "No entanto, eu não estava no Shadowind naquela época. Eu estava seguindo em uma embarcação atrás dos piratas.",
  ui_story_5038_50381202_25_dialog_content = "Você os estava seguindo?",
  ui_story_5038_50381202_26_dialog_content = "Prometi ao Lin Guildmaster que protegeria sua propriedade.",
  ui_story_5038_50381202_27_dialog_content = "Portanto, segui os piratas durante toda a jornada e embarquei no Shadowind algum tempo depois deles.",
  ui_story_5038_50381202_28_dialog_content = "Meu pensamento era recuperar a Bússola deles e voltar para pousar em um barco.",
  ui_story_5038_50381202_29_dialog_content = "O que aconteceu naquela noite no navio acabou sendo muito pior do que eu imaginava.",
  ui_story_5038_50381202_30_dialog_content = "Os piratas apreenderam o navio, mas não conseguiram encontrar a Bússola.",
  ui_story_5038_50381202_31_dialog_content = "Eles começaram a torturar a tripulação por seu paradeiro.",
  ui_story_5038_50381202_32_dialog_content = "Não há leis nem justiça em alto mar, coisa que os canalhas levam como patos na água.",
  ui_story_5038_50381202_33_dialog_content = "Quando cheguei lá, ninguém da família Lin ainda estava vivo.",
  ui_story_5038_50381202_34_dialog_content = "Foi quando percebi que recuperar a Bússola era inútil.",
  ui_story_5038_50381202_35_dialog_content = "Os Lins já estão em uma situação terrível. Possuir a Bússola só trará mais problemas.",
  ui_story_5038_50381202_36_dialog_content = "A melhor maneira de proteger o tesouro é deixá-lo \"desaparecer\".",
  ui_story_5038_50381202_37_dialog_content = "Você o descartou, então?",
  ui_story_5038_50381202_38_dialog_content = "Claro que não. É uma herança de Lin e sua única esperança de ganhar destaque novamente.",
  ui_story_5038_50381202_39_dialog_content = "A Bússola deve ser mantida em segredo, então eu tinha que garantir que ninguém nunca mais falasse sobre isso.",
  ui_story_5038_50381202_40_dialog_content = "Ninguém deve falar disso...",
  ui_story_5038_50381202_41_dialog_content = "Espere, você está me dizendo que você...",
  ui_story_5038_50381202_42_dialog_content = "Sim, tive que matar todos os piratas presentes.",
  ui_story_5038_50381202_43_dialog_content = "Lutei em muitas batalhas ao longo dos anos, mas nunca experimentei nada tão sombrio quanto isso.",
  ui_story_5038_50381202_44_dialog_content = "Esses piratas não são guerreiros. Eles são oportunistas por natureza e, quando são derrotados, imploram de joelhos por misericórdia.",
  ui_story_5038_50381202_45_dialog_content = "Eles xingam, lamentam e se envergonham quando a situação se torna sombria.",
  ui_story_5038_50381202_46_dialog_content = "Eles não estavam tentando me vencer, tanto quanto tentando sobreviver a mim.",
  ui_story_5038_50381202_47_dialog_content = "Alguns deles eram realmente irredimíveis, alguns simplesmente tentavam ganhar a vida. As pessoas acabam como foras da lei por todos os tipos de razões.",
  ui_story_5038_50381202_48_dialog_content = "Mas não tive tempo de considerar essas razões. Eu só poderia matar todos eles.",
  ui_story_5038_50381202_49_dialog_content = "Para preservar a Bússola?",
  ui_story_5038_50381202_50_dialog_content = "Foi o que eu disse para me convencer.",
  ui_story_5038_50381202_51_dialog_content = "Houve momentos fugazes em que senti que estava indo longe demais.",
  ui_story_5038_50381202_52_dialog_content = "Mas no segundo em que minha lâmina ficou manchada de sangue, era tarde demais para voltar atrás.",
  ui_story_5038_50381202_53_dialog_content = "Entendo...",
  ui_story_5038_50381202_54_dialog_content = "Eu menti sobre o navio ser atingido por uma tempestade.",
  ui_story_5038_50381202_55_dialog_content = "Serpentfish foi o verdadeiro culpado que enviou Liqing e eu à deriva no mar.",
  ui_story_5038_50381202_56_dialog_content = "Peixe-serpente de novo?",
  ui_story_5038_50381202_57_dialog_content = "É por isso que eu ponderei se eles estavam atrás de mim.",
  ui_story_5038_50381202_58_dialog_content = "O ataque deles lembrava o ataque ao antigo Shadowind.",
  ui_story_5038_50381202_59_dialog_content = "Nenhuma dessas coisas é relevante para a busca pela Bússola, então não vi necessidade de mencioná-las.",
  ui_story_5038_50381202_60_dialog_content = "Mas já que você insistiu, agora eu confesso.",
  ui_story_5038_50381202_61_dialog_content = "Ninguém gostaria de aliviar uma experiência como essa. Peço desculpas por ser intrometido!",
  ui_story_5038_50381202_62_dialog_content = "Está tudo certo. Devemos confiar uns nos outros inequivocamente para superar nossa situação atual.",
  ui_story_5038_50381202_63_dialog_content = "Sim, devemos estar unidos.",
  ui_story_5038_50381202_64_dialog_content = "Eu deveria gastar mais tempo tentando descobrir como vamos resolver os problemas atuais.",
  ui_story_5038_50381202_65_dialog_content = "É quase impossível fazer qualquer coisa neste nevoeiro.",
  ui_story_5038_50381202_66_dialog_content = "Mas Liqing é muito dedicado a encontrar a Bússola e tem instintos demoníacos especiais.",
  ui_story_5038_50381202_67_dialog_content = "Dado que ele estava disposto a ir para o mar, isso significa que o navio está próximo.",
  ui_story_5038_50381202_68_dialog_content = "Talvez quando a névoa se dissipar, ele volte com a Bússola.",
  ui_story_5038_50381202_69_dialog_content = "Esse seria o melhor cenário...",
  ui_story_5038_50381202_70_dialog_content = "<color=#e8d9bb>Crash!</color>",
  ui_story_5038_50381202_71_dialog_content = "O quê...",
  ui_story_5038_50381202_72_dialog_content = "<size=45><color=#e8d9bb>Baque!</color></size>",
  ui_story_5038_50381202_73_dialog_content = "Ahhhhhh!",
  ui_story_5038_50381202_74_dialog_content = "O que aconteceu? Por que estamos lançando tão mal?",
  ui_story_5038_50381202_75_dialog_content = "Meu senhor, você está—",
  ui_story_5038_50381202_76_dialog_content = "Estou bem. Suba no convés para ver o que está acontecendo!",
  ui_story_5038_50381202_77_dialog_content = "Absolutamente! Por favor, espere aqui...",
  ui_story_5038_50381202_78_dialog_content = "<size=45>Aaaaaaahhhhhhh!!!</size>",
  ui_story_5038_50381202_79_dialog_content = "Por que o marinheiro está gritando?!",
  ui_story_5038_50381202_80_dialog_content = "Navio AA...",
  ui_story_5038_50381202_81_dialog_content = "<size=50>Um navio acabou de se chocar contra nós!</size>",
  ui_story_5038_50381301_1_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5038_50381301_2_dialog_content = "Ei o que está acontecendo?!",
  ui_story_5038_50381301_3_dialog_content = "O arco deve ter colidido com alguma coisa. Você está bem?",
  ui_story_5038_50381301_4_dialog_content = "Estou bem. Já estou acostumado com o ambiente instável de um navio.",
  ui_story_5038_50381301_5_dialog_content = "O que atingimos, um recife?",
  ui_story_5038_50381301_6_dialog_content = "Venha rápido, é logo à frente.",
  ui_story_5038_50381301_7_dialog_content = "A propósito, algum de vocês pode arrombar uma fechadura?",
  ui_story_5038_50381301_8_dialog_content = "A porta parece ser...",
  ui_story_5038_50381301_9_dialog_content = "Minha lâmina pode.",
  ui_story_5038_50381301_10_dialog_content = "<color=#e8d9bb>Shiing!</color>",
  ui_story_5038_50381301_11_dialog_content = "Cuidado, você quase cortou minha cabeça!",
  ui_story_5038_50381301_12_dialog_content = "Você não vai entrar?",
  ui_story_5038_50381301_13_dialog_content = "Hunf...",
  ui_story_5038_50381301_14_dialog_content = "Venha e contemple os tesouros que todos esperamos.",
  ui_story_5038_50381301_15_dialog_content = "<color=#e8d9bb>*Ranger*</color>",
  ui_story_5038_50381301_16_dialog_content = "Nossa...",
  ui_story_5038_50381301_17_dialog_content = "É tão elegante aqui!",
  ui_story_5038_50381301_18_dialog_content = "Então é assim que os clãs ricos de Longzhou são, hein?",
  ui_story_5038_50381301_19_dialog_content = "Esses desenhos...",
  ui_story_5038_50381301_20_dialog_content = "Eles são muito parecidos com os encontrados no Lin Manor que eu me lembro.",
  ui_story_5038_50381301_21_dialog_content = "Eles devem ter guardado essas antiguidades e pinturas aqui depois da queda da família.",
  ui_story_5038_50381301_22_dialog_content = "A Mansão Lin? Essa era a sua casa?",
  ui_story_5038_50381301_23_dialog_content = "Eu vivi lá brevemente quando eu era jovem.",
  ui_story_5038_50381301_24_dialog_content = "Até que a Lin Guild entrou em declínio, perdeu toda a sua fortuna e foi forçada a entregar a propriedade.",
  ui_story_5038_50381301_25_dialog_content = "Nunca pensei que seria capaz de me entregar a imagens do passado novamente.",
  ui_story_5038_50381301_26_dialog_content = "Lares de infância definitivamente evocam um ataque de emoções...",
  ui_story_5038_50381301_27_dialog_content = "Vamos parar de relembrar.",
  ui_story_5038_50381301_28_dialog_content = "Qual destes é The Compass, Liqing?",
  ui_story_5038_50381301_29_dialog_content = "De jeito nenhum, isso não pode ser...",
  ui_story_5038_50381301_30_dialog_content = "O que há de errado, Liqing?",
  ui_story_5038_50381301_31_dialog_content = "Não está aqui... Como não está aqui?",
  ui_story_5038_50381301_32_dialog_content = "Como assim?",
  ui_story_5038_50381301_33_dialog_content = "Talvez estivesse escondido em outro lugar.",
  ui_story_5038_50381301_34_dialog_content = "Liqing, descreva The Compass para nós e nós o ajudaremos a encontrá-lo.",
  ui_story_5038_50381301_35_dialog_content = "Mas... onde mais poderia estar?",
  ui_story_5038_50381301_36_dialog_content = "Só pode estar em um tanque em algum lugar, no entanto...",
  ui_story_5038_50381301_37_dialog_content = "Em um tanque?",
  ui_story_5038_50381301_38_dialog_content = "Aguentar. A bússola não é uma bússola?",
  ui_story_5038_50381301_39_dialog_content = "A Bússola é um peixe.",
  ui_story_5038_50381301_40_dialog_content = "O quê?!",
  ui_story_5038_50381301_41_dialog_content = "Hi...",
  ui_story_5038_50381301_42_dialog_content = "<color=#e8d9bb>*Respingo*</color>",
  ui_story_5038_50381301_43_dialog_content = "<color=#e8d9bb>*Respingo*</color>",
  ui_story_5038_50381301_44_dialog_content = "O-O que está acontecendo?! Parece que algo está prestes a quebrar!",
  ui_story_5038_50381301_45_dialog_content = "É porcelana, mas não consigo ver onde está...",
  ui_story_5038_50381301_46_dialog_content = "Oh não, acabei de ver alguém sair correndo!",
  ui_story_5038_50381301_47_dialog_content = "Tinha mais alguém aqui?!",
  ui_story_5038_50381301_48_dialog_content = "<color=#828282>Bater!</color>",
  ui_story_5038_50381301_49_dialog_content = "Ei, a porta está fechada!",
  ui_story_5038_50381301_50_dialog_content = "É ele do outro lado!",
  ui_story_5038_50381301_51_dialog_content = "Quem? Quem está do outro lado?",
  ui_story_5038_50381301_52_dialog_content = "Agradecer...",
  ui_story_5038_50381301_53_dialog_content = "?!!",
  ui_story_5038_50381301_54_dialog_content = "Obrigado... Obrigado... Você.",
  ui_story_5038_50381301_55_dialog_content = "<color=#e8d9bb>Tum, tum, tum...</color>",
  ui_story_5038_50381301_56_dialog_content = "Isso...",
  ui_story_5038_50381301_57_dialog_content = "Ele fugiu! Temos que nos atualizar!",
  ui_story_5038_50381301_58_dialog_content = "Esta porta... Capităo, pode abri-la?",
  ui_story_5038_50381301_59_dialog_content = "Eu tentei. Está barricado com algo pesado.",
  ui_story_5038_50381301_60_dialog_content = "Isso não é bom... Temos que alcançá-lo.",
  ui_story_5038_50381301_61_dialog_content = "O que podemos fazer...",
  ui_story_5038_50381301_62_dialog_content = "Vamos nos jogar na porta e arrombá-la!",
  ui_story_5038_50381301_63_dialog_content = "Isso não vai funcionar, só nós três não é o suficiente.",
  ui_story_5038_50381301_64_dialog_content = "Acalme-se primeiro.",
  ui_story_5038_50381301_65_dialog_content = "Como posso quando ele está prestes a fugir?!",
  ui_story_5038_50381301_66_dialog_content = "Como vamos encontrá-lo lá no mar imenso?",
  ui_story_5038_50381301_67_dialog_content = "Er, eu poderia ter uma maneira de abrir a porta.",
  ui_story_5038_50381301_68_dialog_content = "Sério?",
  ui_story_5038_50381301_69_dialog_content = "Sim, mas preciso de um tempo.",
  ui_story_5038_50381301_70_dialog_content = "Me dê um momento...",
  ui_story_5038_50381301_71_dialog_content = "(Isto é provavelmente absurdo, mas...)",
  ui_story_5038_50381301_72_dialog_content = "(Não custa nada tentar!)",
  ui_story_5038_50381301_73_option_content = "Aumento de Força!",
  ui_story_5038_50381301_74_dialog_content = "De repente, ele fica imóvel. Ele deve estar usando sua habilidade psíquica.",
  ui_story_5038_50381301_X74_dialog_content = "Por que você não aproveita para me contar qual é o problema com o The Compass?",
  ui_story_5038_50381301_75_dialog_content = "E quem foi que fugiu?",
  ui_story_5038_50381301_76_dialog_content = "Uh, por onde devo começar...?",
  ui_story_5038_50381301_77_dialog_content = "Na verdade, nunca vi essa pessoa antes.",
  ui_story_5038_50381301_78_dialog_content = "Mas se ele estava aqui, só há uma possibilidade.",
  ui_story_5038_50381301_79_dialog_content = "Ele é a bússola.",
  ui_story_5038_50381301_80_dialog_content = "Ele é o quê?!",
  ui_story_5038_50381301_81_dialog_content = "Em um minuto você diz que o Compass é um peixe, no minuto seguinte você me diz que ele é uma pessoa. O que está acontecendo?",
  ui_story_5038_50381301_82_dialog_content = "O Compass é de fato um peixe, e um peixe-serpente muito especial.",
  ui_story_5038_50381301_83_dialog_content = "Mas só porque é um peixe não significa que tenha que se parecer com um.",
  ui_story_5038_50381301_84_dialog_content = "Lembre-se, eu sou um gato.",
  ui_story_5038_50381301_85_dialog_content = "Você está dizendo que ele é um demônio?",
  ui_story_5038_50381301_86_dialog_content = "Sim, essa é a única possibilidade.",
  ui_story_5038_50381301_87_dialog_content = "Ele provavelmente se transformou em um fiendling enquanto o navio estava à deriva.",
  ui_story_5038_50381301_88_dialog_content = "A evolução o libertou da água e da restrição de um tanque.",
  ui_story_5038_50381301_89_dialog_content = "Mas ele ainda não conseguia sair da cabine trancada.",
  ui_story_5038_50381301_90_dialog_content = "Até quebrarmos a fechadura...",
  ui_story_5038_50381301_91_dialog_content = "... Entendo.",
  ui_story_5038_50381301_92_dialog_content = "A Bússola é um peixe... Como um peixe navega em um navio?",
  ui_story_5038_50381301_93_dialog_content = "Como Lin, você deve conhecer muito bem o totem da sua família, certo?",
  ui_story_5038_50381301_94_dialog_content = "Serpentfish atuará coletivamente para um indivíduo na escola.",
  ui_story_5038_50381301_95_dialog_content = "E The Compass é o líder do peixe-serpente.",
  ui_story_5038_50381301_96_dialog_content = "O líder?!",
  ui_story_5038_50381301_97_dialog_content = "Não é à toa que os peixes-serpentes começaram a se comportar de maneira estranha e a lotar esta área do mar.",
  ui_story_5038_50381301_98_dialog_content = "Foi assim que você e Zhong Xu descobriram que a Bússola estava aqui.",
  ui_story_5038_50381301_99_dialog_content = "Isso mesmo.",
  ui_story_5038_50381301_100_dialog_content = "Hum, acho que entendi agora.",
  ui_story_5038_50381301_101_dialog_content = "Os peixes-serpente são especialistas em atravessar as águas entre os dois continentes, como é de sua natureza.",
  ui_story_5038_50381301_102_dialog_content = "O ex-Shadowind explorou suas habilidades capturando o peixe-serpente de chumbo.",
  ui_story_5038_50381301_103_dialog_content = "Ao manter seu líder cativo, toda a escola começou a ajudar o navio a cruzar o oceano...",
  ui_story_5038_50381301_104_dialog_content = "Exatamente.",
  ui_story_5038_50381301_105_dialog_content = "Os Lins confinaram o peixe-serpente chumbo a bordo.",
  ui_story_5038_50381301_106_dialog_content = "Gerações se passaram e o peixe-serpente recém-nascido passou a ver o Shadowind como seu líder.",
  ui_story_5038_50381301_107_dialog_content = "Eles se reuniam atrás do navio e o empurravam para frente sempre que o navio partia.",
  ui_story_5038_50381301_108_dialog_content = "Portanto, nunca houve necessidade de se preocupar em se perder ou ficar preso por causa do mau tempo.",
  ui_story_5038_50381301_109_dialog_content = "Os peixes sempre os entregavam ao seu destino.",
  ui_story_5038_50381301_110_dialog_content = "Como é que ninguém me falou sobre isso antes?",
  ui_story_5038_50381301_111_dialog_content = "Os Lins não, nem você nem Zhong Xu.",
  ui_story_5038_50381301_112_dialog_content = "Sobre isso... Zhong Xu meio que explicou um pouco, mas eu realmente não entendi.",
  ui_story_5038_50381301_113_dialog_content = "Parecia complicado. Algo sobre segredos comerciais, proteção da honra da família e assim por diante.",
  ui_story_5038_50381301_114_dialog_content = "Em suma, manter a mãe era a melhor opção.",
  ui_story_5038_50381301_115_dialog_content = "...",
  ui_story_5038_50381301_116_dialog_content = "Quanto a mim, bem... acho que me sinto culpado por tudo isso.",
  ui_story_5038_50381301_117_dialog_content = "Desde o dia em que pisei no velho Shadowind, tornei-me cúmplice da escravidão.",
  ui_story_5038_50381301_118_dialog_content = "Sempre que o mar se tornava caprichoso, fui forçado a tratá-lo como um instrumento.",
  ui_story_5038_50381301_119_dialog_content = "Chamei-o de Bússola para me sentir melhor.",
  ui_story_5038_50381301_120_dialog_content = "Culpa...",
  ui_story_5038_50381301_121_dialog_content = "Pelo menos você tem a percepção de se sentir assim.",
  ui_story_5038_50381301_122_dialog_content = "Provavelmente porque sempre pensei nele como um amigo.",
  ui_story_5038_50381301_123_dialog_content = "Ah, sim, ele tem um nome. É Yoh.",
  ui_story_5038_50381301_124_dialog_content = "Yoh... eu vou me lembrar disso.",
  ui_story_5038_50381301_125_dialog_content = "Ah, desculpe interromper...",
  ui_story_5038_50381301_126_dialog_content = "Acho que consegui.",
  ui_story_5038_50381301_127_dialog_content = "Você fez? Você abriu a porta?",
  ui_story_5038_50381301_128_dialog_content = "Sim, daqui a pouco estará aberto.",
  ui_story_5038_50381301_129_dialog_content = "Uau, impressionante!",
  ui_story_5038_50381301_130_dialog_content = "Vocês dois devem se preparar embora.",
  ui_story_5038_50381301_131_dialog_content = "Preparar-nos? Para que?",
  ui_story_5038_50381301_132_dialog_content = "Aí vem eles!",
  ui_story_5038_50381301_133_dialog_content = "<color=#e8d9bb>Crash!</color>",
  ui_story_5038_50381301_134_dialog_content = "Grrr!",
  ui_story_5038_50381301_135_dialog_content = "Ah!!! Isso me assustou!",
  ui_story_5038_50381301_136_dialog_content = "Como os Eclipsitas entraram?",
  ui_story_5038_50381301_137_dialog_content = "Espere um minuto, foi assim que você abriu a porta?",
  ui_story_5038_50381301_138_dialog_content = "Desenhar os Eclipsites e fazê-los passar por ela?",
  ui_story_5038_50381301_139_dialog_content = "Você não chamaria isso de violento, mas eficaz?",
  ui_story_5038_50381301_140_dialog_content = "Bem feito. É muito mais fácil lidar com os Eclipsites do que com a porta.",
  ui_story_5038_50381301_141_dialog_content = "Vamos eliminá-los!",
  ui_story_5038_50381302_1_dialog_content = "O que está acontecendo? O que está errado?",
  ui_story_5038_50381302_2_dialog_content = "Eclipsites... Eles estão no convés!",
  ui_story_5038_50381302_3_dialog_content = "Eles vieram do navio atrás de nós!",
  ui_story_5038_50381302_4_dialog_content = "Graaah!",
  ui_story_5038_50381302_5_dialog_content = "Scram, seu imundo!",
  ui_story_5038_50381302_6_dialog_content = "Graah...",
  ui_story_5038_50381302_7_dialog_content = "Há muitos deles...",
  ui_story_5038_50381302_8_dialog_content = "Por favor, recue, Alteza.",
  ui_story_5038_50381302_9_dialog_content = "Deixe-me lidar com trabalho bruto como este.",
  ui_story_5038_50381302_10_dialog_content = "Todos, reúnam-se na popa!",
  ui_story_5038_50381302_11_dialog_content = "Segure a linha contra os Eclipsites. Não os deixe fazer o que quiserem!",
  ui_story_5038_50381302_12_dialog_content = "Sim!",
  ui_story_5038_50381302_13_dialog_content = "O que está acontecendo, Senhor Zhong?",
  ui_story_5038_50381302_14_dialog_content = "Por que uma nave cheia de Eclipsites se concentraria em nós?",
  ui_story_5038_50381302_15_dialog_content = "É um navio muito grande...",
  ui_story_5038_50381302_16_dialog_content = "Talvez as ondas o tenham carregado por puro acaso e a baixa visibilidade tenha agravado o problema.",
  ui_story_5038_50381302_17_dialog_content = "Oh não, eles estão destruindo o mastro!",
  ui_story_5038_50381302_18_dialog_content = "Cuidado, grande parte do convés foi destruído!",
  ui_story_5038_50381302_19_dialog_content = "Isso é ruim, temos que fazer alguma coisa!",
  ui_story_5038_50381302_20_dialog_content = "Eclipsos podres!",
  ui_story_5038_50381302_21_dialog_content = "Vamos ajudar, Jiu!",
  ui_story_5038_50381302_22_dialog_content = "Por favor, espere.",
  ui_story_5038_50381302_23_dialog_content = "Por quê?",
  ui_story_5038_50381302_24_dialog_content = "Lutar no Shadowind só irá danificar ainda mais a nave.",
  ui_story_5038_50381302_25_dialog_content = "Devemos mover o campo de batalha.",
  ui_story_5038_50381302_26_dialog_content = "Jogada? Você quer dizer...",
  ui_story_5038_50381302_27_dialog_content = "Junte tábuas e construa uma ponte para aquela outra embarcação.",
  ui_story_5038_50381302_28_dialog_content = "Se deve haver um incêndio, certifiquemo-nos de que não é o nosso navio que arde.",
  ui_story_5038_50381401_1_dialog_content = "Não está em condições de lutar, meu senhor. Por favor, fique aqui.",
  ui_story_5038_50381401_2_dialog_content = "Temos mão de obra suficiente para nos livrarmos dos Eclipsites.",
  ui_story_5038_50381401_3_dialog_content = "Ela está certa. Não adianta se machucar.",
  ui_story_5038_50381401_4_dialog_content = "Não se preocupem com isso.",
  ui_story_5038_50381401_5_dialog_content = "Eu não teria seguido se acreditasse que seria um fardo.",
  ui_story_5038_50381401_6_dialog_content = "(Não se engane, este é o Shadowind original.)",
  ui_story_5038_50381401_7_dialog_content = "(A Bússola está tão perto. Vou recuperá-la desta vez.)",
  ui_story_5038_50381401_8_dialog_content = "(Eu não renego minhas promessas, Sr. Lin.)",
  ui_story_5038_50381401_9_dialog_content = "Aí vem mais Eclipsites, Alteza.",
  ui_story_5038_50381401_10_dialog_content = "Há mais aqui do que em nosso navio.",
  ui_story_5038_50381401_11_dialog_content = "Sem problemas, nós devemos—",
  ui_story_5038_50381401_12_dialog_content = "Só um segundo, por favor, recue alguns passos.",
  ui_story_5038_50381401_13_dialog_content = "Não seja pego na minha linha de fogo.",
  ui_story_5038_50381401_14_dialog_content = "Huh? Meu senhor, o que você está...",
  ui_story_5038_50381401_15_dialog_content = "<size=50>As chamas devem reduzir tudo a cinzas!</size>",
  ui_story_5038_50381401_16_dialog_content = "Tenha cuidado, Alteza!",
  ui_story_5038_50381401_17_dialog_content = "Gaahhhh!",
  ui_story_5038_50381401_18_dialog_content = "Que chama intensa!",
  ui_story_5038_50381401_19_dialog_content = "Todos os Eclipsitos estão chamuscados...",
  ui_story_5038_50381401_20_dialog_content = "Até a névoa se dissipou!",
  ui_story_5038_50381401_21_dialog_content = "Não é de admirar que Lorde Zhong insistisse em vir.",
  ui_story_5038_50381401_22_dialog_content = "Não há como ele desencadear algo assim a bordo do Shadowind.",
  ui_story_5038_50381401_23_dialog_content = "Este velho navio está à deriva há muito tempo, assaltado pelas ondas, corroído pelos ventos salgados do oceano.",
  ui_story_5038_50381401_24_dialog_content = "É uma casca de seu antigo eu agora. A única coisa que ainda está intacta é a moldura.",
  ui_story_5038_50381401_25_dialog_content = "Um fogo arderia intensamente aqui.",
  ui_story_5038_50381401_26_dialog_content = "Excelente! Vamos nos apressar e lidar com os Eclipsites com o fogo de Lord Zhong!",
  ui_story_5038_50381401_27_dialog_content = "O Shadowind ainda está esperando que voltemos e ajudemos.",
  ui_story_5038_50381401_28_dialog_content = "Tenha cuidado, Alteza, o convés enfraquecido pelo fogo pode desabar.",
  ui_story_5038_50381401_29_dialog_content = "Hum, você está certo sobre isso...",
  ui_story_5038_50381401_30_dialog_content = "Vamos nos segurar, Jiu.",
  ui_story_5038_50381401_31_dialog_content = "Dessa forma, se um de nós escorregar, o outro pode ajudar.",
  ui_story_5038_50381401_32_dialog_content = "E-Espera...",
  ui_story_5038_50381401_33_dialog_content = "Como você diz, Sua Alteza.",
  ui_story_5038_50381401_34_dialog_content = "Muito bem, vocês dois, deixem-me limpar o caminho à frente para vocês.",
  ui_story_5038_50381401_35_dialog_content = "Sim, vamos seguir em frente.",
  ui_story_5038_50381401_36_dialog_content = "Há outra coisa que eu queria fazer além de me livrar dos Eclipsites.",
  ui_story_5038_50381401_37_dialog_content = "Você deve fazê-lo neste navio?",
  ui_story_5038_50381401_38_dialog_content = "Se eu estiver correto, este é o Shadowind original.",
  ui_story_5038_50381401_39_dialog_content = "Tenho certos laços com o navio.",
  ui_story_5038_50381401_40_dialog_content = "Oh, então este é o lendário navio perdido...",
  ui_story_5038_50381401_41_dialog_content = "Há uma antiguidade a bordo.",
  ui_story_5038_50381401_42_dialog_content = "Devo recuperá-lo antes que a nave queime.",
  ui_story_5038_50381401_43_dialog_content = "Parece algo muito importante.",
  ui_story_5038_50381401_44_dialog_content = "Sim, pode nos ajudar a retornar a Longzhou.",
  ui_story_5038_50381401_45_dialog_content = "(A Bússola foi negligenciada por tanto tempo, espero que esteja tudo bem.)",
  ui_story_5038_50381401_46_dialog_content = "(É bastante ridículo pensar nisso...)",
  ui_story_5038_50381401_47_dialog_content = "(Que a longevidade de uma rota entre dois continentes anda nas costas de um peixe.)",
  ui_story_5038_50381401_48_dialog_content = "<color=#e8d9bb>*Pisando passos*...</color>",
  ui_story_5038_50381401_49_dialog_content = "Hum?",
  ui_story_5038_50381401_50_dialog_content = "Espera, acho que ouvi um barulho.",
  ui_story_5038_50381401_51_dialog_content = "Um Eclipsite escondido, talvez?",
  ui_story_5038_50381401_52_dialog_content = "Não, Alteza, isso soa como...",
  ui_story_5038_50381401_53_dialog_content = "<color=#e8d9bb>Embaralhar, embaralhar...</color>",
  ui_story_5038_50381401_54_dialog_content = "Passos.",
  ui_story_5038_50381401_55_dialog_content = "Passos?! Deveria haver outras pessoas aqui além de nós?",
  ui_story_5038_50381401_56_dialog_content = "É você.",
  ui_story_5038_50381401_57_dialog_content = "!!!",
  ui_story_5038_50381401_58_dialog_content = "Quem é esse? Quem está falando?",
  ui_story_5038_50381401_59_dialog_content = "Saia e—",
  ui_story_5038_50381401_60_dialog_content = "Ao controle.",
  ui_story_5038_50381401_61_dialog_content = "Argh!",
  ui_story_5038_50381401_62_dialog_content = "Peguei você, Alteza!",
  ui_story_5038_50381401_63_dialog_content = "L-Olha!",
  ui_story_5038_50381401_64_dialog_content = "Senhor Zhong—",
  ui_story_5038_50381401_65_dialog_content = "Tosse...",
  ui_story_5038_50381401_66_dialog_content = "Quem é você?",
  ui_story_5038_50381401_67_dialog_content = "Eu conheço você.",
  ui_story_5038_50381401_68_dialog_content = "Mas eu não sei...",
  ui_story_5038_50381401_69_dialog_content = "Espera, você tem rabo?!",
  ui_story_5038_50381401_70_dialog_content = "Você... estava... no... navio.",
  ui_story_5038_50381401_71_dialog_content = "Isso é uma cauda de peixe-serpente.",
  ui_story_5038_50381401_72_dialog_content = "Essa é uma característica Lin. Você é Lin?",
  ui_story_5038_50381401_73_dialog_content = "Você... ajudou... Lins.",
  ui_story_5038_50381401_74_dialog_content = "Não, você não pode ser um Lin.",
  ui_story_5038_50381401_75_dialog_content = "Ninguém sobreviveu a esse massacre.",
  ui_story_5038_50381401_76_dialog_content = "As únicas coisas que apareceriam aqui seriam as posses de Lin.",
  ui_story_5038_50381401_77_dialog_content = "Seu nome.",
  ui_story_5038_50381401_78_dialog_content = "Zhong... Xu.",
  ui_story_5038_50381401_79_dialog_content = "Você é isso.",
  ui_story_5038_50381401_80_dialog_content = "O tesouro mais valorizado pelos Lins.",
  ui_story_5038_50381401_81_dialog_content = "Você é Yoh.",
  ui_story_5038_50381401_82_dialog_content = "Quem é aquela criança? E por que ele machucou Lord Zhong?",
  ui_story_5038_50381401_83_dialog_content = "Tenha cuidado, ele é muito poderoso.",
  ui_story_5038_50381401_84_dialog_content = "Como uma criança tão pequena pode ser tão...",
  ui_story_5038_50381401_85_dialog_content = "Ele poderia ser um demônio?",
  ui_story_5038_50381401_86_dialog_content = "Não acredito que é assim que você está agora...",
  ui_story_5038_50381401_87_dialog_content = "Por que você me atacou?",
  ui_story_5038_50381401_88_dialog_content = "Lins... merece... morrer.",
  ui_story_5038_50381401_89_dialog_content = "... Como eu suspeitava, você os despreza.",
  ui_story_5038_50381401_90_dialog_content = "Porque eles fizeram de você um prisioneiro.",
  ui_story_5038_50381401_91_dialog_content = "Todos... no... navio.",
  ui_story_5038_50381401_92_dialog_content = "Deve morrer.",
  ui_story_5038_50381401_93_dialog_content = "Eu, junto com a família Lin, prevemos há muito tempo seu ódio inevitável.",
  ui_story_5038_50381401_94_dialog_content = "Mas nenhum de nós esperava ser confrontado por esse ódio um dia.",
  ui_story_5038_50381401_95_dialog_content = "Nave... merece... a morte... a maioria.",
  ui_story_5038_50381401_96_dialog_content = "Seu ódio é justificado, então você é bem-vindo a ele.",
  ui_story_5038_50381401_97_dialog_content = "Herdamos os legados de nossos predecessores, assim como suas dívidas.",
  ui_story_5038_50381401_98_dialog_content = "Alguns são apenas mais azarados do que outros e ficam presos entre os dois.",
  ui_story_5038_50381401_99_dialog_content = "Esta parece ser outra grande enrascada da qual tenho de salvá-lo, Lin, velho amigo.",
  ui_story_5038_50381401_100_dialog_content = "Todos... de... vocês... são...",
  ui_story_5038_50381401_101_dialog_content = "inimigos... do... mar.",
  ui_story_5038_50381401_102_dialog_content = "Você... e... este... navio.",
  ui_story_5038_50381401_103_dialog_content = "Afundar... no... oceano.",
  ui_story_5038_50381401_104_dialog_content = "O que está acontecendo?!",
  ui_story_5038_50381401_105_dialog_content = "Espere, Yoh!",
  ui_story_5038_50381401_106_dialog_content = "E-Essa é a voz de Liqing!",
  ui_story_5038_50381401_107_dialog_content = "Huff... Finalmente alcancei você!",
  ui_story_5038_50381401_108_dialog_content = "Li... qing...",
  ui_story_5038_50381401_109_dialog_content = "Então é assim que A Bússola se parece.",
  ui_story_5038_50381401_110_dialog_content = "Por que todos estão aqui? O que aconteceu?",
  ui_story_5038_50381401_111_dialog_content = "Vocês três estiveram aqui o tempo todo?",
  ui_story_5038_50381401_112_dialog_content = "O que está acontecendo? E quem é o garoto?",
  ui_story_5038_50381401_113_dialog_content = "Essa é a Bússola que estávamos procurando.",
  ui_story_5038_50381401_114_dialog_content = "O compasso?!",
  ui_story_5038_50381401_115_dialog_content = "Nenhuma das minhas adivinhações escolheu revelar isso para mim...",
  ui_story_5038_50381401_116_dialog_content = "Espere um minuto, a leitura!",
  ui_story_5038_50381401_117_dialog_content = "Fui apresentado a um grupo muito estranho de três animais: o rato hesitante, o macaco tolo e o coelho astuto.",
  ui_story_5038_50381401_118_dialog_content = "\"O que é ilusão torna-se real, quando o que é real torna-se ilusão.\" Essencialmente, está nos dizendo para <color=#FFB400>substituir</color> aquilo que perdemos.",
  ui_story_5038_50381401_119_dialog_content = "Então era isso que significava!",
  ui_story_5038_50381401_120_dialog_content = "Sobre o que você está divagando?",
  ui_story_5038_50381401_121_dialog_content = "As varas predisseram toda essa jornada.",
  ui_story_5038_50381401_122_dialog_content = "O \"rato hesitante\" era o capitão oscilando entre encontrar a Bússola e chegar a Longzhou.",
  ui_story_5038_50381401_123_dialog_content = "O \"coelho astuto\"... você conhece o ditado: \"Um coelho astuto tem três esconderijos.\" Estava falando da Bússola. Não sabíamos o que era, o que fazia ou onde estava.",
  ui_story_5038_50381401_124_dialog_content = "O segundo bastão, o \"macaco tolo\", reconcilia o primeiro e o último bastão.",
  ui_story_5038_50381401_125_dialog_content = "Somente sendo um tolo, trilhando o caminho impossível e fazendo o impossível, nossa jornada pode terminar.",
  ui_story_5038_50381401_126_dialog_content = "Quando você soma todos os três trigramas, pode ver que o que deveríamos substituir não eram peças de um navio.",
  ui_story_5038_50381401_127_dialog_content = "Estava falando sobre o próprio navio inteiro!",
  ui_story_5038_50381401_128_dialog_content = "O que você está tentando fazer, Yoh?",
  ui_story_5038_50381401_129_dialog_content = "Você está tentando matá-lo?",
  ui_story_5038_50381401_130_dialog_content = "...",
  ui_story_5038_50381401_131_dialog_content = "Não só eu. Ele quer afundar o Shadowind também.",
  ui_story_5038_50381401_132_dialog_content = "Por que você faria isso?",
  ui_story_5038_50381401_133_dialog_content = "Eu sei o quanto foi difícil para você trancado no pequeno tanque.",
  ui_story_5038_50381401_134_dialog_content = "E eu sei que você guarda rancor. Você se sente zangado e até rancoroso.",
  ui_story_5038_50381401_135_dialog_content = "Mas nem todas as pessoas são iguais, nem todo mundo está tentando te machucar.",
  ui_story_5038_50381401_136_dialog_content = "Você não deve fazer pessoas inocentes pagarem pelos pecados dos outros!",
  ui_story_5038_50381401_137_dialog_content = "Você... não deveria... ter... saído.",
  ui_story_5038_50381401_138_dialog_content = "Por que não?",
  ui_story_5038_50381401_139_dialog_content = "Você vai morrer.",
  ui_story_5038_50381401_140_dialog_content = "<color=#e8d9bb>Rachadura!</color>",
  ui_story_5038_50381401_141_dialog_content = "Oh não, o deck está quebrando!",
  ui_story_5038_50381401_142_dialog_content = "Pense nisso, Yoh! É mesmo isto que queres?",
  ui_story_5038_50381401_143_dialog_content = "Ninguém aqui fez nada de errado, principalmente eu!",
  ui_story_5038_50381401_144_dialog_content = "Você esqueceu como eu costumava te alimentar todos os dias?",
  ui_story_5038_50381401_145_dialog_content = "<color=#e8d9bb>Rachadura!</color>",
  ui_story_5038_50381401_146_dialog_content = "Você-Você—!",
  ui_story_5038_50381401_X146_dialog_content = "Ele passou do ponto de ouvir mais alguém. Se não o pararmos, todos a bordo da nave morrerão.",
  ui_story_5038_50381401_X147_dialog_content = "Vamos tentar encontrar uma maneira de detê-lo primeiro.",
  ui_story_5038_50381401_147_dialog_content = "É inútil, filho. O pouco de boa vontade que ele tem em relação a você não é suficiente para reprimir seu ódio.",
  ui_story_5038_50381401_148_dialog_content = "Você espera usar a comida de peixe que você deu a ele antes para trocar pela vida de todos?",
  ui_story_5038_50381401_149_dialog_content = "Mas...",
  ui_story_5038_50381401_150_dialog_content = "O Shadowind não sucumbirá tão facilmente.",
  ui_story_5038_50381401_151_dialog_content = "Nós dissemos que você poderia ficar louco e fazer o que quisesse?",
  ui_story_5038_50381401_152_dialog_content = "Sim, não vamos deixar ninguém prejudicar o navio!",
  ui_story_5038_50381401_153_dialog_content = "Você acha... é realmente certo bater em uma criança?",
  ui_story_5038_50381401_154_dialog_content = "Ele é um demônio e provavelmente tem idade para ser seu avô.",
  ui_story_5038_50381401_155_dialog_content = "Ele está prestes a atacar!",
  ui_story_5038_50381401_156_dialog_content = "Prepare-se para lutar!",
  ui_story_5038_50381402_1_dialog_content = "Fora do caminho.",
  ui_story_5038_50381402_2_dialog_content = "Ele perdeu muito poder!",
  ui_story_5038_50381402_3_dialog_content = "Atacar-nos parece exigir muito dele.",
  ui_story_5038_50381402_4_dialog_content = "Sim. Ele é um novo demônio e ainda não sabe como administrar seus poderes.",
  ui_story_5038_50381402_5_dialog_content = "Ele desperdiçou muita energia em ataques inúteis.",
  ui_story_5038_50381402_6_dialog_content = "Devemos subjugá-lo antes que ele tenha a chance de retaliar.",
  ui_story_5038_50381402_7_dialog_content = "Claro, deixe-me ajudar!",
  ui_story_5038_50381402_8_dialog_content = "Afundar... agora.",
  ui_story_5038_50381402_9_dialog_content = "<color=#e8d9bb>Rachadura!</color>",
  ui_story_5038_50381402_10_dialog_content = "H-Ele está atacando o casco!",
  ui_story_5038_50381402_11_dialog_content = "E se estou vendo direito, os peixes-serpente estão nadando para cá!",
  ui_story_5038_50381402_12_dialog_content = "Faça a sua jogada, Liqing.",
  ui_story_5038_50381402_13_dialog_content = "Sim!",
  ui_story_5038_50381402_14_dialog_content = "Então passamos de amigos para companheiros demônios, hein, Yoh?",
  ui_story_5038_50381402_15_dialog_content = "Li... qing...",
  ui_story_5038_50381402_16_dialog_content = "Você aprendeu a falar.",
  ui_story_5038_50381402_17_dialog_content = "Não... me pare.",
  ui_story_5038_50381402_18_dialog_content = "É uma pena que nunca tivemos a chance de conversar.",
  ui_story_5038_50381402_19_dialog_content = "Fora... de... caminho.",
  ui_story_5038_50381402_20_dialog_content = "Qual é o seu problema? Eu sou um fiendling mais experiente do que você!",
  ui_story_5038_50381402_21_dialog_content = "Ainda há muitas coisas que você precisa aprender!",
  ui_story_5038_50381402_22_dialog_content = "Como seu superior, gostaria de ensiná-los a você, mas...",
  ui_story_5038_50381402_23_dialog_content = "Isso tem que esperar até eu te derrotar!",
  ui_story_5038_50381402_24_dialog_content = "(Agora, Yuebai!)",
  ui_story_5038_50381402_25_dialog_content = "!!!",
  ui_story_5038_50381402_26_dialog_content = "Não coloque a mão no meu navio.",
  ui_story_5038_50381402_27_dialog_content = "Hum...",
  ui_story_5038_50381402_28_dialog_content = "Ele está ferido! Pegue-o agora!",
  ui_story_5038_50381402_29_dialog_content = "Ok! Peguei o braço esquerdo dele!",
  ui_story_5038_50381402_30_dialog_content = "Vou pegar o braço direito, Alteza.",
  ui_story_5038_50381402_31_dialog_content = "V-Vocês não precisam ser tão rudes...",
  ui_story_5038_50381402_32_dialog_content = "Ele está completamente esgotado.",
  ui_story_5038_50381402_33_dialog_content = "Ele é?",
  ui_story_5038_50381402_34_dialog_content = "Sibila... sibila...",
  ui_story_5038_50381402_35_dialog_content = "Os peixes não gritam. Ele ainda não aprendeu a gritar de dor.",
  ui_story_5038_50381402_36_dialog_content = "Ufa, finalmente vencemos.",
  ui_story_5038_50381402_37_dialog_content = "Isso significa que temos The Compass agora?",
  ui_story_5038_50381402_38_dialog_content = "Sim. Ele é a bússola, sem dúvida.",
  ui_story_5038_50381402_39_dialog_content = "Tornar-se um fiendling não muda seu papel como The Compass.",
  ui_story_5038_50381402_40_dialog_content = "Então o que fazemos agora?",
  ui_story_5038_50381402_41_dialog_content = "...",
  ui_story_5038_50381402_42_dialog_content = "...",
  ui_story_5038_50381402_43_dialog_content = "De acordo com os procedimentos, devemos confiná-lo ao Shadowind.",
  ui_story_5038_50381402_44_dialog_content = "Em seguida, instrua-o a enviar o sinal de retorno.",
  ui_story_5038_50381402_45_dialog_content = "Assim que o peixe-serpente receber o sinal, eles se reunirão ao redor do navio e nos escoltarão de volta a Longzhou.",
  ui_story_5038_50381402_46_dialog_content = "Esta viagem será desprovida de qualquer outro perigo, assim como as incontáveis viagens anteriores.",
  ui_story_5038_50381402_47_dialog_content = "Suspirar...",
  ui_story_5038_50381402_48_dialog_content = "Devemos prender uma criança?",
  ui_story_5038_50381402_49_dialog_content = "Uma viagem segura soa bem, mas não estou totalmente confortável com esta opção.",
  ui_story_5038_50381402_50_dialog_content = "Sim, especialmente quando acabamos de testemunhar seu desprezo por nós.",
  ui_story_5038_50381402_51_dialog_content = "O antepassado Lin inspirou o ódio, que se aprofundou com cada passageiro que já subiu a bordo.",
  ui_story_5038_50381402_52_dialog_content = "Todos eles escolheram acreditar que The Compass era apenas um peixe, incapaz de guardar rancor.",
  ui_story_5038_50381402_53_dialog_content = "Todos acreditavam que, se não houvesse ódio, não haveria crime e, sem crime, não haveria necessidade de culpa.",
  ui_story_5038_50381402_54_dialog_content = "Mas é tarde demais para arrependimentos quando o ódio se manifesta diante de seus olhos.",
  ui_story_5038_50381402_55_dialog_content = "Você se arrepende, Senhor Zhong?",
  ui_story_5038_50381402_56_dialog_content = "Você acha que limitar o The Compass também é errado, não é?",
  ui_story_5038_50381402_57_dialog_content = "Lamento muitas coisas.",
  ui_story_5038_50381402_58_dialog_content = "Foi errado massacrar todas aquelas pessoas e é errado escravizar a Bússola.",
  ui_story_5038_50381402_59_dialog_content = "Transferir para o mar uma questão que deveria ter sido resolvida em terra é como acabamos nesta posição.",
  ui_story_5038_50381402_60_dialog_content = "Então, vamos seguir pelo mesmo caminho errado...?",
  ui_story_5038_50381402_61_dialog_content = "Dada a minha idade, não tenho nenhum problema em expiar meus pecados com minha vida.",
  ui_story_5038_50381402_62_dialog_content = "Mas há mais pessoas presentes aqui do que apenas eu.",
  ui_story_5038_50381402_63_dialog_content = "Temos alguma esperança de chegar a Longzhou sem explorar a Bússola?",
  ui_story_5038_50381402_64_dialog_content = "Bom...",
  ui_story_5038_50381402_65_dialog_content = "O navio está danificado e ainda não sabemos a extensão dos danos...",
  ui_story_5038_50381402_66_dialog_content = "Eu sei o que Zhong Xu significa, porque eu mesmo pensei muito sobre isso.",
  ui_story_5038_50381402_67_dialog_content = "Na maioria das vezes, suas mãos estão atadas quando você está no mar.",
  ui_story_5038_50381402_68_dialog_content = "Eu penso em Yoh como meu amigo e quero vê-lo livre, mas...",
  ui_story_5038_50381402_69_dialog_content = "Não posso pagar o preço por essa decisão.",
  ui_story_5038_50381402_70_dialog_content = "Preço...",
  ui_story_5038_50381402_71_dialog_content = "(Ninguém está dizendo uma palavra agora.)",
  ui_story_5038_50381402_72_dialog_content = "(Estamos todos trocando olhares para tentar disfarçar o desamparo que sentimos.)",
  ui_story_5038_50381402_73_dialog_content = "(Como se estivéssemos mostrando remorso através do silêncio.)",
  ui_story_5038_50381402_74_dialog_content = "(Sabemos que é errado, mas não temos outra escolha.)",
  ui_story_5038_50381402_75_dialog_content = "Não sejamos tão taciturnos.",
  ui_story_5038_50381402_76_dialog_content = "Encontramos a bússola. Devemos estar felizes por termos cumprido nossa missão.",
  ui_story_5038_50381402_77_dialog_content = "Vale a pena comemorar o fato de podermos terminar nossa viagem, capitão.",
  ui_story_5038_50381402_78_dialog_content = "Mas a ideia de prender a criança...",
  ui_story_5038_50381402_79_dialog_content = "Quem disse que vamos prendê-lo? Isso é mesmo necessário?",
  ui_story_5038_50381402_80_dialog_content = "Hã?",
  ui_story_5038_50381402_81_dialog_content = "O que quer dizer, capitão?",
  ui_story_5038_50381402_82_dialog_content = "Tínhamos que encontrar o The Compass para ter alguma esperança de chegar a Longzhou.",
  ui_story_5038_50381402_83_dialog_content = "Agora que o localizamos, temos muitas opções quando se trata de como podemos utilizá-lo.",
  ui_story_5038_50381402_84_dialog_content = "É claro que nenhum de nós está bem com a forma como os Lins fizeram isso.",
  ui_story_5038_50381402_85_dialog_content = "Então vou explorar outras opções.",
  ui_story_5038_50381402_86_dialog_content = "Sério? Nós realmente não temos que manter Yoh cativo?",
  ui_story_5038_50381402_87_dialog_content = "...",
  ui_story_5038_50381402_88_dialog_content = "Diga-me, você está disposto a ser um convidado a bordo do Shadowind?",
  ui_story_5038_50381402_89_dialog_content = "... Não.",
  ui_story_5038_50381402_90_dialog_content = "Claro que não.",
  ui_story_5038_50381402_91_dialog_content = "Então acho que é aqui que nos separamos.",
  ui_story_5038_50381402_92_dialog_content = "Este navio vai afundar em breve. Você deve voltar para o mar.",
  ui_story_5038_50381402_93_dialog_content = "Deixe ele ir. Estamos voltando para o nosso navio.",
  ui_story_5038_50381402_94_dialog_content = "A-Tem certeza?",
  ui_story_5038_50381402_95_dialog_content = "Será impossível encontrá-lo novamente.",
  ui_story_5038_50381402_96_dialog_content = "Ele é um peixe. Ele é muito mais adequado para o oceano do que para um navio.",
  ui_story_5038_50381402_97_dialog_content = "Vamos. A névoa se foi. Devemos retomar a viagem.",
  ui_story_5038_50381402_98_dialog_content = "Você já se decidiu?",
  ui_story_5038_50381402_99_dialog_content = "De uma vez só.",
  ui_story_5038_50381402_100_dialog_content = "Você vai me impedir, Lorde Zhong?",
  ui_story_5038_50381402_101_dialog_content = "Prometi ao velho Sr. Lin proteger o tesouro da família.",
  ui_story_5038_50381402_102_dialog_content = "Cumpri essa promessa entregando The Compass a um membro da família Lin.",
  ui_story_5038_50381402_103_dialog_content = "Contanto que você esteja ciente das consequências de sua decisão, eu a respeitarei.",
  ui_story_5038_50381402_104_dialog_content = "Vamos, você ouviu as ordens do capitão.",
  ui_story_5038_50381402_105_dialog_content = "Ela sabe mais do que nós quando se trata de velejar.",
  ui_story_5038_50381402_106_dialog_content = "Sim, verdade... Não devemos nos preocupar.",
  ui_story_5038_50381402_107_dialog_content = "Vamos... Mova-se, PlayerName, por que você está parado aí?",
  ui_story_5038_50381402_108_dialog_content = "Oh, estou apenas observando o peixe-serpente.",
  ui_story_5038_50381402_109_dialog_content = "É espetacular como eles continuam circulando o navio.",
  ui_story_5038_50381402_110_dialog_content = "Como se estivessem apenas esperando que afundasse.",
  ui_story_5038_50381402_111_dialog_content = "Oh, não comece a fazer poética aqui ou algo assim. Você pode fazer isso do Shadowind.",
  ui_story_5038_50381402_112_dialog_content = "Vamos nos mexer.",
  ui_story_5038_50381402_113_dialog_content = "Ok, estou indo.",
  ui_story_5038_50381402_114_dialog_content = "Parabéns, Yoh, você está livre agora!",
  ui_story_5038_50381402_115_dialog_content = "Livre...",
  ui_story_5038_50381402_116_dialog_content = "Você não entendeu? Eles disseram que estão deixando você ir.",
  ui_story_5038_50381402_117_dialog_content = "Não é fácil se tornar um fiendling. Lembre-se de continuar praticando a fala.",
  ui_story_5038_50381402_118_dialog_content = "Tentar conversar com você é cansativo.",
  ui_story_5038_50381402_119_dialog_content = "Me deixar ir?",
  ui_story_5038_50381402_120_dialog_content = "Sim, você não entende?",
  ui_story_5038_50381402_121_dialog_content = "Vá em frente e vá para onde você deveria estar.",
  ui_story_5038_50381402_122_dialog_content = "Eu...",
  ui_story_5038_50381402_123_dialog_content = "Eu tenho que ir. Não estou prestes a cair na água.",
  ui_story_5038_50381402_124_dialog_content = "Mas nunca esqueça que Liqing é seu amigo.",
  ui_story_5038_50381402_125_dialog_content = "Adeus!",
  ui_story_5038_50381402_126_dialog_content = "Aí está você, capitão!",
  ui_story_5038_50381402_127_dialog_content = "O navio foi abalroado, depois abordado por Eclipsites e sofreu muitos danos.",
  ui_story_5038_50381402_128_dialog_content = "Estamos trabalhando arduamente tentando colocá-lo de volta no lugar...",
  ui_story_5038_50381402_129_dialog_content = "Entendido. Não pare com os reparos, mas certifique-se de desenrolar as velas imediatamente.",
  ui_story_5038_50381402_130_dialog_content = "Estamos zarpando.",
  ui_story_5038_50381402_131_dialog_content = "Agora? Não deveríamos nos reagrupar primeiro?",
  ui_story_5038_50381402_132_dialog_content = "Não temos tempo.",
  ui_story_5038_50381402_133_dialog_content = "O peixe-serpente logo iniciará sua viagem de volta e devemos segui-los de perto.",
  ui_story_5038_50381402_134_dialog_content = "O peixe-serpente?",
  ui_story_5038_50381402_135_dialog_content = "É verdade, os peixes-serpente estão começando a nadar!",
  ui_story_5038_50381402_136_dialog_content = "Estão todos indo na mesma direção!",
  ui_story_5038_50381402_137_dialog_content = "É aí que fica Longzhou.",
  ui_story_5038_50381402_138_dialog_content = "Nada no oceano quer voltar para casa mais do que eles.",
  ui_story_5038_50381402_139_dialog_content = "Oh, entendi!",
  ui_story_5038_50381402_140_dialog_content = "Você sabia que assim que soltasse Yoh, o peixe-serpente retomaria sua jornada original.",
  ui_story_5038_50381402_141_dialog_content = "Eles podem nos levar pela rota mais rápida de volta a Longzhou!",
  ui_story_5038_50381402_142_dialog_content = "Parece simples, mas acompanhar o peixe-serpente é mais difícil do que você pensa.",
  ui_story_5038_50381402_143_dialog_content = "Vou precisar da ajuda de todos na etapa final desta jornada.",
  ui_story_5038_50381402_144_dialog_content = "Você pode contar com isso!",
  ui_story_5038_50381402_145_dialog_content = "Oh não, estamos vazando de novo...",
  ui_story_5038_50381402_146_dialog_content = "Precisamos de mais mãos no convés!",
  ui_story_5038_50381402_147_dialog_content = "Todos os membros da tripulação estão muito ocupados para ajudar agora.",
  ui_story_5038_50381402_148_dialog_content = "Será muito difícil para o castigado Shadowind navegar no mar agitado.",
  ui_story_5038_50381402_149_dialog_content = "Isso vai aguentar?",
  ui_story_5038_50381402_150_dialog_content = "A rachadura que selamos antes está vazando de novo.",
  ui_story_5038_50381402_151_dialog_content = "Estamos trabalhando duro para resgatar a água, mas o nível ainda está subindo.",
  ui_story_5038_50381402_152_dialog_content = "O que podemos fazer agora...",
  ui_story_5038_50381402_153_dialog_content = "Não importa, já que todo mundo já está ocupado o suficiente.",
  ui_story_5038_50381402_154_dialog_content = "Teremos que sair mais rápido.",
  ui_story_5038_50381402_155_dialog_content = "Veja, eu tenho um balde em cada mão agora.",
  ui_story_5038_50381402_156_dialog_content = "Espere até eu colocar um na minha boca, então eu posso tirar a água de três pessoas!",
  ui_story_5038_50381402_157_dialog_content = "I-Isso vai funcionar?",
  ui_story_5038_50381402_158_dialog_content = "Tem que ser. Todo mundo está indo all-out desde que estamos tão perto.",
  ui_story_5038_50381402_159_dialog_content = "Tudo ficará bem enquanto o navio ainda puder navegar a toda velocidade.",
  ui_story_5038_50381402_160_dialog_content = "Você deveria sair e me deixar trabalhar!",
  ui_story_5038_50381402_161_dialog_content = "Quem tem um balde vazio? Me dê um!",
  ui_story_5038_50381402_162_dialog_content = "Por aqui, PlayerName!",
  ui_story_5038_50381402_163_dialog_content = "Por favor me de uma ajuda!",
  ui_story_5038_50381402_164_dialog_content = "O que está acontecendo, Dantang? O que você está fazendo...?",
  ui_story_5038_50381402_165_dialog_content = "O guincho que segura as velas no lugar está quebrado, então agora as cordas precisam ser operadas manualmente.",
  ui_story_5038_50381402_166_dialog_content = "Já fiz isso antes, mas agora...",
  ui_story_5038_50381402_167_dialog_content = "O vento aumentou e está me desgastando fisicamente.",
  ui_story_5038_50381402_168_dialog_content = "Oh, eu vejo! Eu posso ajudar.",
  ui_story_5038_50381402_169_dialog_content = "Então eu continuo puxando assim?",
  ui_story_5038_50381402_170_dialog_content = "Sim, assim mesmo.",
  ui_story_5038_50381402_171_dialog_content = "Suas mãos estão todas vermelhas... Você está bem?",
  ui_story_5038_50381402_172_dialog_content = "Está bem. É só porque nunca faço trabalho físico como este.",
  ui_story_5038_50381402_173_dialog_content = "Eu seria completamente inútil se não conseguisse sequer lidar com essa pequena tarefa.",
  ui_story_5038_50381402_174_dialog_content = "Mas não sabemos quanto tempo ainda temos. Suas mãos...",
  ui_story_5038_50381402_175_dialog_content = "E daí? Mesmo o Shadowind não desistiu.",
  ui_story_5038_50381402_176_dialog_content = "Jogue esta caixa ao mar!",
  ui_story_5038_50381402_177_dialog_content = "Sim!",
  ui_story_5038_50381402_178_dialog_content = "Uau, é libertador jogar coisas ao mar!",
  ui_story_5038_50381402_179_dialog_content = "E isso também! Jogue fora!",
  ui_story_5038_50381402_180_dialog_content = "Estamos descartando todos os cobertores?",
  ui_story_5038_50381402_181_dialog_content = "Sim, não vamos dormir por um tempo.",
  ui_story_5038_50381402_182_dialog_content = "Tudo bem, isso vai para o mar também!",
  ui_story_5038_50381402_183_dialog_content = "Perde tudo o que não é essencial. Cada pedaço conta!",
  ui_story_5038_50381402_184_dialog_content = "Estamos lutando contra o próprio mar por mais tempo!",
  ui_story_5038_50381402_185_dialog_content = "Verdade isso.",
  ui_story_5038_50381402_186_dialog_content = "Jogue fora, livre-se de tudo!",
  ui_story_5038_50381402_187_dialog_content = "E todas as mesas, cadeiras e móveis!",
  ui_story_5038_50381402_188_dialog_content = "(As pessoas a bordo nunca estiveram tão ocupadas.)",
  ui_story_5038_50381402_189_dialog_content = "(Cada membro da tripulação e todas as partes do navio estão sendo trabalhadas ao máximo.)",
  ui_story_5038_50381402_190_dialog_content = "(Existem dois resultados possíveis para nós: Sink ou Longzhou.)",
  ui_story_5038_50381402_191_dialog_content = "(É uma luta entre o que é realista e o que é idealista.)",
  ui_story_5038_50381402_192_dialog_content = "(Muito além, na direção da terra, o sol nasce no horizonte, enquanto nosso navio continua afundando.)",
  ui_story_5038_50381402_193_dialog_content = "(O universo está esperando ansiosamente para nos revelar nossos destinos finais.)",
  ui_story_5038_50381402_194_dialog_content = "Estamos perdidos, todo o porão está inundado!",
  ui_story_5038_50381402_195_dialog_content = "Alguma ideia, marinheiros veteranos?",
  ui_story_5038_50381402_196_dialog_content = "Está tudo alagado...",
  ui_story_5038_50381402_197_dialog_content = "Não há nada que possamos fazer. Se o porão estiver inundado, a seguir...",
  ui_story_5038_50381402_198_dialog_content = "Uau, tem água no convés!",
  ui_story_5038_50381402_199_dialog_content = "O que devemos fazer agora...",
  ui_story_5038_50381402_200_dialog_content = "N-estamos afundando...",
  ui_story_5038_50381402_201_dialog_content = "O que fazemos, o que fazemos...",
  ui_story_5038_50381402_202_dialog_content = "Capitão! Capitão!",
  ui_story_5038_50381402_203_dialog_content = "Onde você foi? Você vê o que está acontecendo—",
  ui_story_5038_50381402_204_dialog_content = "Não entrar em pânico. Apenas espere no convés.",
  ui_story_5038_50381402_205_dialog_content = "O Shadowind não vai afundar.",
  ui_story_5038_50381402_206_dialog_content = "<color=#e8d9bb>Bang! Bang! Bang!</color>",
  ui_story_5038_50381402_207_dialog_content = "O-o que é isso?",
  ui_story_5038_50381402_208_dialog_content = "Algo está batendo no fundo do navio...",
  ui_story_5038_50381402_209_dialog_content = "Espere um minuto! Vocês sentem isso? Parece que estamos subindo!",
  ui_story_5038_50381402_210_dialog_content = "Você está certo! O que está havendo-",
  ui_story_5038_50381402_211_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5038_50381402_212_dialog_content = "Estamos voando?!",
  ui_story_5038_50381402_213_dialog_content = "L-Olha lá embaixo! É peixe, muito peixe-serpente!",
  ui_story_5038_50381402_214_dialog_content = "Eles estão carregando o navio nas costas!",
  ui_story_5038_50381402_215_dialog_content = "Oh meu, que espetacular!",
  ui_story_5038_50381402_216_dialog_content = "Eu disse que o peixe-serpente era muito mais adequado para o oceano do que para um navio.",
  ui_story_5038_50381402_217_dialog_content = "Sim, Yoh está nos ajudando!",
  ui_story_5038_50381402_218_dialog_content = "Você está aí, Yoh?",
  ui_story_5038_50381402_219_dialog_content = "Obrigada!!!",
  ui_story_5038_50381402_220_dialog_content = "Você imaginou que isso aconteceria quando você deixasse Yoh ir, Yuebai?",
  ui_story_5038_50381402_221_dialog_content = "Não. Ninguém pode prever o curso do mar efêmero.",
  ui_story_5038_50381402_222_dialog_content = "Tudo o que sei é que fizemos o nosso melhor e alcançamos todos os nossos objetivos.",
  ui_story_5038_50381402_223_dialog_content = "Chegaremos a Longzhou com certeza.",
  ui_story_5038_50381501_1_dialog_content = "O Senhor Zhong já está vindo?",
  ui_story_5038_50381501_2_dialog_content = "Rápido, traga-o aqui.",
  ui_story_5038_50381501_3_dialog_content = "Vindo, vindo! Nossa, todos vocês apenas dão ordens às pessoas.",
  ui_story_5038_50381501_4_dialog_content = "O que você está fazendo, Liqing?",
  ui_story_5038_50381501_5_dialog_content = "Não queremos que perca a vista fabulosa.",
  ui_story_5038_50381501_6_dialog_content = "Olhe para lá. O que você vê?",
  ui_story_5038_50381501_7_dialog_content = "Isso...",
  ui_story_5038_50381501_8_dialog_content = "Estamos em casa?",
  ui_story_5038_50381501_9_dialog_content = "Sim, estamos em casa! Isso é Longzhou!",
  ui_story_5038_50381501_10_dialog_content = "Você sente falta?",
  ui_story_5038_50381501_11_dialog_content = "Longzhou...",
  ui_story_5038_50381501_12_dialog_content = "Na minha vida, o solo sob meus pés raramente foi Longzhou.",
  ui_story_5038_50381501_13_dialog_content = "Eu não esperava sentir tanta nostalgia ao ouvir você trazer isso à tona.",
  ui_story_5038_50381501_14_dialog_content = "Já estamos longe há muito tempo.",
  ui_story_5038_50381501_15_dialog_content = "Sim. Já passamos por muita coisa e viajamos até agora.",
  ui_story_5038_50381501_16_dialog_content = "Ao longo desta jornada, mudamos de navio. Agora também estou confinado a uma cadeira de rodas.",
  ui_story_5038_50381501_17_dialog_content = "Não será tão fácil para mim cumprimentar o imperador na próxima vez que o visitar.",
  ui_story_5038_50381501_18_dialog_content = "Não me diga que só sente falta do palácio em Longzhou.",
  ui_story_5038_50381501_19_dialog_content = "Você também vai ficar nostálgico quando chegar na minha idade.",
  ui_story_5038_50381501_20_dialog_content = "Seja na corte real ou em qualquer outro lugar, anseio por todos os lugares em que já estive.",
  ui_story_5038_50381501_21_dialog_content = "É uma tarefa árdua falar com você...",
  ui_story_5038_50381501_22_dialog_content = "Apenas me diga, você gosta da vista do convés agora?",
  ui_story_5038_50381501_23_dialog_content = "Sim, eu gosto muito.",
  ui_story_5038_50381501_24_dialog_content = "Olha, os peixes-serpente estão nadando para longe!",
  ui_story_5038_50381501_25_dialog_content = "É claro. Eles não podem desembarcar conosco.",
  ui_story_5038_50381501_26_dialog_content = "Eles vão fazer suas próprias coisas depois de nos ajudar.",
  ui_story_5038_50381501_27_dialog_content = "Depois de ser carregado por eles por tanto tempo, é um pouco triste dizer adeus.",
  ui_story_5038_50381501_28_dialog_content = "Eles provavelmente me mimaram.",
  ui_story_5038_50381501_29_dialog_content = "Meu mestre diz que as despedidas são sempre agridoces.",
  ui_story_5038_50381501_30_dialog_content = "Mas como eles não devem ficar conosco, é melhor se contentar com uma despedida adequada.",
  ui_story_5038_50381501_31_dialog_content = "Sim, suponho. Todas as viagens chegam ao fim.",
  ui_story_5038_50381501_32_dialog_content = "Adeus! Obrigado a todos!",
  ui_story_5038_50381501_33_dialog_content = "*Soluçando* Finalmente chegamos em casa...",
  ui_story_5038_50381501_34_dialog_content = "Sim, pensei que íamos todos morrer no mar.",
  ui_story_5038_50381501_35_dialog_content = "É tão bom ver terra.",
  ui_story_5038_50381501_36_dialog_content = "É tudo graças ao capitão. Sem ela, o navio teria afundado dez vezes.",
  ui_story_5038_50381501_37_dialog_content = "Sim, temos um capitão incrível!",
  ui_story_5038_50381501_38_dialog_content = "Pense no que ela nos levou a realizar?",
  ui_story_5038_50381501_39_dialog_content = "Restauramos a rota Lin!",
  ui_story_5038_50381501_40_dialog_content = "Ei, aí vem o capitão!",
  ui_story_5038_50381501_41_dialog_content = "Aqui, capitão! Estávamos apenas elogiando você!",
  ui_story_5038_50381501_42_dialog_content = "Vocês...",
  ui_story_5038_50381501_43_dialog_content = "O que você está fazendo aqui? De volta aos seus posts!",
  ui_story_5038_50381501_44_dialog_content = "O navio está indo para o porto. Ainda não acabou.",
  ui_story_5038_50381501_45_dialog_content = "Ouça isso, não acabou até que acabe, ordens do capitão!",
  ui_story_5038_50381501_46_dialog_content = "Sim, sim!",
  ui_story_5038_50381501_47_dialog_content = "Estou, uh, um pouco nervoso.",
  ui_story_5038_50381501_48_dialog_content = "O que devo fazer depois de sair do navio?",
  ui_story_5038_50381501_49_dialog_content = "Por que você está nervoso? Apenas siga-nos!",
  ui_story_5038_50381501_50_dialog_content = "Você acabou de resistir a uma tempestade infernal no mar. Como estar em terra pode ser mais assustador?",
  ui_story_5038_50381501_51_dialog_content = "Mas estes ambientes são totalmente novos...",
  ui_story_5038_50381501_52_dialog_content = "Nada me é familiar e estou sozinho.",
  ui_story_5038_50381501_53_dialog_content = "O que quer dizer com você está sozinho? Você não tem nós?",
  ui_story_5038_50381501_54_dialog_content = "Isso mesmo.",
  ui_story_5038_50381501_55_dialog_content = "Apenas fique comigo em Longzhou, e vou garantir que você tenha os melhores momentos de sua vida.",
  ui_story_5038_50381501_56_dialog_content = "Tudo bem, vamos começar a fazer as malas.",
  ui_story_5038_50381501_57_dialog_content = "O capitão está pedindo a todos que comecem a se preparar para desembarcar.",
  ui_story_5038_50381501_58_dialog_content = "Espinheiros cristalizados!",
  ui_story_5038_50381501_59_dialog_content = "Espinheiros cristalizados à venda!",
  ui_story_5038_50381501_60_dialog_content = "Quanto custam, senhor?",
  ui_story_5038_50381501_61_dialog_content = "Ei, tem um fabricante de doces ali, vamos dar uma olhada!",
  ui_story_5038_50381501_62_dialog_content = "Isso é bolinhos doces que eu cheiro?",
  ui_story_5038_50381501_63_dialog_content = "Uau, as ruas estão movimentadas!",
  ui_story_5038_50381501_64_dialog_content = "Tantas pessoas!",
  ui_story_5038_50381501_65_dialog_content = "Então, o que você acha?",
  ui_story_5038_50381501_66_dialog_content = "Não tenho certeza... As ruas de Longzhou estão sempre lotadas?",
  ui_story_5038_50381501_67_dialog_content = "Nem sempre. Você chegou bem a tempo para o final do Festival da Primavera.",
  ui_story_5038_50381501_68_dialog_content = "É a hora mais popular em Longzhou. As ruas estão cheias de coisas divertidas e saborosas.",
  ui_story_5038_50381501_69_dialog_content = "Veja, aquele garoto está segurando o que é chamado de Cristalizado Hawthorn. Eles são super azedos, doces e gostosos.",
  ui_story_5038_50381501_70_dialog_content = "E naquela mesa estão pequenas estatuetas em forma de açúcar. Eles são apenas para aparência, não comestíveis.",
  ui_story_5038_50381501_71_dialog_content = "Depois, fervendo naquela panela enorme, estão os bolinhos doces, disponíveis apenas nessa época.",
  ui_story_5038_50381501_72_dialog_content = "Uau, tudo parece bom!",
  ui_story_5038_50381501_73_dialog_content = "Basta perguntar-me se você está curioso sobre qualquer coisa!",
  ui_story_5038_50381501_74_dialog_content = "Deixe-me entender tudo isso.",
  ui_story_5038_50381501_75_dialog_content = "Aquela barraca no chão com o vendedor sacudindo uma vasilha de palitos...",
  ui_story_5038_50381501_76_dialog_content = "Ah, não caia nessa! É uma farsa total!",
  ui_story_5038_50381501_77_dialog_content = "Uma farsa?",
  ui_story_5038_50381501_78_dialog_content = "Sim, chama-se adivinhação. Não vale a pena escrever sobre isso.",
  ui_story_5038_50381501_79_dialog_content = "Esses charlatães dirão qualquer coisa para pegar você com anzol, linha e pecador.",
  ui_story_5038_50381501_80_dialog_content = "É pouco mais do que inventar coisas para roubar seu dinheiro.",
  ui_story_5038_50381501_81_dialog_content = "Por que eles não são presos e colocados na cadeia?",
  ui_story_5038_50381501_82_dialog_content = "Bem, é meio complicado...",
  ui_story_5038_50381501_83_dialog_content = "De qualquer forma, não dê ouvidos a eles, não confie neles. Se você quer saber o que o futuro reserva, eu sou o cara!",
  ui_story_5038_50381501_84_dialog_content = "V-você?",
  ui_story_5038_50381501_85_dialog_content = "Eu pensei que adivinhação era uma farsa?",
  ui_story_5038_50381501_86_dialog_content = "É sobre quem está adivinhando. Eu te disse, é complicado.",
  ui_story_5038_50381501_87_dialog_content = "Heh, há um ditado em Longzhou que diz: \"Duas pessoas raramente concordam.\"",
  ui_story_5038_50381501_88_dialog_content = "Vou deixar você ruminar sobre isso, PlayerName.",
  ui_story_5038_50381501_89_dialog_content = "Abra o caminho, abra o caminho!",
  ui_story_5038_50381501_90_dialog_content = "Você não vê uma cadeira de rodas passando?",
  ui_story_5038_50381501_91_dialog_content = "Devagar, Liqing, para não incomodar os outros.",
  ui_story_5038_50381501_92_dialog_content = "De jeito nenhum! Depois de tanto trabalho para chegar em casa, vou andar como eu quiser!",
  ui_story_5038_50381501_93_dialog_content = "Mas para onde vamos todos, capitão?",
  ui_story_5038_50381501_94_dialog_content = "O Shadowind é o navio dos Lins, então, naturalmente, devo retornar ao Lin Guild.",
  ui_story_5038_50381501_95_dialog_content = "Se não se importam, estão convidados a ficar como meus convidados.",
  ui_story_5038_50381501_96_dialog_content = "Mais o melhor para a temporada de festivais.",
  ui_story_5038_50381501_97_dialog_content = "Vamos, velho?",
  ui_story_5038_50381501_98_dialog_content = "Estou esfomeado.",
  ui_story_5038_50381501_99_dialog_content = "Claro que estamos. Eu teria ido mesmo sem o convite.",
  ui_story_5038_50381501_100_dialog_content = "O Lin Guildmaster me deve muito.",
  ui_story_5038_50381501_101_dialog_content = "Ninguém cobra dívidas durante o Festival da Primavera, Lord Zhong.",
  ui_story_5038_50381501_102_dialog_content = "E dado o estado lamentável em que a guilda está atualmente, não poderíamos pagar o preço pedido por um general como você, meu senhor.",
  ui_story_5038_50381501_103_dialog_content = "Bem, essa é a ideia.",
  ui_story_5038_50381501_104_dialog_content = "Quero que ele tenha vergonha desse fato pelo resto da vida.",
  ui_story_5038_50381501_105_dialog_content = "Eles voltaram! Os viajantes Shadowind estão de volta!",
  ui_story_5038_50381501_106_dialog_content = "Por favor entre! Deve ter sido uma jornada difícil!",
  ui_story_5038_50381501_107_dialog_content = "Você deve estar exausto!",
  ui_story_5038_50381501_108_dialog_content = "Então esta é a mansão Lin?",
  ui_story_5038_50381501_109_dialog_content = "Eu não esperava que o prédio fosse tão comum para um clã que construiu um navio tão grande quanto o Shadowind.",
  ui_story_5038_50381501_110_dialog_content = "Afinal, eles não estão indo muito bem.",
  ui_story_5038_50381501_111_dialog_content = "Ouvi dizer que o portão da frente costumava ser muito maior.",
  ui_story_5038_50381501_112_dialog_content = "Não gosto de portões grandes, são tão impessoais.",
  ui_story_5038_50381501_113_dialog_content = "Tem aquela sensação do Festival da Primavera do jeito que está agora!",
  ui_story_5038_50381501_114_dialog_content = "Por que você não entra já que está em casa?",
  ui_story_5038_50381501_115_dialog_content = "Não fique aí parado.",
  ui_story_5038_50381501_116_dialog_content = "Quem é este senhor idoso?",
  ui_story_5038_50381501_117_dialog_content = "Guildmaster, você não tinha que sair para nos receber.",
  ui_story_5038_50381501_118_dialog_content = "Como não poderia, ouvindo notícias do retorno do Shadowind?",
  ui_story_5038_50381501_119_dialog_content = "Todos vocês são convidados estimados pelo que fizeram. Eu deveria estar esperando por você no píer pessoalmente.",
  ui_story_5038_50381501_120_dialog_content = "Isso mesmo, ele deveria ter feito um banquete no cais para nos receber.",
  ui_story_5038_50381501_121_dialog_content = "Em vez de apenas sentar em casa, aproveitando os frutos do nosso trabalho.",
  ui_story_5038_50381501_122_dialog_content = "Zhong Xu, você está de volta!",
  ui_story_5038_50381501_123_dialog_content = "Suas pernas...",
  ui_story_5038_50381501_124_dialog_content = "Eles estão bem.",
  ui_story_5038_50381501_125_dialog_content = "Tudo o que sofri lutando pelo Exército Imperial todos esses anos foram algumas cicatrizes.",
  ui_story_5038_50381501_126_dialog_content = "Mas fazendo recados para sua guilda, consegui quebrar minhas duas pernas.",
  ui_story_5038_50381501_127_dialog_content = "Velho Lin, você superou o próprio Imperador.",
  ui_story_5038_50381501_128_dialog_content = "Por favor, não diga isso, eu não ousaria...",
  ui_story_5038_50381501_129_dialog_content = "Vou encontrar o melhor médico para você. Apenas fique e leve o seu tempo para convalescer.",
  ui_story_5038_50381501_130_dialog_content = "Isso não será necessário. Eu gosto bastante de relaxar na cadeira de rodas.",
  ui_story_5038_50381501_131_dialog_content = "Além disso, como ficaria em Liqing se alguém conseguisse curar minhas pernas?",
  ui_story_5038_50381501_132_dialog_content = "Isso é impossível!",
  ui_story_5038_50381501_133_dialog_content = "Suas pernas não podem ser curadas, não importa quem tente!",
  ui_story_5038_50381501_134_dialog_content = "H-Ele é muito franco, não é?",
  ui_story_5038_50381501_135_dialog_content = "Não ligue para ele. Liqing sempre foi um atirador certeiro.",
  ui_story_5038_50381501_136_dialog_content = "A viagem que fizemos foi bastante emocionante...",
  ui_story_5038_50381501_137_dialog_content = "No entanto, não consegui recuperar The Compass, Lin.",
  ui_story_5038_50381501_138_dialog_content = "Zhong Xu...",
  ui_story_5038_50381501_139_dialog_content = "Você está me envergonhando.",
  ui_story_5038_50381501_140_dialog_content = "Não foi fácil para você voltar como está.",
  ui_story_5038_50381501_141_dialog_content = "A culpa é minha por não ter conseguido proteger os negócios da família e sobrecarregar um amigo.",
  ui_story_5038_50381501_142_dialog_content = "Peço desculpas a você, Zhong Xu, assim como a todos os presentes.",
  ui_story_5038_50381501_143_dialog_content = "Ah, não importa.",
  ui_story_5038_50381501_144_dialog_content = "Perdi a bússola, então estamos quites.",
  ui_story_5038_50381501_145_dialog_content = "Mas você tem um herdeiro brilhante que agora pode navegar na rota sem a Bússola.",
  ui_story_5038_50381501_146_dialog_content = "Você deve guardar seus sentimentos para ela.",
  ui_story_5038_50381501_147_dialog_content = "Falando nisso, é verdade. Aqui está você, de volta a Longzhou com segurança, sem a bússola.",
  ui_story_5038_50381501_148_dialog_content = "Você se saiu incrivelmente bem, Yuebai.",
  ui_story_5038_50381501_149_dialog_content = "Devo confessar, Guildmaster.",
  ui_story_5038_50381501_150_dialog_content = "Na verdade, tínhamos The Compass, mas decidi deixá-lo ir.",
  ui_story_5038_50381501_151_dialog_content = "Você deixa...",
  ui_story_5038_50381501_152_dialog_content = "Achei que não era certo como exploramos o The Compass.",
  ui_story_5038_50381501_153_dialog_content = "Minha consciência está limpa, mas o fato é que perdi um bem valioso.",
  ui_story_5038_50381501_154_dialog_content = "Portanto, aceitarei qualquer punição que você escolher.",
  ui_story_5038_50381501_155_dialog_content = "Hahahaha. Você está confessando um pecado ou lançando uma acusação?",
  ui_story_5038_50381501_156_dialog_content = "Você aprendeu a esconder lâminas em suas palavras com Lord Zhong ali?",
  ui_story_5038_50381501_157_dialog_content = "Essa não era minha intenção, senhor.",
  ui_story_5038_50381501_158_dialog_content = "Não era um tesouro valioso, mas um último esforço para navegar no mar.",
  ui_story_5038_50381501_159_dialog_content = "Eu deveria estar feliz por você não ter que confiar mais nisso.",
  ui_story_5038_50381501_160_dialog_content = "Obrigado por sua benevolência, Guildmaster.",
  ui_story_5038_50381501_161_dialog_content = "Por que você é tão formal, meu filho?",
  ui_story_5038_50381501_162_dialog_content = "Você liderou uma rota marítima para a Lin Guild por conta própria. Você pode ser o próximo Guildmaster em breve.",
  ui_story_5038_50381501_163_dialog_content = "O quê?!",
  ui_story_5038_50381501_164_dialog_content = "Senhor, você exagera...",
  ui_story_5038_50381501_165_dialog_content = "Não, eu não sou. Você merece isso.",
  ui_story_5038_50381501_166_dialog_content = "Espero que você deixe suas origens para trás. Está tudo no passado.",
  ui_story_5038_50381501_167_dialog_content = "O que um Lin pode fazer, Mu Yuebai também pode fazer.",
  ui_story_5038_50381501_168_dialog_content = "Sim, senhor.",
  ui_story_5038_50381501_169_dialog_content = "Agora, chega de tagarelice da minha parte.",
  ui_story_5038_50381501_170_dialog_content = "Está frio lá fora. Por que vocês não entram e desfrutam de uma boa refeição?",
  ui_story_5038_50381501_171_dialog_content = "Sim, o que ainda estamos esperando? O Guildmaster falou!",
  ui_story_5038_50381501_172_dialog_content = "Vamos, podemos conversar lá dentro!",
  ui_story_5038_50381501_173_dialog_content = "<color=#e8d9bb>Embaralhar, embaralhar...</color>",
  ui_story_5038_50381501_174_dialog_content = "Devo entrar também?",
  ui_story_5038_50381501_175_dialog_content = "É claro. Por que, você tem um lugar para estar?",
  ui_story_5038_50381501_176_dialog_content = "Não mas...",
  ui_story_5038_50381501_177_dialog_content = "Eu me sinto estranho roubando uma refeição da guilda como um estranho...",
  ui_story_5038_50381501_178_dialog_content = "Um estranho? Não depois que você ajudou o Shadowind em todo aquele problema!",
  ui_story_5038_50381501_179_dialog_content = "Olha, todo mundo já está se enchendo.",
  ui_story_5038_50381501_180_dialog_content = "Bom vinho e boa cozinha... Não precisa de me perguntar duas vezes!",
  ui_story_5038_50381501_181_dialog_content = "As ricas mesas domésticas devem ser preenchidas com todos os tipos de coisas deliciosas! Vamos Jiu!",
  ui_story_5038_50381501_182_dialog_content = "Cuidado ao ultrapassar a soleira, Alteza!",
  ui_story_5038_50381501_183_dialog_content = "Uau, todos eles desapareceram em um piscar de olhos...",
  ui_story_5038_50381501_184_dialog_content = "É por isso que eu disse para você não se preocupar.",
  ui_story_5038_50381501_185_dialog_content = "Sinta-se à vontade para ficar aqui durante o seu tempo em Longzhou.",
  ui_story_5038_50381501_186_dialog_content = "Quando o Shadowind navegar novamente, eu o escoltarei de volta ao Astra.",
  ui_story_5038_50381501_187_dialog_content = "Ficar com os Lins? Eu não deveria incomodá-lo...",
  ui_story_5038_50381501_188_dialog_content = "Oh, por favor. Não vá pegar a polidez estereotipada de Longzhou agora.",
  ui_story_5038_50381501_189_dialog_content = "Entre antes que a comida acabe.",
  ui_story_5038_50381501_190_dialog_content = "(Longzhou é um lugar muito turbulento e movimentado.)",
  ui_story_5038_50381501_191_dialog_content = "(Ninguém jamais poderia se sentir sozinho em meio às multidões animadas.)",
  ui_story_5038_50381501_192_dialog_content = "<color=#e8d9bb>Vários dias depois</color>",
  ui_story_5038_50381501_193_dialog_content = "Ir para o Shadowind? Agora?",
  ui_story_5038_50381501_194_dialog_content = "Sim, Yuebai reuniu todos juntos. Você é a última pessoa.",
  ui_story_5038_50381501_195_dialog_content = "Mas eu não quero fazer outra viagem, então por que eu deveria ir?",
  ui_story_5038_50381501_196_dialog_content = "Não se preocupe, não é outra viagem. Não estamos abduzindo você para o Astra.",
  ui_story_5038_50381501_197_dialog_content = "Ela também não me contou os detalhes, então acho que vamos descobrir!",
  ui_story_5038_50381501_198_dialog_content = "Tudo bem, eu vou, já que não estamos muito longe do cais.",
  ui_story_5038_50381501_199_dialog_content = "Esse é o espírito!",
  ui_story_5038_50381501_200_dialog_content = "Como Longzhou está tratando você, PlayerName? Se divertindo?",
  ui_story_5038_50381501_201_dialog_content = "Ainda é um pouco novo para mim e estou nervoso em falar com os locais.",
  ui_story_5038_50381501_202_dialog_content = "Além disso, não faço ideia para onde ir.",
  ui_story_5038_50381501_203_dialog_content = "Nossa, parece que os Lins não são bons anfitriões.",
  ui_story_5038_50381501_204_dialog_content = "Venha me ver mais tarde, e eu lhe mostrarei o lugar.",
  ui_story_5038_50381501_205_dialog_content = "Claro, isso parece ótimo!",
  ui_story_5038_50381501_206_dialog_content = "Aliás, tem uma coisa...",
  ui_story_5038_50381501_207_dialog_content = "O que foi?",
  ui_story_5038_50381501_208_dialog_content = "Trouxe uma carta comigo para Longzhou.",
  ui_story_5038_50381501_209_dialog_content = "Passei os últimos dois dias tentando localizar o endereço do destinatário, mas não consegui.",
  ui_story_5038_50381501_210_dialog_content = "E ontem, sem querer, derramei água no envelope.",
  ui_story_5038_50381501_211_dialog_content = "O selo de cera se dissolveu e uma pilha de <color=#FFB400>papel vermelho</color> voou.",
  ui_story_5038_50381501_212_dialog_content = "Papel vermelho?!",
  ui_story_5038_50381501_213_dialog_content = "Sim. Pareciam recortes de borboletas. Eles se reuniram e voaram para longe.",
  ui_story_5038_50381501_214_dialog_content = "Não havia mais nada no envelope. Não tenho certeza se isso conta como entregue.",
  ui_story_5038_50381501_215_dialog_content = "Hum...",
  ui_story_5038_50381501_216_dialog_content = "Alguma opinião sobre isso, Tianxian?",
  ui_story_5038_50381501_217_dialog_content = "Intrigante...",
  ui_story_5038_50381501_218_dialog_content = "Não se preocupe com isso. O remetente obteve seu desejo.",
  ui_story_5038_50381501_X218_dialog_content = "Borboletas adoram flores. Eles encontrarão seu destino.",
  ui_story_5038_50381501_219_dialog_content = "A sua parte está feita.",
  ui_story_5038_50381501_220_dialog_content = "É isso? Bem desse jeito?",
  ui_story_5038_50381501_221_dialog_content = "De nada.",
  ui_story_5038_50381501_X221_dialog_content = "Nunca esperei que chegasse aqui, do outro lado do mar.",
  ui_story_5038_50381501_X222_dialog_content = "<size=35>Bênçãos e infortúnios existem em conjunto. Com certeza, nossa abençoada sobrevivência não se manifestou do nada.</size>",
  ui_story_5038_50381501_X223_dialog_content = "<size=35>Agora...</size>",
  ui_story_5038_50381501_X224_dialog_content = "O que? O que você quer dizer?",
  ui_story_5038_50381501_X225_dialog_content = "Nada, esquece. Eu estava falando sozinho.",
  ui_story_5038_50381501_222_dialog_content = "Ei, aqui está o cais.",
  ui_story_5038_50381501_223_dialog_content = "Vamos, depressa.",
  ui_story_5038_50381501_224_dialog_content = "Os pregos são martelados?",
  ui_story_5038_50381501_225_dialog_content = "Sim! Alguém precisa de sobras de unhas?",
  ui_story_5038_50381501_226_dialog_content = "Olha, aqui vêm as duas últimas pessoas!",
  ui_story_5038_50381501_227_dialog_content = "Estávamos esperando por você.",
  ui_story_5038_50381501_228_dialog_content = "Todos estão aqui agora, capitão!",
  ui_story_5038_50381501_229_dialog_content = "Todos presentes?",
  ui_story_5038_50381501_230_dialog_content = "Ok, vamos ao que interessa.",
  ui_story_5038_50381501_231_dialog_content = "O que estamos fazendo aqui, capitão?",
  ui_story_5038_50381501_232_dialog_content = "Já passamos por muita coisa juntos.",
  ui_story_5038_50381501_233_dialog_content = "Portanto, vamos testemunhar este momento juntos.",
  ui_story_5038_50381501_234_dialog_content = "Este momento?",
  ui_story_5038_50381501_235_dialog_content = "Capitão!",
  ui_story_5038_50381501_236_dialog_content = "Os reparos são feitos. Todas as verificações concluídas.",
  ui_story_5038_50381501_237_dialog_content = "O Shadowind está como novo!",
  ui_story_5038_50381501_238_dialog_content = "<size=45>Viva!</size>",
  ui_story_5038_50381501_239_dialog_content = "Uau! O navio está consertado!",
  ui_story_5038_50381501_240_dialog_content = "Sim. Finalmente.",
  ui_story_5038_50381501_241_dialog_content = "Agora ela realmente completou sua jornada.",
  ui_story_5038_50381501_242_dialog_content = "Sua viagem tem sido um ciclo interminável de danos e reparos. Hoje, finalmente acabou.",
  ui_story_5038_50381501_243_dialog_content = "Esta jornada chegou a um final satisfatório.",
  ui_story_5038_50381501_244_dialog_content = "Isso é ótimo! Eu quase esqueci como o Shadowind parecia originalmente!",
  ui_story_5038_50381501_245_dialog_content = "Tudo novo e polido, não tem nem um arranhão... é um pouco difícil de acostumar.",
  ui_story_5038_50381501_246_dialog_content = "Sinta-se à vontade para explorar mais tarde.",
  ui_story_5038_50381501_247_dialog_content = "Mas, por enquanto, preciso que todos vocês façam mais uma coisa.",
  ui_story_5038_50381501_248_dialog_content = "O que foi?",
  ui_story_5038_50381501_249_dialog_content = "É costume dos artesãos gravar seu nome no trabalho de que mais se orgulham.",
  ui_story_5038_50381501_250_dialog_content = "Por mais reparos que fizemos durante a viagem, todos aqui tiveram um papel importante para trazer o navio de volta à sua antiga glória.",
  ui_story_5038_50381501_251_dialog_content = "Eu gostaria de ver seus nomes adornando este novíssimo Shadowind.",
  ui_story_5038_50381501_252_dialog_content = "Vamos gravar nossos nomes na icônica e tradicional \"orelha de coelho\".",
  ui_story_5038_50381501_253_dialog_content = "Oh, isso parece divertido!",
  ui_story_5038_50381501_254_dialog_content = "Boa ideia! Eu amo isso!",
  ui_story_5038_50381501_255_dialog_content = "Espero que ninguém se importe com meu péssimo roteiro...",
  ui_story_5038_50381501_256_dialog_content = "Vejo que todos estão de acordo.",
  ui_story_5038_50381501_257_dialog_content = "Então, vamos começar com nosso amigo do exterior.",
  ui_story_5038_50381501_258_dialog_content = "Você está falando de mim?!",
  ui_story_5038_50381501_259_dialog_content = "Sim. É costume que os convidados cheguem primeiro em Longzhou.",
  ui_story_5038_50381501_260_dialog_content = "Aqui está o cinzel. Grave seu nome onde preferir.",
  ui_story_5038_50381501_261_dialog_content = "Isso é um pouco estranho.",
  ui_story_5038_50381501_262_dialog_content = "E acho que ninguém consegue ler meu nome...",
  ui_story_5038_50381501_263_dialog_content = "Isso é ainda melhor. Não saberemos se você errar!",
  ui_story_5038_50381501_264_dialog_content = "É um privilégio ir primeiro. Você pode escolher o melhor e mais proeminente local.",
  ui_story_5038_50381501_265_dialog_content = "Sim, o que há para ser estranho?",
  ui_story_5038_50381501_266_dialog_content = "Ok, tudo bem...",
  ui_story_5038_50381501_267_dialog_content = "Vou começar então.",
  ui_story_5038_50381501_268_dialog_content = "Sim, faça isso.",
  ui_story_5038_50381501_269_dialog_content = "(Mão, segure o cinzel ainda e não agite.)",
  ui_story_5038_50381501_270_dialog_content = "(Vamos com este ponto na borda aqui.)",
  ui_story_5038_50381501_271option_content = "PlayerName",
  ui_story_5038_50381501_272_dialog_content = "Ai está! Isso parece ótimo!",
  ui_story_5038_50381501_273_dialog_content = "Faça-o maior para que possamos vê-lo!",
  ui_story_5038_50381501_274_dialog_content = "(Ninguém pode deixar uma marca no oceano.)",
  ui_story_5038_50381501_275_dialog_content = "(Tudo em sua superfície é efêmero, sejam águas calmas ou ondas turbulentas.)",
  ui_story_5038_50381501_276_dialog_content = "(No entanto, sempre haverá aqueles que tentam.)",
  ui_story_5038_50381501_277_dialog_content = "(Tente, como eu, gravar o nome deles onde possa permanecer para sempre.)",
  ui_story_5038_50381501_278_dialog_content = "(Acompanhará o Shadowind enquanto ele viaja entre os continentes.)",
  ui_story_5038_50381501_279_dialog_content = "(Não tem magnitude para mudar o mar.)",
  ui_story_5038_50381501_280_dialog_content = "(Mas talvez para alguns, meu nome se torne sinônimo de suas águas.)",
  ui_story_5038_50381501_281_dialog_content = "PlayerName",
  ui_story_5038_50381501_282_dialog_content = "Continua..."
}
return config
